#!/usr/bin/env python3
"""Erzeugt fünf Steuerrechts- und zehn BGB-Alltagsakten aus Primärunterlagen."""

from __future__ import annotations

import importlib.util
from dataclasses import dataclass
from pathlib import Path


REPO = Path(__file__).resolve().parent.parent
BASE_PATH = REPO / "scripts" / "build-prioritaere-schulungsakten.py"
SPEC = importlib.util.spec_from_file_location("prioritaere_akten", BASE_PATH)
assert SPEC and SPEC.loader
P = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(P)


@dataclass(frozen=True)
class CaseMeta:
    slug: str
    title: str
    plugins: tuple[str, ...]
    summary: str
    closing: str
    checks: tuple[tuple[str, str], ...]


def record(
    directory: Path,
    filename: str,
    *,
    org: str,
    strapline: str,
    contact: str,
    title: str,
    metadata: list[tuple[str, str]],
    sections: list[tuple[str, list[str]]],
    tables: list[tuple[str, list[str], list[list[str]], list[float] | None]] | None = None,
    signer: str | None = None,
    signer_role: str | None = None,
) -> None:
    P.write_record(
        directory / filename,
        org=org,
        strapline=strapline,
        contact=contact,
        title=title,
        metadata=metadata,
        sections=sections,
        tables=tables,
        signer=signer,
        signer_role=signer_role,
    )


def email(directory: Path, filename: str, **kwargs) -> None:
    P.write_email(directory / filename, **kwargs)


def finish(
    directory: Path,
    meta: CaseMeta,
    files: list[tuple[str, str]],
) -> None:
    P.write_readme(
        directory,
        meta.title,
        [f"`{plugin}`" for plugin in meta.plugins],
        meta.summary,
        files,
        meta.closing,
    )
    lines = [
        f"name: {meta.slug}",
        f"plugin: {P.yaml_quote(meta.plugins[0])}",
        f"description: {P.yaml_quote(meta.summary)}",
        "checks:",
        "  - id: dateien",
        "    check_type: working_file_count",
        f"    description: Mindestens {len(files)} exportierbare Primärunterlagen vorhanden",
        f"    min: {len(files)}",
    ]
    for check_id, description in meta.checks:
        lines.extend(
            [
                f"  - id: {check_id}",
                "    check_type: human_review",
                f"    description: {P.yaml_quote(description)}",
            ]
        )
    (directory / "rubric.yaml").write_text("\n".join(lines) + "\n", encoding="utf-8")


