def build_steuer_ingenieurbuero() -> None:
    meta = CaseMeta(
        slug="steuer-ingenieurbuero-freiberuf-gewerbe-koblenz",
        title="Steuerrecht: Ingenieurbüro zwischen Planung und Produktgeschäft in Koblenz",
        plugins=("steuerrecht-anwalt-und-berater", "solo-selbststaendige-praxis"),
        summary="Diplom-Ingenieurin Eva Langen betreibt mit drei Mitarbeitern ein Büro für Tragwerksplanung. Neben persönlich verantworteten Gutachten verkauft sie ein selbst entwickeltes Messmodul, vergibt Softwarelizenzen und lässt Routineauswertungen von Mitarbeitern erstellen; das Finanzamt hinterfragt Einkunftsart, Gewinnermittlung und Umsatzsteuer.",
        closing="Projektverträge, Leistungszeiten, Rechnungen, Personalzuordnung und Zahlungsdaten zeigen, wie eng Beratung, Planung, Software und Hardware zusammenlaufen. Die rechtliche und steuerliche Abgrenzung bleibt der Bearbeitung überlassen.",
        checks=(("einkunftsart", "Paragrafen 15 und 18 EStG projektbezogen auf eigenverantwortliche Ingenieurleistung, Mitarbeiterarbeit, Software und Warenverkauf anwenden."), ("trennung", "Prüfen, ob Tätigkeiten organisatorisch und rechnungsmäßig trennbar sind; Verträge und Zeiterfassung als Primärquellen nutzen."), ("umsatzsteuer", "Lieferungen, sonstige Leistungen, Leistungsorte und Anzahlungen aus Rechnungen und Konten abgleichen."), ("gewinnermittlung", "Bestände an Messmodulen, Aktivierung eigener Entwicklung und Einnahmen-Überschuss-Rechnung zeitlich prüfen.")),
    )
    d = P.prepare(meta.slug)
    contact = "Casinostraße 38 · 56068 Koblenz\nTelefon 0261 973 42 10 · planung@langen-tragwerk.de\nSteuernummer 22/118/08741 · IBAN DE45 5705 0120 0048 1192 31"
    fa = "Ferdinand-Sauerbruch-Straße 17 · 56073 Koblenz\nTelefon 0261 4931 0 · Fax 0261 4931 190\nPostfach 20 10 55 · 56010 Koblenz"
    record(d, "01_auskunftsersuchen_einkunftsart.docx", org="Finanzamt Koblenz", strapline="Veranlagungsbezirk Selbständige", contact=fa, title="Bitte um Ergänzung zur Einkommensteuererklärung 2025", metadata=[("Steuernummer", "22/118/08741"), ("Aktenzeichen", "VZ-25-Langen-118"), ("Datum", "19.05.2026"), ("Frist", "12.06.2026")], sections=[("1. Erklärte Tätigkeit", ["In der Anlage S wurden Einkünfte aus selbständiger Arbeit in Höhe von 146820 EUR erklärt. Aus der Umsatzsteuererklärung ergeben sich zugleich Erlöse aus dem Verkauf von Messmodulen, wiederkehrende Lizenzentgelte für die Software SpanCheck und Leistungen von drei Arbeitnehmern. Bitte erläutern Sie Art, Umfang und organisatorische Abwicklung dieser Tätigkeiten.", "Reichen Sie eine Aufteilung der Umsätze nach Tragwerksplanung, Gutachten, Softwarelizenz, Messmodulverkauf und Schulung ein. Aus den vorliegenden Rechnungen ist nicht stets erkennbar, wer die fachliche Leistung erbracht und wer die abschließende Prüfung verantwortet hat."]), ("2. Gewinnermittlung und Bestände", ["Die Einnahmen-Überschuss-Rechnung enthält Entwicklungskosten von 68400 EUR als laufenden Aufwand. Nach der Inventurliste befanden sich am 31.12.2025 noch 37 Messmodule und 14 Sensorköpfe im Büro. Bitte übersenden Sie Einkaufsbelege, Entwicklungsvertrag, Lagerliste und Erläuterung der Bilanzierungsentscheidung.", "Für die Zahlung der Rheinbrücke Projekt GmbH über 28560 EUR am 4. Januar 2026 ist die Rechnung vom 18. Dezember 2025 beigefügt. Bitte geben Sie an, wann die Leistung abgenommen und wann der Betrag wirtschaftlich verfügbar war."])], signer="Maren Schlüter", signer_role="Steueroberinspektorin")
    record(d, "02_rahmenvertrag_tragwerksmonitoring.docx", org="Langen Tragwerk und Monitoring", strapline="Dipl.-Ing. Eva Langen · Beratende Ingenieurin", contact=contact, title="Rahmenvertrag Brückenmonitoring Moselbogen", metadata=[("Vertrag", "LT-25-044"), ("Auftraggeber", "Rheinbrücke Projekt GmbH, Andernach"), ("Laufzeit", "01.03.2025 bis 28.02.2027"), ("Nettohöchstwert", "248000 EUR")], sections=[("1. Leistungen", ["Eva Langen übernimmt die statische Konzeption, Auswahl der Messpunkte, Plausibilitätsprüfung der Messreihen und Freigabe der Quartalsberichte. Das Büro installiert zwölf Messmodule LM-4 am Bauwerk. Rohdaten werden automatisiert an SpanCheck übertragen. Mitarbeiterin Lena Kapp betreut Installation und Datenbereinigung; Bauingenieur Fabian Kurz erstellt erste Diagramme.", "Die Auftraggeberin erhält einen Zugang zur Software, jedoch kein ausschließliches Nutzungsrecht. Für jedes aktive Messmodul werden monatlich 145 EUR Serviceentgelt berechnet. Defekte Module tauscht das Büro aus einem eigenen Bestand aus. Module bleiben im Eigentum von Eva Langen, sofern eine Einzelbestellung nichts anderes bestimmt."]), ("2. Abnahme und Verantwortung", ["Quartalsberichte gelten zehn Werktage nach Zugang als abgenommen, wenn keine konkreten Messfehler bezeichnet werden. Die fachliche Schlussfolgerung trägt den Freigabevermerk Eva Langen. Bei Abwesenheit darf Fabian Kurz lediglich Rohdatenberichte versenden. Alarmmeldungen über Grenzwertüberschreitungen gehen parallel an Auftraggeberin und Eva Langen.", "Die Rechnung trennt Konzeptionsstunden, Installationspauschale, Modulmiete und Softwarezugang. Reisekosten werden nach Beleg abgerechnet. Die Parteien führen für jedes Bauwerk ein Übergabeprotokoll mit Seriennummer, Messpunkt und Kalibrierstand."])], signer="Eva Langen", signer_role="Diplom-Ingenieurin")
    record(d, "03_produktblatt_spancheck_module.docx", org="Langen Tragwerk und Monitoring", strapline="Messsystem SpanCheck / LM-4", contact=contact, title="Produkt- und Leistungsbeschreibung", metadata=[("Stand", "15.01.2025"), ("Produkt", "Messmodul LM-4"), ("Software", "SpanCheck 3.2"), ("Vertrieb", "Direktverkauf und projektbezogene Überlassung")], sections=[("1. Messmodul", ["Das LM-4 besteht aus zugekauftem Sensorkopf, industriellem Datenlogger, vorkonfigurierter Mobilfunkkarte und einem im Büro gefertigten Gehäuse. Kalibrierung und Montage erfolgen projektbezogen. Der Einkaufspreis der Komponenten liegt je nach Sensor zwischen 610 und 880 EUR; der Listenverkaufspreis beträgt 1890 EUR netto.", "Im Jahr 2025 wurden 64 Module eingekauft oder montiert. 18 wurden an zwei Ingenieurbüros verkauft, neun an die Stadtwerke Neuwied vermietet und weitere Module in eigenen Monitoringprojekten eingesetzt. Rückläufer werden geprüft und teilweise erneut ausgegeben."]), ("2. Software und Auswertung", ["SpanCheck importiert Rohdaten, erzeugt Schwellenwertmeldungen und stellt Diagramme bereit. Die Programmierung stammt überwiegend von Codehafen UG auf Grundlage eines Lastenhefts von Eva Langen. Das Büro vergibt Jahreszugänge für 960 EUR je Nutzer. Ein Zugang umfasst Support per E-Mail, aber keine fachliche Bewertung der Messkurven.", "Für Tragwerksgutachten werden Messdaten erst nach Sichtung von Bauunterlagen und Randbedingungen verwendet. Die Softwareausgabe trägt den Hinweis Datenreport; der von Eva Langen unterschriebene Bericht trägt die Bezeichnung fachtechnische Stellungnahme."])], signer="Eva Langen", signer_role="Inhaberin")
    record(d, "04_personaleinsatz_freigaben_2025.docx", org="Langen Tragwerk und Monitoring", strapline="Interne Projektorganisation", contact=contact, title="Personal- und Freigaberegelung 2025", metadata=[("Team", "Eva Langen / Lena Kapp / Fabian Kurz / Mira Enders"), ("Gültig", "ab 01.02.2025"), ("Ablage", "QM 3.4"), ("Freigabe", "Eva Langen")], sections=[("1. Rollen", ["Eva Langen akquiriert Aufträge, legt statische Modelle fest, führt Ortstermine bei wesentlichen Schäden durch und unterschreibt Gutachten. Fabian Kurz, Master Bauingenieurwesen, erstellt Berechnungsmodelle und Entwürfe. Lena Kapp, Technikerin, montiert Sensoren und kontrolliert Datenimporte. Mira Enders bearbeitet Rechnungen, Lizenzen und Versand.", "Bei 16 Kurzberichten im Herbst 2025 erfolgte die Freigabe per Mobiltelefon, weil Eva Langen auf einer Baustelle in Luxemburg war. In der Dokumentenablage ist nur das Kürzel EL vermerkt. Fabian Kurz erklärte in einer E-Mail, dass er zwei Berichte wegen einer drohenden Sperrung bereits an den Kunden versandt habe, bevor die Rückmeldung einging."]), ("2. Zeiterfassung", ["Arbeitszeiten werden nach Projekt und Tätigkeit gebucht. Der Code FACH umfasst Modellwahl, Plausibilisierung und Schlussfolgerung; DATEN umfasst Import und Diagramm; PRODUKT umfasst Montage, Kalibrierung und Versand. Für interne Softwareentwicklung gibt es den Code DEV.", "Die Monatsauswertung November weist Eva Langen 42 FACH-Stunden, Fabian Kurz 116 FACH-Stunden und 38 DATEN-Stunden aus. Eine nachträgliche Umbuchung von 24 Stunden vom Projekt Moselbogen auf DEV erfolgte am 12. Januar 2026."])], signer="Eva Langen", signer_role="Inhaberin")
    record(d, "05_stellungnahme_steuerkanzlei_sachverhalt.docx", org="Steuerkanzlei Konrad & Lenz", strapline="Steuerberaterinnen · Jahresabschluss · Unternehmenssteuerrecht", contact="Löhrstraße 119 · 56068 Koblenz\nTelefon 0261 921 08 30 · kanzlei@konrad-lenz.de\nPartnerschaftsregister PR 224 AG Koblenz", title="Sachverhaltsdarstellung für die Besprechung", metadata=[("Mandat", "Eva Langen / 2025"), ("Aktenzeichen", "KL-EL-2026-31"), ("Datum", "03.06.2026"), ("Bearbeitung", "StB Judith Konrad")], sections=[("1. Unterlagenstand", ["Vorliegen: Einkommensteuer- und Umsatzsteuererklärungen 2025, EÜR, Ausgangsrechnungen, Rahmenvertrag Moselbogen, Produktliste und Zeiterfassung. Noch nicht vollständig vorliegen die Verträge mit Codehafen UG, Seriennummernliste der Module und Freigabeverläufe für die im November versandten Kurzberichte.", "Die Buchhaltung verwendet ein gemeinsames Bankkonto und einen einheitlichen Nummernkreis. Rechnungen weisen einzelne Leistungszeilen aus, aber keine gesonderten Kostenstellen. Die Website bezeichnet das Büro zugleich als Ingenieurbüro und Anbieter des SpanCheck-Messsystems."]), ("2. Offene Tatsachenfragen", ["Zu klären ist, ob die 18 verkauften Module stets mit Installation oder auch ohne weitere Ingenieurleistung geliefert wurden. Bei den Stadtwerken Neuwied wurden Module vermietet; monatliche Reports erstellte Lena Kapp. Eva Langen nahm nach eigener Angabe nur bei Grenzwertmeldungen eine fachliche Prüfung vor.", "Weiter fehlen genaue Zeitpunkte für Abnahme und Zahlung des Moselbogen-Berichts Dezember 2025. Die Bankgutschrift am 4. Januar 2026 war am selben Tag verfügbar. Der Kunde hatte am 22. Dezember per E-Mail zwei Diagrammbezeichnungen beanstandet, den statischen Inhalt aber nicht kommentiert."])], signer="Judith Konrad", signer_role="Steuerberaterin")
    email(d, "06_email_kunde_report_freigabe.eml", sender="nora.hardenberg@rheinbruecke-projekt.de", recipients=["eva.langen@langen-tragwerk.de"], cc=["fabian.kurz@langen-tragwerk.de"], date="Mon, 22 Dec 2025 11:08:00 +0100", subject="LT-25-044 / Quartalsreport Q4 – zwei Beschriftungen und Zahlung", message_id="<rbp-lt-25-044-q4-202512221108@rheinbruecke-projekt.de>", body="Guten Morgen Frau Langen,\n\nwir haben den Report Q4 am Freitag erhalten. Inhaltlich hat unser Bauleiter derzeit keine Rückfrage zu den Schwellenwerten. In Abbildung 7 sind jedoch Nordlager und Südlager vertauscht; außerdem zeigt die Legende Millimeter pro Minute, während im Text Millimeter pro Stunde steht. Herr Kurz hatte zugesagt, heute eine korrigierte Datei zu senden.\n\nUnsere Buchhaltung hat Rechnung LT-2025-188 über 28560 EUR zur Zahlung am 2. Januar angewiesen. Wegen des Bankfeiertags kann die Gutschrift erst danach sichtbar sein. Die Korrektur der Beschriftungen hält die Zahlung nicht auf. Bitte senden Sie die neue Fassung an alle Empfänger und lassen Sie die ursprüngliche Version im Projektraum stehen.\n\nFreundliche Grüße\nNora Hardenberg\nKaufmännische Projektleitung\nRheinbrücke Projekt GmbH\nKonrad-Adenauer-Allee 14, 56626 Andernach\nTelefon 02632 884 219")
    email(d, "07_email_modulverkauf_ohne_planung.eml", sender="einkauf@statikbuero-bergwald.de", recipients=["vertrieb@langen-tragwerk.de"], cc=["mira.enders@langen-tragwerk.de"], date="Thu, 6 Nov 2025 16:37:00 +0100", subject="Bestellung 8 Messmodule LM-4 ohne Montage / Angebot 25-119", message_id="<bestellung-25-119-202511061637@statikbuero-bergwald.de>", body="Sehr geehrte Frau Enders,\n\nwir bestellen acht Messmodule LM-4 zum Stückpreis von 1890 EUR netto gemäß Angebot 25-119. Montage, Messkonzept und fachliche Auswertung führen wir selbst durch. Bitte programmieren Sie nur die von uns übermittelte Abtastrate und legen Sie die Kalibrierprotokolle sowie eine Liste der Seriennummern bei. Einen SpanCheck-Zugang benötigen wir für zwei Nutzer ab 1. Dezember.\n\nDie Lieferung soll an unsere Baustelle in Gießen gehen. Herr Bergwald möchte vor Versand ein zwanzigminütiges Gespräch mit Frau Langen zur Positionierung der Dehnungssensoren; falls dies nicht im Produktpreis enthalten ist, teilen Sie die Kosten bitte vorab mit. Zahlung erfolgt vierzehn Tage nach vollständiger Lieferung.\n\nMit freundlichen Grüßen\nAlina Förster\nEinkauf und Projektassistenz\nStatikbüro Bergwald Partnerschaft\nLudwigstraße 28, 35390 Gießen\nTelefon 0641 209 77 14")
    P.write_txt(d / "08_chat_team_freigabe_november.txt", """Teams-Export · Kanal Moselbogen · 18.11.2025 bis 20.11.2025

18.11. 15:22 Fabian Kurz: Q4-Rohreport ist fertig. Zwei Sensoren hatten am Sonntag Funklöcher, Werte sind nachgezogen und markiert.
18.11. 16:04 Eva Langen: Ich bin bis Donnerstag in Luxemburg. Bitte Modellannahmen und Schwellenwerttabelle offenlassen, ich prüfe abends.
19.11. 08:17 Lena Kapp: Kunde drängt wegen Sitzung um 11 Uhr. Diagramme kann ich schicken, aber die Schlussseite trägt noch EL.
19.11. 08:25 Fabian Kurz: Ich sende einen Datenreport ohne Schlussseite. Betreff klar als vorläufig.
19.11. 10:48 Fabian Kurz: Kunde hat angerufen. Er wollte genau die Ampel. Ich habe Version 0.8 mit dem EL-Kürzel aus der Vorlage geschickt und dazugeschrieben, Freigabe folgt.
19.11. 18:56 Eva Langen: Gesehen. Schwelle Sensor 4 bitte von 0.34 auf 0.31 korrigieren. Begründung steht im Ortsterminprotokoll vom 7. Oktober.
20.11. 07:34 Fabian Kurz: Version 0.9 versandt. Im System steht Freigabe EL, weil ich dein Chat-Okay hinterlegt habe.
20.11. 08:02 Eva Langen: Bitte künftig den Chat als Anlage speichern. Für heute passt die Korrektur. Die statische Schlussfolgerung ergänze ich nach Rückkehr.
""")
    P.write_csv(d / "09_umsatzaufteilung_2025.csv", ["Rechnung", "Datum", "Kunde", "Leistungsart", "Netto_EUR", "Bearbeiter", "Freigabe", "Zahlung"], [["LT-2025-041", "2025-03-28", "Rheinbrücke Projekt GmbH", "Konzeption und Installation", "38400", "Langen/Kapp", "EL", "2025-04-11"], ["LT-2025-077", "2025-06-30", "Stadtwerke Neuwied", "Modulmiete und Datenreport", "11280", "Kapp", "EL", "2025-07-15"], ["LT-2025-119", "2025-09-12", "Statikbüro Bergwald", "Verkauf 10 LM-4", "18900", "Enders", "", "2025-09-25"], ["LT-2025-144", "2025-10-31", "Stadt Koblenz", "Tragwerksgutachten", "44200", "Langen/Kurz", "EL", "2025-11-18"], ["LT-2025-166", "2025-11-28", "Statikbüro Bergwald", "SpanCheck Lizenzen", "1920", "Enders", "automatisch", "2025-12-10"], ["LT-2025-188", "2025-12-18", "Rheinbrücke Projekt GmbH", "Quartalsbericht und Service", "28560", "Kurz/Langen", "EL nach Versand", "2026-01-04"]])
