    files = [("01_auskunftsersuchen_einkunftsart.docx", "Finanzamt fragt Einkunftsart, Erlösaufteilung und Bestände ab"), ("02_rahmenvertrag_tragwerksmonitoring.docx", "Kundenvertrag mit Planung, Modulen, Software und Freigabe"), ("03_produktblatt_spancheck_module.docx", "Produktgeschäft und Softwarezugang im Einzelnen"), ("04_personaleinsatz_freigaben_2025.docx", "Rollen, Freigaben und Zeiterfassung des kleinen Teams"), ("05_stellungnahme_steuerkanzlei_sachverhalt.docx", "Quellenbezogene Sachverhaltsaufnahme der Kanzlei"), ("06_email_kunde_report_freigabe.eml", "Kundenmail zu Korrektur und Zahlung über den Jahreswechsel"), ("07_email_modulverkauf_ohne_planung.eml", "Bestellung von Messmodulen ohne Montageleistung"), ("08_chat_team_freigabe_november.txt", "Teamchat zur fachlichen Freigabe eines Reports"), ("09_umsatzaufteilung_2025.csv", "Rechnungsdaten nach Leistungsart und Bearbeiter"), ("10_zeiterfassung_projektcodes.csv", "Projektstunden und nachträgliche Umbuchung"), ("11_foto_modullager_seriennummern.jpg", "Fotodokumentation des Modulbestands")]
