def build_steuer_heizungsbau_gmbh() -> None:
    meta = CaseMeta(
        slug="steuer-heizungsbau-gmbh-vga-lohnsteuer-bamberg",
        title="Steuerrecht: Kleine Heizungsbau-GmbH und Gesellschafternähe in Bamberg",
        plugins=("steuerrecht-anwalt-und-berater", "gesellschaftsrecht"),
        summary="Die Mertens Wärmebau GmbH beschäftigt sechs Arbeitnehmer. Alleingesellschafter und Geschäftsführer Henrik Mertens vermietet der GmbH eine Halle, fährt einen Firmenwagen, erhält eine Tantieme und lässt seine Ehefrau Büroarbeiten erledigen; zugleich bestehen ein Gesellschafterdarlehen und private Materialentnahmen.",
        closing="Verträge, Beschlüsse, Lohnkonto, Fahrten, Mietzahlungen, Darlehensbewegungen und Materiallisten zeigen denselben Betrieb aus mehreren Blickwinkeln. Widersprüche bleiben sichtbar und werden nicht durch eine fertige steuerliche Würdigung aufgelöst.",
        checks=(("vga", "Paragraf 8 Absatz 3 Satz 2 KStG auf Gehalt, Tantieme, Pkw, Hallenmiete und private Materialentnahmen jeweils gesondert anwenden."), ("fremdvergleich", "Zeitpunkt, Schriftform, Durchführung und Fremdvergleich der Verträge mit Gesellschafter und nahestehender Person anhand der Primärbelege prüfen."), ("darlehen", "Darlehensvaluta, Zinsbuchungen, Tilgungen und Liquiditätslage rechnerisch abstimmen."), ("lohnsteuer", "Arbeitsleistung der Ehefrau, Fahrzeugnutzung und Reisekosten mit Lohnunterlagen und tatsächlicher Durchführung vergleichen.")),
    )
    d = P.prepare(meta.slug)
    company = "Laubanger 12 · 96052 Bamberg\nTelefon 0951 208 71 40 · Fax 0951 208 71 49\nbuero@mertens-waermebau.de · HRB 10844 AG Bamberg"
    fa = "Martin-Luther-Straße 1 · 96050 Bamberg\nTelefon 0951 84 0 · Fax 0951 84 1199\nSteuernummer 207/132/40518"
    record(d, "01_pruefungsanordnung_koerperschaft_lohn.docx", org="Finanzamt Bamberg", strapline="Betriebsprüfung und Lohnsteuer-Außenprüfung", contact=fa, title="Prüfungsanordnung", metadata=[("Aktenzeichen", "BP-207/132/40518-26"), ("Steuerpflichtige", "Mertens Wärmebau GmbH"), ("Zeitraum", "2023 bis 2025"), ("Prüfungsbeginn", "07.09.2026, 09:00 Uhr")], sections=[("1. Prüfungsumfang", ["Geprüft werden Körperschaftsteuer, Gewerbesteuer und Umsatzsteuer 2023 bis 2025 sowie Lohnsteuer vom 1. Januar 2024 bis 31. Dezember 2025. Als Prüfungsort ist zunächst der Betrieb Laubanger 12 vorgesehen. Ansprechpartnerin ist Betriebsprüferin Karin Waldner.", "Bereitzustellen sind Finanzbuchhaltung einschließlich Buchungsstapel, Jahresabschlüsse, Gesellschafterbeschlüsse, Geschäftsführeranstellungsvertrag, Tantiemeberechnungen, Miet- und Darlehensverträge, Fahrzeugunterlagen, Lohnkonten sowie Vereinbarungen mit Angehörigen."]), ("2. Vorabfragen", ["Aus dem Kontennachweis ergeben sich monatliche Hallenmieten an Henrik Mertens, Zinsaufwand aus einem Gesellschafterdarlehen und Aufwendungen für den BMW X5 BA-MW 810. Bitte halten Sie Nachweise über betriebliche und private Nutzung sowie die Kalkulation der vereinbarten Miete bereit.", "Auf dem Konto Fremdleistungen wurden Zahlungen an Sabine Mertens erfasst. Für Dezember 2025 ist zusätzlich eine Sonderzahlung an den Geschäftsführer gebucht. Erläutern Sie Rechtsgrund, Beschlussdatum und tatsächliche Auszahlung."])], signer="Karin Waldner", signer_role="Steueramtsrätin")
    record(d, "02_geschaeftsfuehrervertrag_nachtrag.docx", org="Mertens Wärmebau GmbH", strapline="Heizung · Sanitär · Wärmepumpen", contact=company, title="Nachtrag zum Geschäftsführeranstellungsvertrag", metadata=[("Geschäftsführer", "Henrik Mertens"), ("Beschluss", "15.12.2023"), ("Gültig", "ab 01.01.2024"), ("Unterzeichnung", "18.12.2023")], sections=[("1. Vergütung", ["Das feste Monatsgehalt beträgt 9200 EUR brutto und wird jeweils am letzten Bankarbeitstag gezahlt. Hinzu kommen eine Tantieme von 18 Prozent des handelsrechtlichen Jahresüberschusses vor Ertragsteuern und vor Tantieme, höchstens jedoch 45 Prozent der festen Jahresvergütung. Verlustvorträge aus Vorjahren werden bei der Berechnung berücksichtigt.", "Für 2024 wurde die Tantieme am 28. März 2025 mit 38640 EUR berechnet und am 2. April ausgezahlt. Für 2025 beschloss der Gesellschafter am 19. Dezember 2025 eine Abschlagszahlung von 30000 EUR, obwohl der Jahresabschluss noch nicht vorlag. Der Vertrag enthält keine Regelung über Abschläge."]), ("2. Fahrzeug und Aufwendungen", ["Die Gesellschaft überlässt dem Geschäftsführer den BMW X5 auch zur privaten Nutzung. Kraftstoff, Versicherung und Wartung trägt die Gesellschaft. Fahrten zwischen Wohnung und Betrieb werden nicht gesondert aufgezeichnet. Urlaubsfahrten ins Ausland bedürfen einer kurzen Mitteilung an die Buchhaltung.", "Reisekosten werden nach den für Arbeitnehmer geltenden Sätzen ersetzt. Bewirtungsbelege müssen Anlass und Teilnehmer nennen. Für private Baumaterialien kann der Geschäftsführer den Einkauf der Gesellschaft nutzen; die Weiterberechnung soll zum Einkaufspreis zuzüglich Umsatzsteuer erfolgen."])], signer="Henrik Mertens", signer_role="Gesellschafter und Geschäftsführer")
    record(d, "03_mietvertrag_werkhalle_gesellschafter.docx", org="Henrik Mertens", strapline="Vermietung Werkhalle Laubanger 12a", contact="Am Regnitzufer 29 · 96049 Bamberg\nTelefon 0951 311 88 06 · henrik.mertens@posteo.de", title="Mietvertrag über Werkstatt- und Lagerflächen", metadata=[("Vermieter", "Henrik Mertens"), ("Mieterin", "Mertens Wärmebau GmbH"), ("Mietbeginn", "01.01.2024"), ("Fläche", "Werkstatt 310 qm / Lager 180 qm")], sections=[("1. Mietgegenstand und Entgelt", ["Vermietet werden die auf dem Grundstück Laubanger 12a gelegene Werkhalle, das Außenlager und sechs Stellplätze. Die monatliche Nettomiete beträgt 7800 EUR zuzüglich Umsatzsteuer und einer Betriebskostenvorauszahlung von 850 EUR. Die Zahlung ist bis zum dritten Werktag auf das Konto des Vermieters zu leisten.", "Ein schriftliches Verkehrswertgutachten wurde nicht eingeholt. Die Parteien bezogen sich auf zwei Internetangebote für Hallen in Hallstadt und Strullendorf. Eine der Vergleichshallen war neu gebaut und beheizbar; die andere hatte keine Außenfläche. Die frühere Mieterin zahlte bis September 2023 monatlich 3900 EUR ohne Umsatzsteuer."]), ("2. Umbau und Instandhaltung", ["Die GmbH darf auf eigene Kosten ein Hochregallager, eine Absauganlage und Ladepunkte errichten. Bei Vertragsende verbleiben fest verbundene Einbauten entschädigungslos beim Vermieter, sofern dieser keinen Rückbau verlangt. Dach und tragende Bauteile unterhält der Vermieter; Tore, Heizung und Inneninstallationen trägt die Mieterin.", "Im Februar 2025 bezahlte die GmbH 28600 EUR für die Erneuerung zweier Dachflächen nach einem Sturmschaden. Die Rechnung der Dachdeckerei nennt die GmbH als Auftraggeberin. Eine Verrechnung mit der Miete erfolgte nicht."])], signer="Henrik Mertens", signer_role="Vermieter und Geschäftsführer der Mieterin")
    record(d, "04_darlehensvertrag_und_kontoblatt.docx", org="Mertens Wärmebau GmbH", strapline="Finanzierung Wärmepumpenlager", contact=company, title="Gesellschafterdarlehen mit Kontenabstimmung", metadata=[("Vertrag", "MW-GLD-2024-01"), ("Darlehensgeber", "Henrik Mertens"), ("Valuta", "180000 EUR"), ("Laufzeit", "01.02.2024 bis 31.01.2027")], sections=[("1. Vertragsbedingungen", ["Das Darlehen wird mit 7.5 Prozent jährlich verzinst. Zinsen sind jeweils zum 31. Dezember fällig. Die Tilgung erfolgt in sechs halbjährlichen Raten zu 30000 EUR ab 30. Juni 2024. Sicherheiten sind nicht bestellt. Eine vorzeitige Rückzahlung ist jederzeit möglich.", "Die Valuta ging am 2. Februar 2024 auf dem Geschäftskonto ein. Die erste Tilgungsrate wurde am 28. Juni gezahlt. Weitere vertragliche Raten sind auf dem Bankkonto nicht erkennbar. Am 15. August 2025 überwies die GmbH 42000 EUR mit dem Verwendungszweck Rückzahlung privat; die Buchhaltung erfasste 30000 EUR als Tilgung und 12000 EUR als Verrechnungskonto Gesellschafter."]), ("2. Zinsbuchungen und Liquidität", ["Für 2024 wurden 12375 EUR Zinsen aufwandswirksam gebucht und am 10. Januar 2025 gezahlt. Für 2025 wurden 11250 EUR gebucht, aber bis zum 31. März 2026 nicht ausgezahlt. Der Kontokorrentkredit der Hausbank war im Dezember 2025 mit 148000 EUR von 150000 EUR ausgeschöpft.", "Henrik Mertens erklärte der Buchhaltung am 22. Dezember telefonisch, die Zinsen könnten stehen bleiben. Eine schriftliche Stundung liegt nicht vor. Das Darlehenskonto weist nach der Umbuchung vom August einen Saldo von 120000 EUR aus."])], signer="Leonie Frank", signer_role="Finanzbuchhaltung")
    record(d, "05_beschaeftigung_sabine_mertens.docx", org="Mertens Wärmebau GmbH", strapline="Personalunterlagen", contact=company, title="Vereinbarung Bürohilfe und Tätigkeitsnachweise", metadata=[("Beschäftigte", "Sabine Mertens"), ("Beginn", "01.04.2024"), ("Vergütung", "520 EUR monatlich"), ("Aufgaben", "Telefon, Belege, Terminbestätigung")], sections=[("1. Vereinbarung", ["Sabine Mertens arbeitet im Umfang von acht Stunden wöchentlich, regelmäßig dienstags und donnerstags zwischen 09:00 und 13:00 Uhr. Sie bestätigt Kundentermine, scannt Eingangsrechnungen und bereitet Monteurmappen vor. Urlaub ist mit der Büroleitung abzustimmen. Die Vergütung wird auf das gemeinsame Ehegattenkonto überwiesen.", "Die Vereinbarung wurde am 27. März 2024 von Henrik und Sabine Mertens unterschrieben. Eine feste Vertretung ist nicht benannt. Zeiterfassung sollte über eine Liste im Büro erfolgen; für April bis August 2024 fehlen unterschriebene Listen."]), ("2. Tatsächlicher Ablauf", ["Nach Aussage der Disponentin Nele Urban kam Sabine Mertens meist am Donnerstag, teilweise auch sonntags von zu Hause. Während einer Reha im Oktober und November 2024 wurden die Monatsbeträge weitergezahlt. E-Mails aus dieser Zeit zeigen vier Terminbestätigungen und zwei sortierte Lieferantenlisten.", "Ab Januar 2025 erhielt Sabine Mertens zusätzlich monatlich einen Einkaufsgutschein über 50 EUR. Im Juli 2025 nutzte sie den Firmenwagen BA-MW 810 an drei Tagen, während ihr eigenes Fahrzeug in der Werkstatt war. Ein Fahrtenvermerk wurde nicht erstellt."])], signer="Nele Urban", signer_role="Büroleitung")
    email(d, "06_email_tantieme_abschlag_dezember.eml", sender="henrik.mertens@mertens-waermebau.de", recipients=["leonie.frank@mertens-waermebau.de"], cc=["kanzlei@steuerhaus-regnitz.de"], date="Fri, 19 Dec 2025 17:21:00 +0100", subject="Tantieme 2025 – Abschlag vor Weihnachten", message_id="<mw-tantieme-2025-202512191721@mertens-waermebau.de>", body="Hallo Frau Frank,\n\nbitte überweisen Sie mir am Montag 30000 EUR als Abschlag auf die Tantieme 2025. Nach der BWA November liegen wir bei rund 310000 EUR Ergebnis vor Steuern; selbst mit den noch offenen Projektkosten sollte die endgültige Tantieme darüber liegen. Den Gesellschafterbeschluss habe ich heute unterschrieben und in den roten Abschlussordner gelegt.\n\nUnser Vertrag nennt zwar nur die Jahresberechnung, aber die Liquidität reicht nach Eingang der Abschläge von Heller Haustechnik aus. Falls Frau Dr. Seifert noch eine andere Buchung benötigt, soll sie mich Montagvormittag anrufen. Bitte nicht über das Darlehenskonto verrechnen, sondern auf mein Privatkonto auszahlen.\n\nViele Grüße\nHenrik Mertens\nGeschäftsführer\nMertens Wärmebau GmbH\nLaubanger 12, 96052 Bamberg\nTelefon 0951 208 71 41")
    email(d, "07_email_private_materialentnahme.eml", sender="nele.urban@mertens-waermebau.de", recipients=["henrik.mertens@mertens-waermebau.de"], cc=["lager@mertens-waermebau.de"], date="Wed, 13 Aug 2025 08:42:00 +0200", subject="Material für Wohnhaus / Lieferschein 7718 noch offen", message_id="<mw-ls-7718-202508130842@mertens-waermebau.de>", body="Guten Morgen Herr Mertens,\n\nfür die Baustelle an Ihrem Wohnhaus wurden am 8. August zwei Heizkreisverteiler, 180 Meter Verbundrohr, sechs Stellantriebe und Dämmmaterial aus dem Lager genommen. Mehmet hat Lieferschein 7718 auf Privat Mertens geschrieben, aber noch keine Preise eingetragen. Der Einkauf liegt laut System zusammen bei 4870.60 EUR netto.\n\nSoll ich eine Rechnung an Sie erstellen oder läuft das über die noch offene Reisekostenabrechnung? Im Juni hatten wir die Badarmaturen zum Einkaufspreis weiterberechnet. Beim Rohr fehlt mir außerdem die Rückmeldung, ob 24 Meter wieder ins Lager kamen. Der Monteurzettel nennt nur Rest ins Auto.\n\nViele Grüße\nNele Urban\nBüroleitung\nMertens Wärmebau GmbH\nTelefon 0951 208 71 44")
    P.write_txt(d / "08_chat_buchhaltung_miete_dach.txt", """Teams-Export · Kanal Buchhaltung · 24.02.2025 bis 28.02.2025

24.02. 09:18 Leonie Frank: Rechnung Dach Krämer über 28600 EUR ist da. Auftraggeber Mertens Wärmebau, Leistungsort Halle 12a.
24.02. 09:23 Nele Urban: Das war nach dem Sturm. Henrik meinte, wir zahlen erst einmal, sonst tropft es aufs Lager.
24.02. 09:31 Leonie Frank: Laut Mietvertrag Dach Vermieter. Soll ich auf Instandhaltung Gebäude buchen, obwohl uns die Halle nicht gehört?
24.02. 10:02 Henrik Mertens: Bitte zahlen. Wir klären das später mit der Miete. Im März nichts kürzen, ich brauche die private Rate fürs Haus.
27.02. 16:44 Leonie Frank: Zahlung ist raus. Für die Akte brauche ich noch eine Vereinbarung zur Erstattung.
27.02. 17:10 Henrik Mertens: Mach einen Vermerk, dass die GmbH den Betrieb sichern musste. Erstattung besprechen wir beim Abschluss.
28.02. 08:07 Nele Urban: Dachdecker sagt, eine Hälfte war alter Schaden und eine Hälfte Sturm. Er schreibt die Rechnung nicht mehr um.
28.02. 08:22 Leonie Frank: Ich buche vorläufig auf Gebäudeaufwand und markiere es für Dr. Seifert.
""")
    P.write_csv(d / "09_verrechnungskonto_gesellschafter.csv", ["Datum", "Beleg", "Buchung", "Soll_EUR", "Haben_EUR", "Saldo_EUR", "Hinweis"], [["2024-02-02", "BK-0202", "Darlehensvaluta", "0", "180000", "-180000", "Eingang Geschäftskonto"], ["2024-06-28", "BK-0628", "Tilgung", "30000", "0", "-150000", "vertragliche Rate"], ["2025-01-10", "BK-0110", "Zinsen 2024", "12375", "0", "-137625", "separat als Zins gebucht"], ["2025-08-15", "BK-0815", "Überweisung Rückzahlung privat", "42000", "0", "-95625", "davon 12000 Verrechnung"], ["2025-12-22", "BK-1222", "Tantiemeabschlag", "30000", "0", "-65625", "nicht mit Darlehen verrechnet"], ["2025-12-31", "AB-2025", "Zinsen 2025", "0", "11250", "-76875", "noch nicht ausgezahlt"]])
    P.write_csv(d / "10_firmenwagen_reisen_material.csv", ["Datum", "Vorgang", "Nutzer", "Ort", "Betrag_EUR", "Beleg", "Privatbezug_offen"], [["2025-02-14", "Tankung", "Henrik Mertens", "Bamberg", "112.40", "ARAL-2218", "nein"], ["2025-04-05", "Tankung", "Henrik Mertens", "Bozen", "138.20", "ENI-4481", "Urlaubsmitteilung vorhanden"], ["2025-07-08", "Fahrt", "Sabine Mertens", "Bamberg", "0", "Schlüsselbuch", "ja"], ["2025-08-08", "Material Wohnhaus", "Henrik Mertens", "Bamberg", "4870.60", "LS-7718", "Rechnung fehlt"], ["2025-08-21", "Rückgabe Rohr", "Monteur Mehmet Kaya", "Lager", "0", "kein Mengenbeleg", "24 Meter genannt"], ["2025-11-17", "Bewirtung", "Henrik Mertens", "Gasthof Regnitz", "486.90", "RG-1190", "Teilnehmer unvollständig"]])
    P.write_device_photo(d / "11_foto_halle_dach_hochregal.jpg", "Werkhalle Laubanger 12a", ["Dachfläche Nord nach Reparatur", "Hochregal der Mertens Wärmebau GmbH", "Ladepunkt am privaten Gebäudeteil", "Aufnahme: 27.02.2025 · 16:18 Uhr", "Datei aus dem Baustellenmobiltelefon"], (108, 82, 57))
    files = [("01_pruefungsanordnung_koerperschaft_lohn.docx", "Prüfungsanordnung mit Gesellschafter- und Lohnsteuerfragen"), ("02_geschaeftsfuehrervertrag_nachtrag.docx", "Geschäftsführergehalt, Tantieme, Fahrzeug und Materialbezug"), ("03_mietvertrag_werkhalle_gesellschafter.docx", "Hallennutzung mit Vergleichsmiete und Dachreparatur"), ("04_darlehensvertrag_und_kontoblatt.docx", "Gesellschafterdarlehen, Zinsen und unklare Umbuchung"), ("05_beschaeftigung_sabine_mertens.docx", "Angehörigenvereinbarung und tatsächlicher Arbeitsablauf"), ("06_email_tantieme_abschlag_dezember.eml", "Anweisung zur Tantiemezahlung vor Jahresabschluss"), ("07_email_private_materialentnahme.eml", "Materialentnahme für das Wohnhaus des Gesellschafters"), ("08_chat_buchhaltung_miete_dach.txt", "Interner Chat zu Dachkosten der gemieteten Halle"), ("09_verrechnungskonto_gesellschafter.csv", "Darlehens- und Verrechnungskontobewegungen"), ("10_firmenwagen_reisen_material.csv", "Fahrzeug-, Reise- und Materialdaten"), ("11_foto_halle_dach_hochregal.jpg", "Fotodokumentation der Werkhalle")]
