def build_steuer_dba_italien() -> None:
    meta = CaseMeta(
        slug="steuer-dba-italien-ferienwohnung-bologna",
        title="Steuerrecht: Vermietete Wohnung in Bologna und deutsche Erklärung",
        plugins=("steuerrecht-anwalt-und-berater",),
        summary="Die in Nürnberg wohnende Architektin Clara Seidel vermietet seit 2024 eine geerbte Wohnung in Bologna. Italienische Steuerunterlagen, Verwalterabrechnungen und deutsche Erklärungsdaten laufen auseinander; nach einer ausländischen Kontrollmitteilung fragt das Finanzamt nach Einnahmen, Kosten, Ansässigkeit und bisheriger Behandlung.",
        closing="Die Akte trennt Belegenheit und italienische Besteuerung, deutsche Freistellungs- und Progressionsfragen sowie verfahrensrechtliche Offenlegung. Sie enthält die erforderlichen Daten, aber keine fertige Aussage dazu, welche Zeile einer Erklärung auszufüllen ist.",
        checks=(("dba", "Artikel 6 und Artikel 24 Absatz 3 Buchstabe a DBA-Italien auf Vermietung, Ansässigkeit und effektive italienische Besteuerung beziehen."), ("progression", "Paragraf 32b Absatz 1 Satz 1 Nummer 3 und Satz 2 Nummer 3 EStG sowie BFH vom 21. Mai 2025, I R 5/22, nach ihrem jeweiligen Anwendungsbereich unterscheiden; die Entscheidung betrifft keinen Italien-Sachverhalt."), ("mitwirkung", "Materielle Steuerzuweisung und verfahrensrechtliche Mitwirkung nach Paragraf 90 Absatz 2 AO getrennt prüfen."), ("zahlen", "Bruttomieten, Verwaltung, Instandhaltung, italienische Steuer und Wechselkurse aus Originaldaten abstimmen.")),
    )
    d = P.prepare(meta.slug)
    fa = "Sandstraße 20 · 90443 Nürnberg\nTelefon 0911 242 0 · Fax 0911 242 1800\nSteuernummer 241/229/40871"
    record(d, "01_grundbuch_und_erbnachweis_bologna.docx", org="Studio Notarile Bellandi", strapline="Notaio Laura Bellandi · Abschrift und deutsche Arbeitsübersetzung", contact="Via Santo Stefano 92 · 40125 Bologna\nTelefon +39 051 338 72 10 · segreteria@notaiobellandi.it\nRepertorio notarile 88412", title="Eigentums- und Erwerbsunterlagen Via Saragozza 118", metadata=[("Eigentümerin", "Clara Seidel, geb. 08.11.1982"), ("Einheit", "Interno 7, Piano 3"), ("Kataster", "Foglio 202, Particella 811, Subalterno 19"), ("Erwerb", "Erbfolge nach Marta Bianchi, 17.02.2024")], sections=[("1. Objekt", ["Die Wohnung liegt im dritten Obergeschoss des Hauses Via Saragozza 118 in Bologna und umfasst 84 Quadratmeter, drei Zimmer, Küche, Bad und Kellerabteil Nummer 7. Der Miteigentumsanteil beträgt 78.40 Tausendstel. Die Eintragung nennt Clara Seidel als Alleineigentümerin aufgrund der am 12. Juni 2024 registrierten Erbschaftserklärung.", "Marta Bianchi, Tante der Eigentümerin, verstarb am 17. Februar 2024 in Bologna. Das Testament vom 3. Mai 2019 weist Clara Seidel die Wohnung und ein Konto bei Banca Emiliana zu. Die Schlüssel wurden am 22. Juni 2024 durch den Verwalter Paolo Ventresca übergeben."]), ("2. Nutzung und Belastungen", ["Seit 1. September 2024 ist die Wohnung an Marco Rinaldi und Elisa Gori vermietet. Eine Grundschuld ist nicht eingetragen. Die Wohnungseigentümergemeinschaft beschloss im November 2024 eine Dachsanierung; auf die Einheit entfielen 8460 EUR, zahlbar in drei Raten.", "Die vorliegende Abschrift wurde für die Besprechung in Deutschland übersetzt. Maßgeblich bleiben die italienische Urkunde und die Katasterauszüge mit Registrierungsstempeln. Eine Veräußerung oder Eigennutzung ist bis Juli 2026 nicht dokumentiert."])], signer="Dott.ssa Laura Bellandi", signer_role="Notaio in Bologna")
    record(d, "02_mietvertrag_via_saragozza.docx", org="Amministrazioni Ventresca SRL", strapline="Condominio und Mietverwaltung", contact="Via Andrea Costa 55 · 40134 Bologna\nTelefon +39 051 614 28 40 · affitti@ventresca-amministrazioni.it\nPartita IVA 03988211201", title="Mietvertrag und Übergabeübersicht", metadata=[("Vermieterin", "Clara Seidel"), ("Mieter", "Marco Rinaldi / Elisa Gori"), ("Beginn", "01.09.2024"), ("Monatsmiete", "1280 EUR zuzüglich 190 EUR Vorauszahlung")], sections=[("1. Vertragsinhalt", ["Der Vertrag läuft vier Jahre mit gesetzlicher Verlängerungsmöglichkeit. Die Nettomiete ist bis zum fünften Tag jedes Monats auf das Treuhandkonto der Verwalterin zu zahlen. Die Verwalterin behält monatlich 102.40 EUR Honorar ein und leitet den verbleibenden Betrag jeweils zum Monatsende an Clara Seidel weiter.", "Die Kaution beträgt 3840 EUR. Sie wurde am 28. August 2024 auf einem gesonderten Konto verbucht und nicht an die Eigentümerin ausgekehrt. Kleinreparaturen bis 180 EUR tragen die Mieter; Arbeiten an Leitungen und Gemeinschaftseigentum werden über die Verwalterin beauftragt."]), ("2. Übergabe und Mietverlauf", ["Bei Übergabe am 30. August 2024 wurden 62 kleine Bohrlöcher, ein Haarriss im Wohnzimmer und ein feuchter Fleck neben dem Küchenfenster protokolliert. Der Wasserzähler stand bei 04118 Kubikmetern. Die erste Monatsmiete ging am 2. September ein.", "Im März 2025 zahlten die Mieter nur 1080 EUR Nettomiete und verrechneten 200 EUR für einen Notdienst am Küchenabfluss. Die Verwalterin widersprach der Verrechnung, leitete aber nur den tatsächlich eingegangenen Betrag weiter. Im Dezember 2025 wurde die Miete wegen Baugerüsts einvernehmlich um 160 EUR gemindert."])], signer="Paolo Ventresca", signer_role="Amministratore")
    record(d, "03_italienische_steuerbescheinigung_2025.docx", org="Studio Tributario Riva", strapline="Dottore Commercialista Giulia Riva · Deutsche Leseabschrift", contact="Via Rizzoli 17 · 40125 Bologna\nTelefon +39 051 221 904 · studio@riva-tributi.it\nOrdine Bologna Nr. 1884", title="Dichiarazione und Zahlungsübersicht 2025", metadata=[("Steuerpflichtige", "Clara Seidel"), ("Codice fiscale", "SDLC LR82S48Z112Q"), ("Objekt", "Via Saragozza 118, Bologna"), ("Erstellt", "02.07.2026")], sections=[("1. Erfasste Mietdaten", ["Für 2025 wurden in der eingereichten Erklärung elf Monatsmieten zu 1280 EUR und die geminderte Dezembermiete von 1120 EUR angesetzt. Nebenkostenvorauszahlungen und Kaution wurden nicht als Nettomiete in die Aufstellung aufgenommen. Die erklärte Bruttomiete beträgt damit 15200 EUR; ein gesonderter Abgleich mit den tatsächlichen Auskehrungen der Verwalterin war bei Erstellung noch nicht abgeschlossen.", "Die Erklärung verwendet die von der Mandantin gewählte italienische Sonderbesteuerung für Wohnraummiete mit 21 Prozent. Verwalterhonorar, Dachumlage und Reparaturen wurden in der Berechnung nicht einzeln abgezogen. Am 30. Juni 2025 und 30. November 2025 wurden Vorauszahlungen geleistet."]), ("2. Zahlungen und Unterlagen", ["Für das Steuerjahr 2025 weist das F24-Zahlungsprotokoll 3192 EUR aus. Hinzu kommen 842 EUR kommunale Immobilienabgabe und 96 EUR Gebühren. Die Vorauszahlung 2026 über 1596 EUR wurde am 30. Juni 2026 vom italienischen Konto belastet.", "Das Büro hat keine deutsche Erklärung erstellt und keine Aussage zur deutschen verfahrensrechtlichen Behandlung abgegeben. Clara Seidel erhielt Kopien der italienischen Erklärung, F24-Belege, Mietübersicht und Katasterdaten am 20. Juni 2026 per verschlüsseltem Portal."])], signer="Dott.ssa Giulia Riva", signer_role="Dottore Commercialista")
    record(d, "04_auskunftsersuchen_finanzamt_nuernberg.docx", org="Finanzamt Nürnberg-Süd", strapline="Veranlagung natürliche Personen", contact=fa, title="Ausländische Vermietungseinkünfte – Bitte um Stellungnahme", metadata=[("Steuernummer", "241/229/40871"), ("Aktenzeichen", "AUS-IT-2026-918"), ("Datum", "06.07.2026"), ("Antwortfrist", "03.08.2026")], sections=[("1. Kontrollmitteilung", ["Dem Finanzamt wurde im automatisierten Informationsaustausch eine in Italien belegene Immobilie der Steuerpflichtigen sowie eine italienische Steuerzahlung für 2025 mitgeteilt. In der Einkommensteuererklärung 2025 und den ergänzenden Anlagen finden sich hierzu keine Angaben.", "Bitte teilen Sie Erwerbszeitpunkt, Nutzung, Bruttomieten, Werbungskosten, italienische Steuer und den Stand einer ausländischen Veranlagung mit. Reichen Sie Eigentumsnachweis, Mietvertrag, Kontoauszüge, Verwalterabrechnung und Steuerbelege in deutscher Sprache oder mit nachvollziehbarer Übersetzung ein."]), ("2. Ansässigkeit und bisherige Behandlung", ["Erklären Sie, ob im Jahr 2025 neben der Wohnung in Nürnberg eine in Italien jederzeit verfügbare Wohnstätte bestand und wo sich der Mittelpunkt der persönlichen und wirtschaftlichen Beziehungen befand. Nach Aktenlage war die Wohnung in Bologna ganzjährig vermietet.", "Bitte erläutern Sie ferner, aufgrund welcher Erwägungen die Einkünfte in den abgegebenen Unterlagen nicht ausgewiesen wurden. Dieses Schreiben trifft noch keine Entscheidung über Besteuerungsrecht, Freistellung, Anrechnung oder Steuersatz."])], signer="Johannes Klee", signer_role="Steueroberinspektor")
    record(d, "05_unterlagenanforderung_steuerkanzlei.docx", org="Steuerkanzlei Heller und May", strapline="Steuerberater · Internationales Steuerrecht", contact="Fürther Straße 98 · 90429 Nürnberg\nTelefon 0911 288 19 20 · kanzlei@heller-may.de\nMandat HM-2418", title="Unterlagenliste und Gesprächsvermerk Italien", metadata=[("Mandantin", "Clara Seidel"), ("Besprechung", "10.07.2026, 14:30 Uhr"), ("Bearbeiter", "StB Moritz Heller"), ("Frist Finanzamt", "03.08.2026")], sections=[("1. Angaben der Mandantin", ["Clara Seidel wohnt und arbeitet seit 2011 in Nürnberg. Die Wohnung in Bologna wurde nach dem Tod ihrer Tante übernommen und unmittelbar über Ventresca vermietet. Eigene Aufenthalte beschränkten sich 2025 auf drei Besprechungen mit Verwalter und Handwerkern; übernachtet wurde nach ihrer Angabe in einem Hotel.", "Die deutsche Einkommensteuererklärung 2025 erstellte die Mandantin mit einer Steuersoftware. Sie erinnert sich an eine Frage nach ausländischen Einkünften, nahm jedoch an, die in Italien besteuerte Miete müsse nirgends eingetragen werden. Das italienische Büro erhielt nur Unterlagen zur Wohnung."]), ("2. Fehlende und widersprüchliche Belege", ["Noch anzufordern sind die vollständigen italienischen Kontoauszüge, das Original der Dichiarazione, die F24-Quittungen und eine Aufschlüsselung der Dachumlage. In der Verwalterübersicht ist März mit 1080 EUR erfasst; die italienische Jahresübersicht nennt für März 1280 EUR. Dezember ist in beiden Unterlagen mit 1120 EUR ausgewiesen.", "Vor einer Antwort sind Ansässigkeit, Zuordnung nach dem Abkommen, innerstaatliche Progressionsregel und Mitwirkung als getrennte Ebenen zu bearbeiten. Das Schreiben an das Finanzamt soll nur durch Belege gesicherte Tatsachen enthalten und offene Umrechnungs- oder Deklarationsfragen kenntlich machen."])], signer="Moritz Heller", signer_role="Steuerberater")
    email(d, "06_email_verwalter_mietkuerzung.eml", sender="paolo.ventresca@ventresca-amministrazioni.it", recipients=["clara.seidel@architektur-seidel.de"], cc=["studio@riva-tributi.it"], date="Wed, 8 Apr 2026 10:26:00 +0200", subject="Via Saragozza 118 / riepilogo canoni 2025 e differenza marzo", message_id="<vs118-2025-riepilogo-202604081026@ventresca-amministrazioni.it>", body="Guten Morgen Frau Seidel,\n\nanbei erhalten Sie die Abrechnung der im Jahr 2025 eingegangenen Mieten. Im März haben Rinaldi und Gori eigenmächtig 200 EUR für den Rohrnotdienst abgezogen. Wir haben den Betrag nicht anerkannt, aber tatsächlich nur 1080 EUR Nettomiete erhalten und nach Abzug unseres Honorars weitergeleitet. Das Steuerbüro hatte zunächst die vertragliche Miete von 1280 EUR in seiner Liste.\n\nIm Dezember galt wegen des Baugerüsts die mit Ihnen per E-Mail bestätigte Minderung um 160 EUR. Die Dachumlage wurde in drei Raten vom Eigentümerkonto gezahlt. Die Mietkaution von 3840 EUR liegt weiterhin auf dem separaten Konto und erscheint nicht in den monatlichen Auskehrungen.\n\nBitte prüfen Sie besonders die Kontonummern: Zwei Auskehrungen gingen auf Ihr deutsches Konto, alle übrigen auf das Konto bei Banca Emiliana.\n\nFreundliche Grüße\nPaolo Ventresca\nAmministrazioni Ventresca SRL\nVia Andrea Costa 55, 40134 Bologna\nTelefon +39 051 614 28 40")
    email(d, "07_email_mandantin_steuerprogramm.eml", sender="clara.seidel@architektur-seidel.de", recipients=["moritz.heller@heller-may.de"], cc=[], date="Fri, 10 Jul 2026 18:12:00 +0200", subject="Finanzamt-Schreiben Italien / was ich 2025 eingegeben habe", message_id="<cs-italien-202607101812@architektur-seidel.de>", body="Sehr geehrter Herr Heller,\n\nich habe nach unserem Gespräch die gespeicherte PDF meiner Erklärung und die Eingabedaten aus dem Programm gefunden. Bei ausländischen Einkünften steht dort nein. Ich war damals sicher, dass die Wohnung nur nach Italien gehört, weil Frau Riva dort die Steuer angemeldet und bezahlt hat. Einen Hinweis auf eine deutsche Zeile habe ich nicht mehr gesehen.\n\nIch war 2025 dreimal in Bologna: 14. bis 16. Februar wegen der Erbschaftsunterlagen, 6. bis 8. Juni wegen des feuchten Flecks und 21. bis 23. November wegen der Eigentümerversammlung. Die Wohnung war jeweils vermietet; ich habe im Hotel Porta San Felice geschlafen. Meine Wohnung, Arbeit und Familie sind in Nürnberg.\n\nIm Anhang liegen die deutschen Kontoauszüge und die Hotelrechnungen. Den Zugang zum italienischen Konto habe ich heute neu beantragt, weil die alte Mobilnummer meiner Tante noch hinterlegt war.\n\nMit freundlichen Grüßen\nClara Seidel\nArchitekturbüro Seidel\nObere Wörthstraße 18, 90403 Nürnberg\nTelefon 0911 377 28 14")
    P.write_txt(d / "08_telefonnotiz_studio_riva.txt", """Telefonvermerk Steuerkanzlei Heller und May
Datum: 14.07.2026
Beginn: 09:18 Uhr
Ende: 09:46 Uhr
Gesprächspartnerinnen: Dott.ssa Giulia Riva, Bologna, und Rechtsanwaltsfachangestellte Nora Busch, Nürnberg
Mandat: HM-2418 Clara Seidel

Frau Riva bestätigt, dass die eingereichte Aufstellung für Januar bis November jeweils 1280 EUR und für Dezember 1120 EUR enthält. Der im März tatsächlich einbehaltene Notdienstabzug von 200 EUR sei darin noch nicht berichtigt worden. Sie prüft, ob eine Änderung der italienischen Erklärung veranlasst wird.

Die ausgewiesene Zahlung von 3192 EUR betreffe die italienische Einkommensteuer auf die erklärte Wohnraummiete für 2025. Die kommunale Immobilienabgabe von 842 EUR sei davon getrennt. Frau Riva übersendet bis Freitag die vollständige Erklärung mit elektronischer Eingangsquittung und zwei F24-Zahlungsbelegen.

Auf Nachfrage erklärt Frau Riva, sie habe keine deutsche Steuererklärung geprüft. Ihr Auftrag habe die italienische Immobilie umfasst. Die deutsche Behandlung müsse der Berater in Nürnberg klären. Für Übersetzungen könne sie eine zweisprachige Mitarbeiterin benennen; eine beglaubigte Übersetzung sei bisher nicht erstellt worden.

Nora Busch weist auf die Antwortfrist 3. August hin. Frau Riva notiert Aktenzeichen AUS-IT-2026-918 und bittet darum, Rückfragen mit der Katasterkennung Foglio 202, Particella 811, Subalterno 19 zu versehen.
""")
    P.write_csv(d / "09_mieten_auskehrungen_2025.csv", ["Monat", "Vertrag_EUR", "Eingang_EUR", "Verwalterhonorar_EUR", "Auskehrung_EUR", "Zielkonto", "Besonderheit"], [["Januar", "1280", "1280", "102.40", "1177.60", "Banca Emiliana", ""], ["Februar", "1280", "1280", "102.40", "1177.60", "Banca Emiliana", ""], ["März", "1280", "1080", "102.40", "977.60", "Banca Emiliana", "Notdienstabzug 200"], ["April", "1280", "1280", "102.40", "1177.60", "deutsches Konto", ""], ["Mai", "1280", "1280", "102.40", "1177.60", "Banca Emiliana", ""], ["Juni", "1280", "1280", "102.40", "1177.60", "Banca Emiliana", ""], ["Juli", "1280", "1280", "102.40", "1177.60", "Banca Emiliana", ""], ["August", "1280", "1280", "102.40", "1177.60", "deutsches Konto", ""], ["September", "1280", "1280", "102.40", "1177.60", "Banca Emiliana", ""], ["Oktober", "1280", "1280", "102.40", "1177.60", "Banca Emiliana", ""], ["November", "1280", "1280", "102.40", "1177.60", "Banca Emiliana", ""], ["Dezember", "1280", "1120", "89.60", "1030.40", "Banca Emiliana", "Gerüstminderung 160"]])
