def build_steuer_lohnpruefung() -> None:
    meta = CaseMeta(
        slug="steuer-kleinbetrieb-sachbezuege-lohnpruefung-rostock",
        title="Steuerrecht: Lohnsteuerprüfung im kleinen Küstenbetrieb in Rostock",
        plugins=("steuerrecht-anwalt-und-berater",),
        summary="Die Küstenklar Gebäudeservice e. K. beschäftigt fünf Arbeitnehmer. Bei einer Lohnsteuerprüfung treffen wechselnde Einsatzorte, zwei Transporter, Tankkarten, Verpflegungspauschalen, eine möblierte Betriebswohnung, Gutscheine und die Mitarbeit des studierenden Sohnes auf lückenhafte Absprachen.",
        closing="Lohnabrechnungen, Touren, Tankkarten, Wohnungsnutzung, Arbeitszeiten und Reisekosten sind betragsgenau verknüpft. Ob Zahlungen Arbeitslohn, Auslagenersatz oder betriebliche Aufwendungen sind, wird in den Primärunterlagen nicht entschieden.",
        checks=(("arbeitslohn", "Geld- und Sachleistungen nach Paragrafen 8 und 19 EStG sowie einschlägige Steuerbefreiungen einzeln anhand von Zweck, Beleg und tatsächlicher Durchführung prüfen."), ("erste-taetigkeitsstaette", "Arbeitsverträge, Einsatzpläne und tatsächliche Aufsuchen des Betriebs für Fahrt- und Verpflegungsfragen abgleichen."), ("fahrzeuge", "Private Verfügbarkeit, Schlüsselregeln, Tankkarten und Fahrten der Transporter quellenbezogen prüfen."), ("wohnung", "Nutzung, Miete, Umlagen und Lohnabrechnung der Betriebswohnung zeitanteilig abstimmen.")),
    )
    d = P.prepare(meta.slug)
    company = "Am Fischereihafen 7 · 18069 Rostock\nTelefon 0381 660 29 10 · dispo@kuestenklar-service.de\nSteuernummer 079/214/06618"
    fa = "Möllner Straße 13 · 18109 Rostock\nTelefon 0381 128 0 · Fax 0381 128 2190"
    record(d, "01_pruefungsanordnung_lohnsteuer.docx", org="Finanzamt Rostock", strapline="Lohnsteuer-Außenprüfung", contact=fa, title="Prüfungsanordnung Küstenklar Gebäudeservice e. K.", metadata=[("Aktenzeichen", "LSt-079/214/06618-2026/44"), ("Zeitraum", "01.01.2024 bis 31.12.2025"), ("Beginn", "20.08.2026, 09:00 Uhr"), ("Prüfer", "Steueramtmann Olaf Mewes")], sections=[("1. Gegenstand", ["Die Prüfung umfasst Einbehaltung und Abführung der Lohnsteuer einschließlich pauschal besteuerter Bezüge. Bereitzuhalten sind Lohnkonten, Arbeitsverträge, Stunden- und Einsatzpläne, Reisekosten, Fahrzeugunterlagen, Tankkarten, Gutscheinlisten und Vereinbarungen über die Wohnung in Warnemünde.", "Nach den Buchungstexten wurden monatlich Verpflegungspauschalen an mehrere Arbeitnehmer gezahlt. Ferner wurden Kosten der Wohnung Am Strom 44 und Zahlungen an Leonhard Brück erfasst. Bitte erläutern Sie den jeweiligen betrieblichen Anlass."]), ("2. Elektronische Daten", ["Die Lohnbuchhaltung ist als Export mit Stammdaten, Abrechnungen und Korrekturläufen zu übergeben. Für die Transporter HRO-KK 71 und HRO-KK 72 werden Fahrten- und Schlüsselunterlagen sowie Tankkartenabrechnungen benötigt.", "Der Prüfungsbeginn gilt nicht als Aussage zu einzelnen Sachverhalten. Rückfragen können vorab schriftlich unter Angabe des Aktenzeichens eingereicht werden."])], signer="Olaf Mewes", signer_role="Steueramtmann")
    record(d, "02_arbeitsvertraege_einsatzorte.docx", org="Küstenklar Gebäudeservice e. K.", strapline="Treppenhaus · Ferienwohnung · Glasreinigung", contact=company, title="Arbeitsbedingungen und Einsatzorganisation", metadata=[("Inhaberin", "Mareike Brück"), ("Beschäftigte", "fünf Arbeitnehmer"), ("Stand", "01.01.2025"), ("Disponent", "René Wolgast")], sections=[("1. Vertragliche Angaben", ["Die Arbeitsverträge nennen den Betrieb Am Fischereihafen 7 als organisatorischen Ausgangspunkt. Die Arbeitnehmer werden an wechselnden Objekten in Rostock, Warnemünde, Kühlungsborn und Bad Doberan eingesetzt. Beginn und Ende sollen am Objekt erfolgen, wenn Material und Schlüssel bereits vorhanden sind.", "Montags holen die Teams regelmäßig Reinigungsmittel, Wäsche und Schlüssel im Betrieb ab. An anderen Tagen fährt ein Teamleiter den Transporter nach Hause und sammelt Kollegen unterwegs ein. Eine dauerhafte Zuordnung zu einem Kundenobjekt ist in den Verträgen nicht geregelt."]), ("2. Pauschalen und Gutscheine", ["Für Einsatztage außerhalb Rostocks zahlte die Buchhaltung häufig 14 EUR Verpflegungspauschale, sofern die Schicht länger als acht Stunden geplant war. Tatsächliche Abwesenheitszeiten wurden nicht immer nachgetragen. Im Dezember erhielten alle Beschäftigten einen Einkaufsgutschein über 50 EUR; im Juni 2025 zusätzlich einen Tankgutschein über 44 EUR.", "Der Sohn der Inhaberin, Leonhard Brück, unterstützte während des Semesters bei Schlüsselverwaltung und Website. Er erhielt monatlich 420 EUR und im August 2025 einmalig 900 EUR für die Überarbeitung des Buchungskalenders."])], signer="Mareike Brück", signer_role="Inhaberin")
    record(d, "03_betriebswohnung_warnemuende.docx", org="Hausverwaltung Ostseeblick KG", strapline="Mietverwaltung Am Strom 44", contact="Mühlenstraße 22 · 18119 Rostock\nTelefon 0381 519 42 70 · miete@ostseeblick-hv.de", title="Mietvertrag möblierte Einzimmerwohnung", metadata=[("Mieterin", "Küstenklar Gebäudeservice e. K."), ("Mietbeginn", "01.04.2025"), ("Warmmiete", "740 EUR monatlich"), ("Wohnfläche", "31 qm")], sections=[("1. Mietzweck", ["Die Wohnung dient nach dem Vertrag der vorübergehenden Unterbringung von Beschäftigten bei frühen oder späten Einsätzen in Warnemünde. Eine touristische Weitervermietung ist ausgeschlossen. Die Wohnung enthält Bett, Schrank, Tisch, Küchenzeile und Waschmaschine.", "Hauptnutzer war von April bis September 2025 Arbeitnehmer Adrian Sokolowski, dessen Hauptwohnung in Güstrow liegt. Er übernachtete nach eigener Liste an 74 Nächten. Im Juli nutzte die Inhaberin die Wohnung an zwei Wochenenden während eines Segelkurses."]), ("2. Kosten und Schlüssel", ["Der Betrieb zahlte Kaution und monatliche Miete vom Geschäftskonto. Strom wurde separat mit durchschnittlich 54 EUR monatlich abgerechnet. Einen Eigenanteil zog die Lohnbuchhaltung bei Herrn Sokolowski nicht ab.", "Es gibt drei Schlüssel. Einer liegt im Betrieb, einer bei Herrn Sokolowski und einer bei der Inhaberin. Die Hausverwaltung dokumentierte am 16. August eine Schlüsselübergabe an Leonhard Brück für eine Nacht nach dem Hanse-Sail-Einsatz."])], signer="Iris Kämmer", signer_role="Objektverwaltung")
    record(d, "04_fahrzeug_tankkartenregel.docx", org="Küstenklar Gebäudeservice e. K.", strapline="Fuhrparkregelung", contact=company, title="Transporter, Schlüssel und Tankkarten", metadata=[("Fahrzeuge", "HRO-KK 71 / HRO-KK 72"), ("Gültig", "ab 01.02.2025"), ("Tankkarten", "FleetNord 77104 / 77105"), ("Verantwortlich", "René Wolgast")], sections=[("1. Nutzung", ["Die Transporter dienen Material- und Personalfahrten. HRO-KK 71 steht werktags meist bei Teamleiterin Jana Behrens in Reutershagen, HRO-KK 72 bei Teamleiter René Wolgast in Lütten Klein. Private Fahrten sind laut Aushang untersagt. Schriftliche Nutzungsvereinbarungen wurden nicht abgeschlossen.", "Kilometerstände werden jeweils zum Monatsende fotografiert. Für HRO-KK 72 fehlen Fotos August und September 2025. Am 4. Oktober wurde das Fahrzeug an der Ostseeallee in Kühlungsborn betankt, obwohl für diesen Samstag kein Kundenauftrag im Einsatzplan steht."]), ("2. Tankkarten", ["Die Karten sind fahrzeugbezogen und können für Diesel sowie AdBlue genutzt werden. Zwei Belege aus Juni enthalten Kaffee und Fahrzeugwäsche. Eine Barabhebung ist ausgeschlossen. PIN und Karte liegen getrennt im Handschuhfach.", "Die Inhaberin nutzte HRO-KK 71 am 12. Juli für den Transport von Gartenmöbeln zu ihrer Privatwohnung. Sie erklärte, der Transport sei auf dem Rückweg von einem Objekt erfolgt. Kilometer und Kraftstoff wurden nicht gesondert erstattet."])], signer="René Wolgast", signer_role="Disponent und Teamleiter")
    record(d, "05_vorlaeufige_sachverhaltsliste_lohnbuero.docx", org="Lohnkontor Warnow GmbH", strapline="Lohnabrechnung und Finanzbuchhaltung", contact="Doberaner Straße 108 · 18057 Rostock\nTelefon 0381 203 71 40 · lohn@warnow-kontor.de", title="Abstimmung für die Lohnsteuerprüfung", metadata=[("Mandat", "Küstenklar / KK-112"), ("Datum", "04.08.2026"), ("Bearbeiterin", "Jana Lüders"), ("Prüfungsbeginn", "20.08.2026")], sections=[("1. Abrechnungssystem", ["Die Lohnkonten und Korrekturläufe 2024 bis 2025 sind exportiert. Verpflegungspauschalen wurden nach einer monatlichen Excel-Liste der Disposition abgerechnet. Die Liste enthält geplante Schichtdauer, aber nicht stets Abfahrt von der Wohnung und Rückkehr.", "Gutscheine wurden als Sachbezug erfasst. Für den Tankgutschein Juni 2025 ist unklar, ob einzelne Arbeitnehmer im selben Monat bereits einen Einkaufsgutschein erhalten hatten. Die Belege liegen im Ordner Sonstige Personalkosten."]), ("2. Noch zu klärende Punkte", ["Für die Betriebswohnung wurde kein Betrag im Lohnkonto angesetzt. Herr Sokolowski war nicht dauerhaft versetzt; die Einsätze in Warnemünde machten 2025 rund 46 Prozent seiner Stunden aus. Die privaten Wochenenden der Inhaberin sind in der Buchhaltung nicht vermerkt.", "Leonhard Brück ist als kurzfristig Beschäftigter angelegt, obwohl die Zahlungen von April bis Dezember monatlich erfolgten. Studienbescheinigung und Stundenlisten liegen teilweise vor. Der Betrag von 900 EUR im August wurde als Fremdleistung gebucht."])], signer="Jana Lüders", signer_role="Lohnbuchhalterin")
    email(d, "06_email_disposition_pauschalen.eml", sender="rene.wolgast@kuestenklar-service.de", recipients=["jana.lueders@warnow-kontor.de"], cc=["mareike.brueck@kuestenklar-service.de"], date="Fri, 3 Jul 2026 13:54:00 +0200", subject="Pauschalen Mai/Juni und fehlende Rückkehrzeiten", message_id="<kk-pauschalen-2026-07-03@kuestenklar-service.de>", body="Hallo Frau Lüders,\n\nich habe die Einsatzlisten Mai und Juni angehängt. Die Teams starten oft direkt von zu Hause, deshalb kenne ich die genaue Abwesenheitszeit nicht. In der Tabelle steht die geplante Schicht am Objekt. Bei Kühlungsborn rechnen wir normalerweise 14 EUR, wenn einschließlich Fahrt mehr als acht Stunden zusammenkommen.\n\nAm 18. Juni war das Team nur von 07:00 bis 13:30 Uhr im Objekt, hat danach aber noch Wäsche am Hafen abgegeben. Jana meint, sie war erst um 16:20 Uhr zu Hause. René Schulz ist schon um 14:10 Uhr ausgestiegen. Bisher steht bei beiden die Pauschale.\n\nFür die Prüfung kann ich die Fahrzeugortung aus FleetNord anfordern. Bitte sagen Sie, ob wir dafür alle Tage oder nur die markierten brauchen.\n\nViele Grüße\nRené Wolgast\nDisposition Küstenklar Gebäudeservice e. K.\nAm Fischereihafen 7, 18069 Rostock\nTelefon 0381 660 29 14")
    email(d, "07_email_wohnung_schluessel_hanse_sail.eml", sender="iris.kaemmer@ostseeblick-hv.de", recipients=["mareike.brueck@kuestenklar-service.de"], cc=["leonhard.brueck@uni-rostock.de"], date="Mon, 18 Aug 2025 09:08:00 +0200", subject="Am Strom 44 / Schlüsselübergabe am Hanse-Sail-Wochenende", message_id="<as44-schluessel-202508180908@ostseeblick-hv.de>", body="Sehr geehrte Frau Brück,\n\nHerr Leonhard Brück hat am Samstag um 23:18 Uhr den Reserveschlüssel bei unserem Bereitschaftsdienst abgeholt und am Sonntag um 11:42 Uhr zurückgegeben. Als Grund nannte er einen späten Arbeitseinsatz an der Ferienwohnung Strandweg 6. Bitte bestätigen Sie kurz, dass die Nutzung betrieblich veranlasst war.\n\nDer Hausmeister meldet außerdem, dass am Sonntagmorgen zwei weitere Personen die Wohnung verlassen haben. Wir bewerten das mietrechtlich derzeit nicht, möchten aber an die vereinbarte Nutzung ausschließlich zur Unterbringung von Beschäftigten erinnern.\n\nMit freundlichen Grüßen\nIris Kämmer\nHausverwaltung Ostseeblick KG\nMühlenstraße 22, 18119 Rostock\nTelefon 0381 519 42 73")
    P.write_txt(d / "08_sms_export_teamleiter_fahrzeug.txt", """SMS-Export Diensttelefon Küstenklar · HRO-KK 72

04.10.2025 08:14 René Wolgast an Mareike Brück: Ich nehme KK72 kurz nach Kühlungsborn. Meine Schwester zieht aus der Ferienwohnung, zwei Kisten passen nicht ins Auto.
04.10.2025 08:26 Mareike Brück: Ist dort heute ein Objekt offen? Wir brauchen für jede Fahrt einen Bezug, die Tankkarte wird geprüft.
04.10.2025 08:31 René Wolgast: Strandblick 9 hat Schlüsselproblem, ich kann auf dem Weg nachsehen. Dauert zehn Minuten.
04.10.2025 12:47 René Wolgast: Getankt 86.30 und Waschanlage 14.99. Schlüssel bei Strandblick war nur verkantet, keine Arbeitskarte geschrieben.
05.10.2025 17:03 Mareike Brück: Bitte Montag Kilometerstand und kurzen Zettel abgeben. Privaten Anteil zahlst du notfalls zurück.
06.10.2025 07:56 René Wolgast: Start Freitag 68112, heute 68301. Ich weiß nicht mehr, wie viel nur Umweg Schwester war.
06.10.2025 08:10 Mareike Brück: Schreib die Route genau auf: Lütten Klein, Kühlungsborn, Schwester, Strandblick, zurück. Nicht schätzen, wenn du es nicht weißt.
06.10.2025 09:22 René Wolgast: Navi-Verlauf ist gelöscht, weil Handy Update hatte. Tankbeleg liegt im Fach.
""")
    P.write_csv(d / "09_reisekosten_einsatzzeiten.csv", ["Datum", "Arbeitnehmer", "Objekt", "Plan_von", "Plan_bis", "Ort", "Pauschale_EUR", "Fahrzeugdaten", "Hinweis"], [["2025-05-06", "Jana Behrens", "Seeblick 18", "06:30", "15:00", "Kühlungsborn", "14", "KK71 05:58-16:04", ""], ["2025-05-06", "Milan Petrović", "Seeblick 18", "07:00", "15:00", "Kühlungsborn", "14", "Mitfahrt KK71", "Einstieg 06:42"], ["2025-06-18", "Jana Behrens", "Dünenhof 4", "07:00", "13:30", "Warnemünde", "14", "KK71 06:21-16:02", "Wäscheabgabe"], ["2025-06-18", "René Schulz", "Dünenhof 4", "07:00", "13:30", "Warnemünde", "14", "Ausstieg 14:10", "Rückkehr früher"], ["2025-06-24", "Adrian Sokolowski", "Am Strom 39", "05:30", "14:00", "Warnemünde", "14", "zu Fuß ab Wohnung", "Übernachtung Vorabend"], ["2025-06-30", "Milan Petrović", "Büro Hafen", "08:00", "15:45", "Rostock", "0", "keine Fahrt", "Materialinventur"]])
