    files = [("01_pruefungsanordnung_lohnsteuer.docx", "Prüfungsanordnung mit konkreten Datenanforderungen"), ("02_arbeitsvertraege_einsatzorte.docx", "Arbeitsorte, Pauschalen, Gutscheine und Familienmithilfe"), ("03_betriebswohnung_warnemuende.docx", "Mietvertrag und tatsächliche Nutzung der Betriebswohnung"), ("04_fahrzeug_tankkartenregel.docx", "Transporterregel, Tankkarten und private Nutzungsindizien"), ("05_vorlaeufige_sachverhaltsliste_lohnbuero.docx", "Abstimmung des Lohnbüros vor Prüfungsbeginn"), ("06_email_disposition_pauschalen.eml", "Disposition erläutert fehlende Abwesenheitszeiten"), ("07_email_wohnung_schluessel_hanse_sail.eml", "Hausverwaltung fragt eine Wochenendnutzung ab"), ("08_sms_export_teamleiter_fahrzeug.txt", "SMS-Verlauf zu einer gemischten Transporterfahrt"), ("09_reisekosten_einsatzzeiten.csv", "Einsatz- und Fahrzeugzeiten für Verpflegungspauschalen"), ("10_sachbezuege_wohnung_fahrzeuge.csv", "Leistungen und Behandlung im Lohnkonto"), ("11_foto_schluesselbuch_tankkarten.jpg", "Foto von Schlüsselbrett und Fahrtenbuch")]
