def build_bgb_gartenbuergschaft() -> None:
    meta = CaseMeta(
        slug="bgb-buergschaft-gartenbau-kassel",
        title="BGB: Gartenumbau, Zusatzauftrag und Bürgschaft in Kassel",
        plugins=("bgb-bt-pruefer", "bgb-at-pruefer", "schriftform-und-textform-bgb", "fachanwalt-bau-architektenrecht"),
        summary="Rentnerin Ingrid Möller lässt ihren abschüssigen Garten durch die Grünwerk Habichtswald GmbH umbauen. Nach Zusatzarbeiten, Rissen an der Stützmauer und offenen Rechnungen beruft sich der Unternehmer auf eine E-Mail der Tochter, sie werde für die Kosten einstehen.",
        closing="Angebot, Leistungsänderungen, Baustellenmaße, Zahlungen und Familienkommunikation lassen mehrere Vertragsebenen erkennen. Form, Inhalt und Reichweite der Erklärung der Tochter sowie Mängel und Vergütung sind aus den Originalstücken zu entwickeln.",
        checks=(("werkvertrag", "Paragrafen 631, 633 und 634 BGB auf vereinbarte Beschaffenheit, Abnahme, Mängel und Fristsetzungen beziehen."), ("nachtrag", "Zusatzleistungen, Preisabrede und Vertretung bei Baustellenentscheidungen anhand von Auftrag, Chat und Aufmaß trennen."), ("buergschaft", "Paragrafen 765 und 766 Satz 1 und Satz 2 BGB sowie Paragraf 126 Absatz 3 BGB auf Wortlaut, Form und die Abgrenzung zu Schuldbeitritt und Garantie anwenden."), ("zahlung", "Abschläge, Gutschriften, Zusatzrechnung und behaupteten Restbetrag rechnerisch abstimmen.")),
    )
    d = P.prepare(meta.slug)
    contractor = "Wolfhager Straße 188 · 34127 Kassel\nTelefon 0561 830 44 10 · buero@gruenwerk-habichtswald.de\nHRB 19422 AG Kassel · IBAN DE52 5205 0353 0018 7741 09"
    record(d, "01_angebot_und_auftrag_gartenumbau.docx", org="Grünwerk Habichtswald GmbH", strapline="Garten- und Landschaftsbau", contact=contractor, title="Angebot GW-26-041 und Auftrag", metadata=[("Auftraggeberin", "Ingrid Möller, Dörnbergstraße 44, Kassel"), ("Angebotsdatum", "18.02.2026"), ("Auftrag", "02.03.2026"), ("Nettoangebot", "26756.30 EUR")], sections=[("1. Leistungsumfang", ["Vorgesehen sind Rückbau der alten Waschbetonplatten, Geländeabfangung über 11.8 Meter, Natursteinmauer aus Basalt, 42 Quadratmeter wasserdurchlässiges Pflaster, drei Stufen zum Wintergarten und die Wiederherstellung der Rasenfläche. Der angebotene Bruttopreis beträgt 31840 EUR.", "Die Mauer soll nach der Skizze des Bauleiters an der Grundstücksgrenze eine sichtbare Höhe zwischen 65 und 92 Zentimetern erhalten. Für nicht erkennbare Leitungen oder nicht tragfähigen Boden nennt das Angebot nur Abrechnung nach Aufwand nach vorheriger Abstimmung."]), ("2. Zahlung und Ansprechpartner", ["30 Prozent sind bei Arbeitsbeginn, 40 Prozent nach Fertigstellung der Mauer und der Rest nach gemeinsamer Abnahme fällig. Ingrid Möller benannte ihre Tochter Dr. Katja Möller als Ansprechpartnerin für Termine, weil sie selbst vormittags zur Physiotherapie fährt.", "Änderungen mit Mehrkosten sollen schriftlich bestätigt werden. Bauleiter Sven Rabe notierte bei Auftragserteilung handschriftlich Tochter darf vor Ort entscheiden. Eine Vollmacht mit Betrag oder Laufzeit wurde nicht beigefügt."])], signer="Sven Rabe", signer_role="Bauleiter")
    record(d, "02_nachtragsangebot_entwaesserung.docx", org="Grünwerk Habichtswald GmbH", strapline="Baustelle Dörnbergstraße 44", contact=contractor, title="Nachtrag 1 – Drainage, Boden und zweite Stufenanlage", metadata=[("Datum", "24.03.2026"), ("Bezug", "GW-26-041"), ("Nachtrag brutto", "6420.05 EUR"), ("Baustand", "Aushub zu 60 Prozent")], sections=[("1. Anlass", ["Beim Aushub trat unter der alten Terrasse bindiger, nasser Boden auf. Der Polier empfahl eine Drainageleitung mit Kontrollschacht und zusätzlichen Frostschutz. Zudem bat Katja Möller um zwei flachere Stufen am Seitentor, damit ihre Mutter den Weg mit Rollator nutzen könne.", "Das Nachtragsblatt führt 18 Meter Drainagerohr, 7.4 Kubikmeter Frostschutz, Entsorgung Bodenklasse und eine zweite Stufenanlage auf. Handschriftlich steht telefonisch mit Frau Dr. Möller 24.3., 11:10 Uhr, bitte machen."]), ("2. Preis und Ausführung", ["Der Preis wurde aus Einheitspreisen und sechs zusätzlichen Maschinenstunden gebildet. Eine Unterschrift der Auftraggeberin fehlt. Katja Möller antwortete am selben Tag per E-Mail, die Arbeiten sollten wegen angekündigten Regens nicht stillstehen.", "Die Drainage wurde am 25. und 26. März eingebaut. Der Kontrollschacht liegt laut Aufmaß 1.6 Meter weiter westlich als in der Nachtragsskizze. Die zweite Stufenanlage war am 2. April fertig."])], signer="Sven Rabe", signer_role="Bauleiter")
    record(d, "03_maengelanzeige_stuetzmauer.docx", org="Ingrid Möller", strapline="Dörnbergstraße 44 · 34131 Kassel", contact="Telefon 0561 314 06 22 · Zustellung per Einwurf-Einschreiben", title="Risse, lose Stufen und Wasserlauf", metadata=[("Empfängerin", "Grünwerk Habichtswald GmbH"), ("Datum", "29.04.2026"), ("Bezug", "Auftrag GW-26-041"), ("Frist", "12.05.2026")], sections=[("1. Beobachtungen", ["Nach dem Starkregen am 24. April zeigte sich ein durchgehender feuchter Streifen am Fuß der neuen Mauer. An zwei Stoßfugen sind Risse sichtbar. Die obere Randreihe lässt sich an einer Stelle mit der Hand bewegen. Die zweite Stufe am Seitentor wackelt beim Auftreten.", "Wasser läuft nicht zum Kontrollschacht, sondern sammelt sich am Wintergarten. Der Nachbar Ulrich Vaupel sah am 25. April gegen 08:30 Uhr eine Pfütze von etwa zwei Metern Länge. Fotos wurden am 25. und 28. April aufgenommen."]), ("2. Termin und Zahlung", ["Ich bitte um gemeinsame Besichtigung und fachgerechte Beseitigung. Bis zur Klärung zahle ich die Schlussrechnung nicht vollständig. Die Abschläge von 9552 EUR und 12736 EUR wurden am 9. März und 6. April überwiesen.", "Eine Abnahme fand nicht statt. Der Bauleiter hinterließ am 8. April eine Karte mit dem Vermerk fertig, weil ich bei einem Arzttermin war. Meine Tochter erhielt erst später ein Foto dieser Karte."])], signer="Ingrid Möller", signer_role="Auftraggeberin")
    record(d, "04_zahlungsaufforderung_tochter.docx", org="Kanzlei Röttger und Hain", strapline="Rechtsanwälte · Bau- und Forderungsrecht", contact="Königsplatz 55 · 34117 Kassel\nTelefon 0561 920 18 60 · kanzlei@roettger-hain.de\nAktenzeichen RH-1184/26", title="Zahlungsaufforderung aus Einstandserklärung", metadata=[("Adressatin", "Dr. Katja Möller, Friedrich-Ebert-Straße 102, Kassel"), ("Mandantin", "Grünwerk Habichtswald GmbH"), ("Datum", "18.05.2026"), ("Forderung", "11860.05 EUR zuzüglich Zinsen")], sections=[("1. Forderungsdarstellung", ["Unsere Mandantin beansprucht den offenen Rest aus Hauptauftrag und Nachtrag. Nach Abzug der beiden Abschläge und einer Kulanzgutschrift von 4112 EUR verbleiben 11860.05 EUR. Die Mängelanzeige Ihrer Mutter sei nach Auffassung unserer Mandantin weitgehend unbegründet; ein Besichtigungstermin wurde für den 7. Mai angeboten.", "Sie teilten am 24. März per E-Mail mit, die Firma solle weiterarbeiten und Sie stünden dafür ein, dass alles bezahlt werde. Unsere Mandantin habe nur aufgrund dieser Erklärung Drainage und zusätzliche Stufen ohne Unterschrift Ihrer Mutter ausgeführt."]), ("2. Frist und Unterlagen", ["Wir fordern Zahlung bis 29. Mai 2026. Hilfsweise bitten wir um Mitteilung, ob Sie die Erklärung als bloße Terminfreigabe verstehen. Legen Sie gegebenenfalls den vollständigen E-Mail-Verlauf vor.", "Die Ansprüche gegen Ingrid Möller werden unabhängig weiterverfolgt. Mit diesem Schreiben ist keine Erklärung verbunden, auf Einwendungen gegen die Werkleistung zu verzichten."])], signer="Rechtsanwältin Theresa Röttger", signer_role="Fachanwältin für Bau- und Architektenrecht")
    email(d, "05_email_tochter_weitermachen.eml", sender="katja.moeller@radiologie-kassel.de", recipients=["sven.rabe@gruenwerk-habichtswald.de"], cc=["ingrid.moeller@posteo.de"], date="Tue, 24 Mar 2026 11:26:00 +0100", subject="Dörnbergstraße 44 / Drainage und Stufen – bitte nicht stoppen", message_id="<km-gw-26-041-202603241126@radiologie-kassel.de>", body="Sehr geehrter Herr Rabe,\n\nmeine Mutter erreicht gerade niemanden, weil sie in der Behandlung ist. Bitte bauen Sie die Drainage ein und machen Sie die zwei flacheren Stufen, damit die offene Baugrube vor dem Regen geschlossen wird. Sie hatte mir gesagt, dass der Garten am Ende funktionieren soll und ich vor Ort entscheiden darf.\n\nWegen des Geldes müssen Sie sich keine Sorgen machen. Ich stehe dafür ein, dass alles bezahlt wird, wenn Sie es so wie heute besprochen ausführen. Schicken Sie mir bitte heute noch das vollständige Nachtragsblatt; bisher habe ich nur das Foto mit den vier Positionen. Ich kläre den Betrag heute Abend mit meiner Mutter.\n\nMit freundlichen Grüßen\nDr. Katja Möller\nFriedrich-Ebert-Straße 102, 34119 Kassel\nTelefon 0176 442 18 902")
    email(d, "06_email_bauleiter_besichtigung.eml", sender="sven.rabe@gruenwerk-habichtswald.de", recipients=["ingrid.moeller@posteo.de"], cc=["katja.moeller@radiologie-kassel.de"], date="Mon, 4 May 2026 07:38:00 +0200", subject="GW-26-041 / Besichtigung Ihrer Hinweise am 7. Mai", message_id="<gw-26-041-202605040738@gruenwerk-habichtswald.de>", body="Sehr geehrte Frau Möller,\n\nwir können am Donnerstag, 7. Mai, zwischen 09:30 und 10:30 Uhr vor Ort sein. Bitte bestätigen Sie, ob Sie oder Ihre Tochter Zugang zum Seitentor ermöglichen. Den losen Stein und die Stufe sehen wir uns an. Nach unseren Fotos stammt der Wasserfilm vom noch nicht angewachsenen Oberboden; der Kontrollschacht war am 8. April frei.\n\nBitte halten Sie Ihre Fotos im Original mit Aufnahmedatum bereit. Unser Polier bringt Aufmaß und Lieferscheine mit. Eine förmliche Abnahme ist bisher nicht unterschrieben. Die am Gartentor hinterlassene Fertigmeldung sollte nur den Abschluss der täglichen Arbeiten dokumentieren.\n\nMit freundlichen Grüßen\nSven Rabe\nBauleiter\nGrünwerk Habichtswald GmbH\nTelefon 0561 830 44 13")
    P.write_txt(d / "07_whatsapp_familie_gartenkosten.txt", """WhatsApp-Export · Ingrid und Katja Möller · 24.03.2026 bis 27.03.2026

24.03. 10:58 Katja: Der Bauleiter sagt, ohne Drainage läuft später alles gegen den Wintergarten. Mehrpreis angeblich etwa sechstausend.
24.03. 11:02 Ingrid: Ich sitze beim Arzt. Der Garten muss zu, aber sechstausend habe ich nicht einfach so zugesagt.
24.03. 11:05 Katja: Soll ich sagen, sie sollen weitermachen? Regen kommt morgen.
24.03. 11:07 Ingrid: Ja, wenn es nötig ist. Frag nach einem richtigen Zettel und ob bei den Steinen etwas wegfällt.
24.03. 11:31 Katja: Habe gemailt, damit sie nicht stoppen. Nachtrag soll kommen. Ich habe geschrieben, dass bezahlt wird, sonst hätten sie aufgehört.
24.03. 11:34 Ingrid: Von meinem Konto, aber erst wenn alles stimmt. Bitte nicht versprechen, dass du selbst zahlst.
25.03. 18:12 Katja: Rohr ist drin. Sven hat Nachtrag als Foto geschickt. 6420.05 brutto.
27.03. 09:44 Ingrid: Das Wasser steht schon wieder am Fenster. Bitte fotografieren, wenn du heute kommst.
""")
    P.write_csv(d / "08_rechnungen_abschlaege_gutschrift.csv", ["Datum", "Beleg", "Position", "Brutto_EUR", "Zahlung_EUR", "Offen_EUR", "Hinweis"], [["2026-03-02", "GW-26-041", "Hauptauftrag", "31840", "0", "31840", ""], ["2026-03-09", "AZ-1", "Abschlag Arbeitsbeginn", "9552", "9552", "0", "gezahlt Ingrid Möller"], ["2026-04-06", "AZ-2", "Abschlag Mauer", "12736", "12736", "0", "gezahlt Ingrid Möller"], ["2026-04-14", "N-1", "Drainage und Stufen", "6420.05", "0", "6420.05", "keine Unterschrift"], ["2026-04-20", "SR-1", "Schlussrechnung Hauptauftrag", "9552", "0", "9552", ""], ["2026-05-08", "GS-1", "Kulanzgutschrift", "-4112", "0", "-4112", "Preisnachlass und nicht ausgeführte Pflanzung"]])
    P.write_csv(d / "09_aufmass_mauer_entwaesserung.csv", ["Punkt", "Planwert", "Istwert_08_04", "Einheit", "Quelle", "Bemerkung"], [["Mauerlänge", "11.8", "12.1", "Meter", "Aufmaß Rabe", "Bogen am Apfelbaum"], ["Höhe West", "0.65", "0.71", "Meter", "Foto Maßstab", ""], ["Höhe Ost", "0.92", "0.88", "Meter", "Foto Maßstab", ""], ["Drainage", "18", "19.6", "Meter", "Lieferschein", "Verschnitt enthalten"], ["Schacht Abstand Grenze", "2.4", "4.0", "Meter", "Aufmaß Rabe", "Skizze abweichend"], ["Stufenbreite Seitentor", "1.1", "1.08", "Meter", "Aufmaß 08.04", "zweite Stufe locker gemeldet"]])
