def build_bgb_maehroboter() -> None:
    meta = CaseMeta(
        slug="bgb-maehroboter-cloud-update-muenster",
        title="BGB: Mähroboter, Cloud-Zwang und fehlerhaftes Update in Münster",
        plugins=("bgb-bt-pruefer", "verbraucherschutzrecht-pruefer", "produktrecht", "agb-recht-pruefer"),
        summary="Familie Aydin kauft einen Mähroboter mit Kameranavigation und beworbenem Betrieb ohne Begrenzungskabel. Nach Firmware 4.8.2 verliert das Gerät die Gartenkarte, fährt in ein Staudenbeet und verlangt für bisherige Funktionen ein neues Cloud-Abo; Händler und Hersteller verweisen aufeinander.",
        closing="Kaufversprechen, Updatehinweise, Protokolle, Serviceantworten und Grundstücksdaten erlauben eine getrennte Prüfung von Hardware, digitalem Element, Aktualisierung und Abo. Ursache und Verantwortungsbereich bleiben anhand der widersprüchlichen Rohdaten zu klären.",
        checks=(("digital", "Paragrafen 475b bis 475e BGB auf die Ware mit digitalen Elementen anwenden; Paragraf 327f BGB nur für einen rechtlich eigenständigen Digitalvertrag heranziehen."), ("mangel", "Vereinbarte und objektive Anforderungen aus Werbung, Bestellung und Anleitung mit dem Verhalten vor und nach Update vergleichen."), ("beweislast", "Paragraf 477 BGB zeitlich einordnen und Installations-, Nutzungs- sowie Serverdaten als Beweismittel würdigen."), ("agb", "Abo-Umstellung und Änderungsklauseln an Paragrafen 305c und 307 BGB prüfen.")),
    )
    d = P.prepare(meta.slug)
    seller = "Hammer Straße 164 · 48153 Münster\nTelefon 0251 590 47 20 · service@gartenstrom-west.de\nHRB 18804 AG Münster"
    record(d, "01_bestellung_rechnung_werbeversprechen.docx", org="Gartenstrom West GmbH", strapline="Gartentechnik und Robotik", contact=seller, title="Bestellung GS-260318-441", metadata=[("Käufer", "Leyla und Murat Aydin"), ("Produkt", "MeadowPilot Vision X2"), ("Kaufdatum", "18.03.2026"), ("Gesamtpreis", "2699 EUR")], sections=[("1. Lieferumfang", ["Geliefert werden Roboter, Ladestation, zwei Funkbaken, Netzteil und App-Zugang. Die Produktseite bezeichnet VisionMap als dauerhafte Kameranavigation ohne Begrenzungsdraht und nennt kostenlose Sicherheits- und Funktionsaktualisierungen für mindestens fünf Jahre.", "Im Preis enthalten ist CloudBasis für Kartenbackup, Diebstahlortung und Wettersteuerung. Das Bestellblatt nennt keinen jährlichen Preis. Der Verkäufer installierte Ladestation und Gartenkarte am 23. März; das Übergabeprotokoll weist eine vollständig kartierte Fläche von 684 Quadratmetern aus."]), ("2. Einweisung", ["Servicetechnikerin Jule Bender erklärte, automatische Updates könnten nachts installiert werden. Ein Aufschub sei in der App für höchstens sieben Tage möglich. Familie Aydin aktivierte Updates, weil das Gerät laut Hinweis sonst keine Diebstahlortung mehr bieten könne.", "Die Grundstückskarte schloss Teich, Sandkasten und Staudenbeet aus. Ein schmaler Durchgang von 92 Zentimetern zwischen Garage und Hecke wurde zweimal erfolgreich getestet."])], signer="Jule Bender", signer_role="Servicetechnikerin")
    record(d, "02_updatehinweis_firmware_4_8_2.docx", org="MeadowPilot Europe GmbH", strapline="Produktinformation Vision X2", contact="Rheinpromenade 88 · 40213 Düsseldorf\nTelefon 0211 770 81 0 · support@meadowpilot-europe.de", title="Firmware 4.8.2 und CloudBasis-Umstellung", metadata=[("Veröffentlichung", "11.06.2026"), ("Installation Gerät", "13.06.2026, 02:14 Uhr"), ("Geräte-ID", "MPX2-DE-8841-2097"), ("App-Version", "6.4.0")], sections=[("1. Änderungen", ["Firmware 4.8.2 aktualisiert die Hinderniserkennung, komprimiert gespeicherte Karten und führt einen neuen Abgleich mit den Funkbaken ein. Nutzer sollen nach Installation eine Kontrollfahrt an Teichen, Stufen und engen Passagen ausführen. Die vorhandene Karte soll automatisch übernommen werden.", "Im Updatefenster stand, Kartenbackup und Fernzugriff würden ab 1. Juli in CloudPlus zusammengeführt. Ohne CloudPlus bleibe lokales Mähen möglich; Wettersteuerung, Kartensicherung und Fernzugriff seien dann deaktiviert. Der Preis wird mit 7.99 EUR monatlich genannt."]), ("2. Hinweise bei Störung", ["Bei versetzter Karte soll das Gerät an die Ladestation gestellt und die Funktion Karte neu ausrichten gewählt werden. Eine vollständige Neukartierung wird erst nach zwei erfolglosen Ausrichtungen empfohlen.", "Das Protokoll des Geräts zeigt am 13. Juni um 02:19 Uhr eine erfolgreiche Migration. Um 07:04 Uhr folgt der Eintrag Beacon B2 drift 1.8m. In der App wurde dieser Eintrag nicht angezeigt."])], signer="Produktservice MeadowPilot", signer_role="Technische Information")
    record(d, "03_stoerungsprotokoll_und_schaden.docx", org="Leyla und Murat Aydin", strapline="Hafenweg 27 · 48155 Münster", contact="Telefon 0251 321 88 47 · leyla.aydin@posteo.de", title="Ablauf nach dem Update", metadata=[("Gerät", "MeadowPilot Vision X2"), ("Update", "13.06.2026"), ("Schadentag", "14.06.2026"), ("Ticket", "MP-441088")], sections=[("1. Verlauf", ["Am 13. Juni zeigte die App die Gartenkarte um etwa einen Meter nach Osten verschoben. Murat Aydin wählte zweimal Karte neu ausrichten. Die erste Fahrt endete mit der Meldung Position unsicher. Am 14. Juni startete der Zeitplan um 06:30 Uhr automatisch.", "Um 06:47 Uhr fuhr der Roboter durch die bisherige Sperrzone und beschädigte acht junge Pfingstrosen. Anschließend blieb er an der Teichkante mit dem rechten Rad im Wasser hängen. Nachbarin Sophie Wessel zog das Gerät am Griff heraus und fotografierte Position und Fahrspur."]), ("2. Folgen und Sicherung", ["Das Gerät wurde nicht erneut betrieben. In der App waren zunächst nur die letzten 24 Stunden verfügbar. Nach Öffnung des Supporttickets verschwand die alte Karte aus der Ansicht. Ein lokaler Export vom 15. Juni enthält Ereignisse, aber keine Bilddaten der Kamera.", "Die Gärtnerei schätzt Ersatzpflanzen und Neuanlage auf 486 EUR. Am Gerät sind Feuchtigkeitsspuren im rechten Radkasten sichtbar; es lässt sich laden, meldet aber Kamerakalibrierung erforderlich."])], signer="Leyla Aydin", signer_role="Käuferin")
    record(d, "04_haendlerantwort_nacherfuellung.docx", org="Gartenstrom West GmbH", strapline="Kundendienst", contact=seller, title="Antwort auf Mängelanzeige", metadata=[("Ticket", "GS-REK-260619"), ("Datum", "22.06.2026"), ("Kunde", "Aydin"), ("Geräte-ID", "MPX2-DE-8841-2097")], sections=[("1. Untersuchung", ["Der Roboter wurde am 19. Juni angenommen. Mechanik, Akku und Ladestation zeigen im Kurztest keine Auffälligkeit. Im Radkasten fanden sich geringe Feuchtigkeit und Erde. Eine Kamerakalibrierung konnte ohne das Grundstück und die Funkbaken nicht abgeschlossen werden.", "Nach Auskunft des Herstellers wurde Firmware 4.8.2 ordnungsgemäß installiert. Das Serverprotokoll weist eine Abweichung der Funkbake B2 aus. Ob die Bake bewegt, gestört oder durch die Migration falsch zugeordnet wurde, lasse sich in der Werkstatt nicht feststellen."]), ("2. Weiteres Vorgehen", ["Wir bieten einen Vor-Ort-Termin zur Neukartierung an. Für eine Rückabwicklung oder Ersatzlieferung sehen wir derzeit keinen Anlass. Die Kosten des Pflanzenbeets können wir ohne Prüfung der Sicherungszonen nicht übernehmen.", "CloudPlus ist ein Vertrag mit dem Hersteller. Nach unserer Auffassung bleibt die lokale Mähfunktion auch ohne Abo bestehen. Bitte teilen Sie mit, ob Sie den Termin am 30. Juni wahrnehmen."])], signer="Saskia Nolte", signer_role="Leitung Kundendienst")
    email(d, "05_email_support_beacon_drift.eml", sender="support@meadowpilot-europe.de", recipients=["leyla.aydin@posteo.de"], cc=["service@gartenstrom-west.de"], date="Wed, 17 Jun 2026 15:22:00 +0200", subject="Ticket MP-441088 / Beacon B2 und Kartenmigration", message_id="<mp-441088-202606171522@meadowpilot-europe.de>", body="Sehr geehrte Frau Aydin,\n\nwir sehen eine erfolgreiche Migration der Karte am 13. Juni um 02:19 Uhr und ab 07:04 Uhr eine Abweichung der Funkbake B2 von 1.8 Metern. Das Gerät hat die Abweichung am 14. Juni vor dem Start erneut gemessen, aber als noch nutzbar eingestuft. Wir können nicht aus der Ferne erkennen, ob die Bake physisch versetzt wurde oder die Koordinaten fehlerhaft waren.\n\nBitte verändern Sie die Position der Baken nicht und senden Sie Fotos mit sichtbarem Abstand zu festen Gebäudekanten. Der Händler kann beim Vor-Ort-Termin eine Diagnosekarte erzeugen. Die Kamerabilder werden aus Schutzgründen nicht dauerhaft auf unseren Servern gespeichert.\n\nCloudPlus beeinflusst die lokale Hinderniserkennung nicht. Kartenbackup und Wiederherstellung setzen ab 1. Juli jedoch ein aktives Paket voraus.\n\nMit freundlichen Grüßen\nNils Gärtner\nTechnical Support MeadowPilot Europe GmbH\nTelefon 0211 770 81 328")
    email(d, "06_email_nachbarin_foto_zeugenangaben.eml", sender="sophie.wessel@mailbox.org", recipients=["leyla.aydin@posteo.de"], cc=[], date="Sun, 14 Jun 2026 09:12:00 +0200", subject="Fotos von heute früh / Mäher am Teich", message_id="<sw-hafenweg-202606140912@mailbox.org>", body="Hallo Leyla,\n\nich schicke dir die vier Originalfotos von heute Morgen. Ich war gegen 06:45 Uhr mit dem Hund im Garten und habe euren Mäher erst im Beet gehört. Er fuhr in kleinen Bögen, obwohl dort sonst nie gemäht wird. Zwei Minuten später stand das rechte Rad im Wasser und der Motor drehte noch.\n\nIch habe ihn nur am hinteren Griff herausgezogen und auf die Steinplatte gestellt. Die Funkbake an der Garage habe ich nicht angefasst. Am Freitagabend stand sie nach meiner Erinnerung genauso dicht am Fallrohr wie auf dem Foto. Murat hatte mich vor zwei Wochen gebeten, beim Heckenschneiden Abstand zu halten.\n\nRuf gern an, wenn der Händler wissen will, was ich gesehen habe.\n\nViele Grüße\nSophie Wessel\nHafenweg 29, 48155 Münster\nTelefon 0251 321 88 61")
    P.write_txt(d / "07_app_chat_cloudabo.txt", """In-App-Chat MeadowPilot · Ticket MP-441088 · 15.06.2026

09:04 Leyla Aydin: Seit Update ist die Karte verschoben. Gestern fuhr X2 in Beet und Teich. Wie bekomme ich die Karte von vor dem Update zurück?
09:06 Bot: Kartenwiederherstellung ist Bestandteil von CloudPlus. Möchten Sie CloudPlus aktivieren?
09:07 Leyla Aydin: Nein. Beim Kauf war Kartenbackup enthalten. Ich will nur meinen Stand vom 12. Juni.
09:11 Support Mika: Ihr Basiszeitraum läuft bis 30. Juni. Ich prüfe, ob ein Backup vorhanden ist.
09:24 Support Mika: Auf dem Konto liegt eine Karte vom 13. Juni nach Migration. Eine ältere Version sehe ich nicht.
09:28 Leyla Aydin: Die alte Karte war fünf Jahre versprochen und seit März aktiv. Warum wurde sie überschrieben?
09:36 Support Mika: Firmware 4.8.2 migriert Karten in das neue Format. Bei erfolgreicher Migration wird die Vorversion nach 48 Stunden gelöscht. Ihr Ticket wurde am 15. Juni eröffnet.
09:40 Leyla Aydin: Bitte nichts mehr löschen und alle Logs sichern.
09:42 Support Mika: Sicherungsmarke bis 15. Juli gesetzt. Händler erhält Diagnosezugang nach Ihrer Freigabe.
""")
    P.write_csv(d / "08_geraeteereignisse_update.csv", ["Zeitpunkt", "Code", "Meldung", "Position_X", "Position_Y", "Aktion", "Quelle"], [["2026-06-13 02:14", "FW-INSTALL", "Firmware 4.8.2 installiert", "", "", "Neustart", "Geräteexport"], ["2026-06-13 02:19", "MAP-MIG", "Kartenmigration erfolgreich", "", "", "Vorversion markiert", "Serverlog"], ["2026-06-13 07:04", "B2-DRIFT", "Beacon B2 drift 1.8m", "12.44", "8.09", "Toleriert", "Serverlog"], ["2026-06-13 18:31", "ALIGN-1", "Ausrichtung fehlgeschlagen", "", "", "Abbruch", "App-Export"], ["2026-06-14 06:30", "SCHED", "Zeitplan gestartet", "", "", "Mähen", "Geräteexport"], ["2026-06-14 06:47", "WHEEL-SLIP", "Radschlupf rechts", "18.12", "4.77", "Motor weiter", "Geräteexport"], ["2026-06-14 06:49", "LIFT", "Gerät angehoben", "18.08", "4.70", "Stopp", "Geräteexport"]])
    P.write_csv(d / "09_kosten_abo_pflanzen.csv", ["Datum", "Position", "Betrag_EUR", "Beleg", "Status", "Bemerkung"], [["2026-03-18", "MeadowPilot Vision X2", "2699", "GS-260318-441", "bezahlt", "einschließlich Installation"], ["2026-06-15", "Gärtnerei Ersatzpflanzen", "486", "KV-260615", "Angebot", "acht Pfingstrosen und Boden"], ["2026-06-19", "Transport zum Händler", "38", "Taxi-Quittung", "bezahlt", "Gerät passte nicht ins Auto"], ["2026-07-01", "CloudPlus", "7.99", "App-Anzeige", "nicht gebucht", "monatlich"], ["2026-07-02", "Vor-Ort-Neukartierung", "149", "Händlerangebot", "offen", "Kostenübernahme streitig"]])
    P.write_device_photo(d / "10_foto_maeher_teichkante.jpg", "Hafenweg 27 · 14.06.2026", ["Rechtes Rad im flachen Teichrand", "Fahrspur durch Pfingstrosenbeet", "Funkbake B2 am Garagenfallrohr", "Aufnahme Sophie Wessel · 06:49 Uhr", "Originaldatei IMG_6142.JPG"], (67, 112, 86))
    files = [("01_bestellung_rechnung_werbeversprechen.docx", "Kaufbeleg, Funktionsversprechen und Installation"), ("02_updatehinweis_firmware_4_8_2.docx", "Updateinhalt und Cloud-Umstellung"), ("03_stoerungsprotokoll_und_schaden.docx", "Chronologie des Kartenfehlers und Schadens"), ("04_haendlerantwort_nacherfuellung.docx", "Werkstattbefund und Vor-Ort-Angebot"), ("05_email_support_beacon_drift.eml", "Herstellerdaten zur abweichenden Funkbake"), ("06_email_nachbarin_foto_zeugenangaben.eml", "Zeitnahe Zeugenmail mit Fotoangaben"), ("07_app_chat_cloudabo.txt", "Supportchat zu Backup und Abo"), ("08_geraeteereignisse_update.csv", "Technischer Ereignisexport"), ("09_kosten_abo_pflanzen.csv", "Kauf-, Schaden- und Folgekosten"), ("10_foto_maeher_teichkante.jpg", "Bildanlage zum Standort des Geräts")]
