def build_bgb_verbraucherdarlehen() -> None:
    meta = CaseMeta(
        slug="bgb-verbraucherdarlehen-lastenrad-potsdam",
        title="BGB: Verbraucherdarlehen für ein Lastenrad in Potsdam",
        plugins=("bgb-bt-pruefer", "fachanwalt-bank-kapitalmarktrecht", "verbraucherschutzrecht-pruefer"),
        summary="Erzieherin Jasmin Berger finanziert im Fahrradladen ein Lastenrad samt Restschuldversicherung. Nach Liefermängeln, Trennung vom Mitdarlehensnehmer und zwei ausgebliebenen Raten kündigt die Bank; Vertragskopien, Pflichtangaben, Versicherungsbeitrag und Händlerzahlung sind nicht in allen Fassungen gleich.",
        closing="Kauf, Finanzierung, Versicherung, Widerrufsinformation, Auszahlung und Zahlungsstörung sind dokumentenweise getrennt. Die Akte ermöglicht die Prüfung verbundener Verträge, ohne eine Rückabwicklung oder Wirksamkeit vorzugeben.",
        checks=(("form", "Paragrafen 491, 492 und 494 BGB sowie Artikel 247 EGBGB auf die tatsächlich ausgehändigten Fassungen anwenden."), ("widerruf", "Paragraf 495 BGB und die konkreten Pflichtangaben, Datenträger und Zugangszeitpunkte prüfen."), ("verbund", "Paragrafen 358 und 359 BGB auf Kauf, Finanzierung und Restschuldversicherung differenziert beziehen."), ("kuendigung", "Zahlungsverlauf und Voraussetzungen einer Kündigung wegen Verzugs nach Paragraf 498 BGB einschließlich Nachfrist und Rückstandsquote berechnen.")),
    )
    d = P.prepare(meta.slug)
    bank = "Breite Straße 29 · 14467 Potsdam\nTelefon 0331 701 44 0 · kreditservice@havelland-kredit.de\nBIC HAKRDEB1XXX"
    record(d, "01_kaufvertrag_lastenrad.docx", org="Radkontor Havel GmbH", strapline="Familienräder und Werkstatt", contact="Babelsberger Straße 16 · 14473 Potsdam\nTelefon 0331 550 27 90 · verkauf@radkontor-havel.de\nHRB 37218 P", title="Kaufvertrag CargoBee Family 4", metadata=[("Käuferin", "Jasmin Berger"), ("Bestellung", "09.02.2026"), ("Übergabe", "28.02.2026"), ("Kaufpreis", "7890 EUR")], sections=[("1. Ausstattung und Zahlung", ["Bestellt wurden Lastenrad CargoBee Family 4, Doppelakku, Regendach, zwei Kindersitze und GPS-Modul. Die Käuferin zahlte 900 EUR an. Der Rest sollte über die am Verkaufstresen vermittelte Havelland Kreditbank AG finanziert und unmittelbar an den Händler ausgezahlt werden.", "Das Verkaufsgespräch führte Dennis Krause. Er trug als Mitnutzer und zweiten Darlehensnehmer den damaligen Lebensgefährten Oliver Hahn ein, weil dessen Einkommen nach seiner Aussage die Genehmigung erleichtere. Der Kaufvertrag selbst nennt nur Jasmin Berger als Käuferin."]), ("2. Übergabe und Beanstandungen", ["Bei Übergabe fehlte der zweite Akku. Das Regendach hatte an der linken Naht eine offene Stelle. Im Protokoll steht Akku wird bis 15. März nachgeliefert; zur Naht ist nur Foto aufgenommen vermerkt.", "Der zweite Akku wurde am 21. März geliefert. Das Rad meldete ab April wiederholt GPS offline. Der Händler bot ein Softwareupdate an, führte es aber bis zur Zahlungsstörung nicht durch."])], signer="Dennis Krause", signer_role="Verkaufsberater")
    record(d, "02_darlehensvertrag_pflichtangaben.docx", org="Havelland Kreditbank AG", strapline="Verbraucherfinanzierung", contact=bank, title="Allgemein-Verbraucherdarlehensvertrag HK-260209-8841", metadata=[("Darlehensnehmer", "Jasmin Berger / Oliver Hahn"), ("Nettodarlehen", "7418 EUR"), ("Laufzeit", "36 Monate"), ("Sollzins", "8.17 Prozent gebunden")], sections=[("1. Finanzierung", ["Vom Nettodarlehen entfallen 6990 EUR auf den Kaufpreisrest und 428 EUR auf den Einmalbeitrag einer Ratenschutzversicherung. Der effektive Jahreszins ist in der Kundenkopie mit 8.49 Prozent, in der elektronischen Bankfassung mit 9.12 Prozent ausgewiesen. Die monatliche Rate beträgt 233.14 EUR ab 1. April 2026.", "Die Bank zahlte 6990 EUR am 12. Februar an Radkontor Havel und 428 EUR an Nordstern Ratenschutz AG. Jasmin Berger und Oliver Hahn unterzeichneten auf einem Signaturpad. Die ausgedruckte Kundenkopie trägt nur die eingescannte Unterschrift der Bank."]), ("2. Erklärungen und Kommunikation", ["Die Widerrufsinformation nennt eine Frist von vierzehn Tagen und verweist für Pflichtangaben auf Abschnitt 3. In der ausgehändigten Papierkopie fehlen die Seiten 7 und 8 mit dem Tilgungsplan; Jasmin Berger fotografierte die geheftete Kopie am Abend.", "Als Kommunikationsadresse ist die gemeinsame Wohnung Lindenstraße 48 eingetragen. Oliver Hahn zog am 4. Mai aus. Eine Änderungsmitteilung ging am 10. Mai über das Kundenportal ein, wurde aber nur im Profil von Jasmin Berger gespeichert."])], signer="Havelland Kreditbank AG", signer_role="Automatisiert erstellte Vertragsausfertigung")
    record(d, "03_ratenschutz_versicherungsschein.docx", org="Nordstern Ratenschutz AG", strapline="Arbeitsunfähigkeit und unfreiwillige Arbeitslosigkeit", contact="Aegidientorplatz 4 · 30159 Hannover\nTelefon 0511 809 31 0 · service@nordstern-ratenschutz.de", title="Versicherungsschein RS-8841-26", metadata=[("Versicherte", "Jasmin Berger"), ("Beginn", "12.02.2026"), ("Einmalbeitrag", "428 EUR"), ("Finanzierung", "HK-260209-8841")], sections=[("1. Schutzumfang", ["Versichert sind monatliche Darlehensraten nach einer Karenzzeit von 42 Tagen bei unverschuldeter Arbeitslosigkeit oder durch ärztliche Bescheinigung belegter Arbeitsunfähigkeit. Der Schutz endet mit vollständiger Rückzahlung oder spätestens nach 36 Monaten.", "Oliver Hahn ist nicht versicherte Person. Der Antrag enthält bei Jasmin Berger die Berufsangabe Erzieherin, unbefristet seit 2021. Eine Gesundheitsfrage wurde nicht gestellt."]), ("2. Abschlussunterlagen", ["Der Versicherungsschein verweist auf ein Beratungsprotokoll vom 9. Februar. In der Händlerakte liegt lediglich eine Auswahlseite mit den Feldern mit Schutz und ohne Schutz; mit Schutz ist angekreuzt. Jasmin Berger erklärte später, der Verkäufer habe die Versicherung als Voraussetzung der Bank bezeichnet.", "Eine gesonderte Widerrufsinformation wurde am 12. Februar um 18:04 Uhr per E-Mail versandt. Das E-Mail-Protokoll weist zugestellt aus; ein Öffnungsnachweis besteht nicht."])], signer="Nordstern Ratenschutz AG", signer_role="Vertragsservice")
    record(d, "04_mahnung_und_kuendigung_bank.docx", org="Havelland Kreditbank AG", strapline="Kreditservice und Rückstände", contact=bank, title="Kündigung und Gesamtfälligstellung", metadata=[("Vertrag", "HK-260209-8841"), ("Datum", "18.08.2026"), ("Rückstand", "466.28 EUR"), ("Gesamtforderung", "6928.44 EUR")], sections=[("1. Zahlungsverlauf", ["Die Raten April bis Juni wurden eingezogen. Die Lastschriften Juli und August wurden mangels Deckung zurückgegeben. Mit Schreiben vom 5. August setzte die Bank eine Zahlungsfrist bis 17. August und kündigte die Gesamtfälligstellung an.", "Das Schreiben vom 5. August ging laut Einwurfprotokoll am 8. August an der Lindenstraße 48 zu. Jasmin Berger wohnt dort weiterhin. Oliver Hahn hatte der Bank am 12. Mai telefonisch seine neue Anschrift genannt; ein schriftlicher Nachweis liegt der Bank nicht vor."]), ("2. Forderung", ["Die Bank verlangt Darlehenssaldo, Verzugszinsen, zwei Rücklastschriftkosten zu je 4.50 EUR und 18 EUR Mahnkosten. Eine Erstattung aus der Ratenschutzversicherung wurde nicht beantragt.", "Jasmin Berger hatte am 14. August 233.14 EUR überwiesen. Die Zahlung wurde am 19. August gutgeschrieben und im Kündigungsschreiben noch nicht berücksichtigt."])], signer="Ralf Nitz", signer_role="Team Kreditservice")
    email(d, "05_email_verkaeufer_versicherung_pflicht.eml", sender="jasmin.berger@posteo.de", recipients=["dennis.krause@radkontor-havel.de"], cc=["kreditservice@havelland-kredit.de"], date="Tue, 25 Aug 2026 10:18:00 +0200", subject="Finanzierung CargoBee / Ratenschutz und fehlende Vertragsseiten", message_id="<jb-hk-260209-8841-202608251018@posteo.de>", body="Sehr geehrter Herr Krause,\n\nbei Abschluss sagten Sie, die Bank genehmige die Finanzierung nur mit dem Ratenschutz und mit Oliver als zweitem Antragsteller. Jetzt verlangt die Bank den gesamten Rest, obwohl ich eine Rate nachgezahlt habe. Bitte senden Sie mir das Beratungsprotokoll und die vollständige Kopie, die am Verkaufstresen gespeichert wurde.\n\nMeine Papiermappe enthält nach Seite 6 sofort Seite 9. Dort fehlt auch die Berechnung des effektiven Jahreszinses. Außerdem steht in meiner Kopie 8.49 Prozent, im Bankportal 9.12 Prozent. Bitte erklären Sie, welche Fassung an die Bank ging.\n\nDas Rad hat weiterhin GPS-Ausfälle und das Regendach ist an der Naht offen. Den zweiten Akku habe ich erst am 21. März erhalten.\n\nMit freundlichen Grüßen\nJasmin Berger\nLindenstraße 48, 14467 Potsdam\nTelefon 0176 803 19 772")
    email(d, "06_email_bank_adressaenderung_oliver.eml", sender="oliver.hahn@web.de", recipients=["kreditservice@havelland-kredit.de"], cc=["jasmin.berger@posteo.de"], date="Wed, 20 May 2026 07:52:00 +0200", subject="HK-260209-8841 / neue Anschrift und keine Nutzung des Lastenrads", message_id="<oh-hk-260209-8841-202605200752@web.de>", body="Sehr geehrte Damen und Herren,\n\nich bin am 4. Mai aus der Lindenstraße 48 ausgezogen und wohne nun Am Kanal 7, 14473 Potsdam. Ich hatte die neue Adresse bereits am 12. Mai telefonisch mitgeteilt. Bitte bestätigen Sie die Änderung für alle Schreiben zum Darlehen.\n\nDas Lastenrad gehört Jasmin Berger und wird von ihr genutzt. Ich habe den Kredit im Laden mit unterschrieben, weil der Verkäufer sagte, sonst werde der Antrag nicht freigegeben. Eine eigene Vertragsmappe habe ich nicht erhalten. Die Raten wurden bisher allein vom Konto von Frau Berger eingezogen.\n\nBitte senden Sie mir eine vollständige Vertragsabschrift und einen aktuellen Tilgungsplan.\n\nMit freundlichen Grüßen\nOliver Hahn\nAm Kanal 7, 14473 Potsdam")
    P.write_txt(d / "07_chat_trennung_raten_lastenrad.txt", """WhatsApp-Export · Jasmin Berger / Oliver Hahn · 30.06.2026 bis 15.08.2026

30.06. 18:22 Jasmin: Juli-Rate geht von meinem Konto. Bitte überweise deine Hälfte wie besprochen.
30.06. 18:40 Oliver: Ich zahle nicht mehr für ein Rad, das ich nicht nutze. Im Laden hieß es nur Formalität.
01.07. 09:15 Jasmin: Du bist Mitdarlehensnehmer. Ohne dein Einkommen hätten sie es angeblich nicht gemacht.
05.07. 11:03 Oliver: Ich habe der Bank meine Adresse gegeben. Klär das mit Versicherung und Händler, das Rad war doch kaputt.
02.08. 08:11 Jasmin: Lastschrift wieder zurück. Mein Gehalt kommt erst Montag. Kannst du wenigstens eine Rate übernehmen?
02.08. 09:02 Oliver: Nein. Schick mir erst die Vertragskopie. Ich habe nie Seiten 7 und 8 gesehen.
08.08. 14:48 Jasmin: Mahnung lag heute im Briefkasten, Frist 17. August. Sie drohen mit Kündigung.
14.08. 17:26 Jasmin: Ich habe 233.14 überwiesen. Bank sagt telefonisch, zweite Rate fehlt trotzdem.
15.08. 10:07 Oliver: Ich schreibe ihnen noch mal wegen Adresse und Unterlagen. Mehr kann ich gerade nicht tun.
""")
    P.write_csv(d / "08_zahlungsplan_und_rueckstaende.csv", ["Faellig", "Rate_EUR", "Lastschrift", "Rueckgabe", "Nachzahlung", "Gutschrift", "Offen_nach_Gutschrift_EUR"], [["2026-04-01", "233.14", "2026-04-01", "", "", "2026-04-01", "0"], ["2026-05-01", "233.14", "2026-05-02", "", "", "2026-05-02", "0"], ["2026-06-01", "233.14", "2026-06-01", "", "", "2026-06-01", "0"], ["2026-07-01", "233.14", "2026-07-01", "2026-07-04", "", "", "233.14"], ["2026-08-01", "233.14", "2026-08-03", "2026-08-05", "2026-08-14", "2026-08-19", "233.14"], ["2026-09-01", "233.14", "", "", "", "", "noch nicht fällig"]])
    P.write_csv(d / "09_vertragsfassungen_abgleich.csv", ["Angabe", "Papier_Kundin", "Bankportal", "Haendlerakte", "Quelle_Datum", "Abweichung"], [["Nettodarlehen", "7418 EUR", "7418 EUR", "7418 EUR", "09.02.2026", "nein"], ["Effektiver Jahreszins", "8.49 Prozent", "9.12 Prozent", "8.49 Prozent", "09.02.2026", "ja"], ["Seiten", "1-6 und 9-12", "1-12", "1-12", "Foto 09.02.2026", "Seiten 7-8 fehlen"], ["Ratenschutz", "428 EUR", "428 EUR", "mit Schutz", "12.02.2026", "Beratungsprotokoll fehlt"], ["Mitdarlehensnehmer", "Oliver Hahn", "Oliver Hahn", "Oliver Hahn", "09.02.2026", "nein"], ["Erste Rate", "01.04.2026", "01.04.2026", "01.04.2026", "09.02.2026", "nein"]])
    P.write_device_photo(d / "10_foto_vertragsmappe_seitensprung.jpg", "Vertragsmappe vom 09.02.2026", ["Seite 6: Widerrufsinformation", "danach unmittelbar Seite 9", "Heftklammer unverändert", "Foto Jasmin Berger · 21:14 Uhr", "Datei IMG_2209.JPG"], (81, 92, 122))
    files = [("01_kaufvertrag_lastenrad.docx", "Kauf, Finanzierung und Übergabemängel"), ("02_darlehensvertrag_pflichtangaben.docx", "Darlehensdaten und abweichende Vertragsfassungen"), ("03_ratenschutz_versicherungsschein.docx", "Versicherungsschein und Abschlussumstände"), ("04_mahnung_und_kuendigung_bank.docx", "Rückstände, Frist und Gesamtfälligstellung"), ("05_email_verkaeufer_versicherung_pflicht.eml", "Kundin verlangt Beratungs- und Vertragsunterlagen"), ("06_email_bank_adressaenderung_oliver.eml", "Mitdarlehensnehmer meldet neue Adresse"), ("07_chat_trennung_raten_lastenrad.txt", "Privater Chat zu Raten und Rollen"), ("08_zahlungsplan_und_rueckstaende.csv", "Ratengenauer Zahlungsverlauf"), ("09_vertragsfassungen_abgleich.csv", "Abweichungen der drei Vertragskopien"), ("10_foto_vertragsmappe_seitensprung.jpg", "Foto der unvollständigen Papiermappe")]
