def build_bgb_bank_agb() -> None:
    meta = CaseMeta(
        slug="bgb-bank-agb-schliessfach-preis-mainz",
        title="BGB: Bankschließfach, Preiserhöhung und Wasserschaden in Mainz",
        plugins=("agb-recht-pruefer", "fachanwalt-bank-kapitalmarktrecht", "bgb-bt-pruefer"),
        summary="Helene Falkenberg nutzt seit 2017 ein Schließfach der Rhein-Main Privatbank. Die Bank erhöht Entgelt und Haftungsgrenze über das Onlinepostfach; nach einem Wassereintritt sind Urkunden und Schmuck beschädigt, während Inventarliste, Zutrittsprotokoll und Versicherungswert unterschiedliche Bilder ergeben.",
        closing="Vertrag, Bedingungsänderungen, Schadensbericht, Inhaltsbelege und Kommunikation ermöglichen die Prüfung von Einbeziehung, überraschender Klausel, Haftung und Schadenshöhe. Die Akte verrät weder Wirksamkeit noch Ersatzbetrag.",
        checks=(("agb", "Paragrafen 305 Absatz 2, 305c und 307 BGB auf Einbeziehung, Preisanpassung, Zustimmungsfiktion und Haftungsbegrenzung anwenden."), ("bankrecht", "BGH vom 27. April 2021, XI ZR 26/20, nur für Reichweite und Zustandekommen von Vertragsänderungen heranziehen."), ("pflichten", "Verwahrungs-, Schutz- und Aufklärungspflichten aus Vertrag, Zugangssystem und Schadensablauf entwickeln."), ("schaden", "Eigentum, Fachinhalt, Wiederbeschaffung, Zeitwert und Versicherung quellenbezogen trennen.")),
    )
    d = P.prepare(meta.slug)
    bank = "Große Bleiche 62 · 55116 Mainz\nTelefon 06131 881 0 · service@rheinmain-privatbank.de\nBIC RMPBDE5MXXX"
    record(d, "01_schliessfachvertrag_2017.docx", org="Rhein-Main Privatbank AG", strapline="Filiale Mainz · Schließfachanlage B", contact=bank, title="Miet- und Verwahrvertrag Schließfach B-417", metadata=[("Kundin", "Helene Falkenberg"), ("Vertragsbeginn", "01.09.2017"), ("Fach", "B-417 / Größe 3"), ("Jahresentgelt", "120 EUR")], sections=[("1. Nutzung", ["Die Kundin erhält einen mechanischen Kundenschlüssel; das Fach öffnet nur gemeinsam mit dem Bankschlüssel. Zutritte werden mit Datum und Uhrzeit protokolliert. Eine Inhaltsliste führt die Bank nicht.", "Der Vertrag nennt eine Grundversicherung bis 30000 EUR gegen Einbruch, Feuer und Leitungswasser. Höhere Werte können gegen Nachweis gemeldet werden. Bargeld, explosionsgefährliche Gegenstände und verderbliche Sachen dürfen nicht eingelagert werden."]), ("2. Haftung und Mitteilungen", ["Die Bedingungen 2017 begrenzen die Haftung bei einfacher Fahrlässigkeit auf den typischerweise vorhersehbaren Schaden, nennen aber keinen festen Höchstbetrag. Vertragsänderungen sollen in Textform angeboten werden.", "Als Postadresse ist die Kaiserstraße 14 in Mainz hinterlegt. Für Kontoauszüge nutzt Helene Falkenberg seit 2021 das Onlinepostfach. Eine ausdrückliche Vereinbarung, alle Schließfachmitteilungen nur dort bereitzustellen, liegt nicht in der Vertragsmappe."])], signer="Rhein-Main Privatbank AG", signer_role="Filiale Mainz")
    record(d, "02_bedingungsaenderung_2024_2025.docx", org="Rhein-Main Privatbank AG", strapline="Kundeninformation Schließfach", contact=bank, title="Änderungsmitteilungen und Preisverzeichnis", metadata=[("Postfachbereitstellung", "18.10.2024 und 02.09.2025"), ("Entgelt ab 2025", "180 EUR jährlich"), ("Haftungsgrenze", "5000 EUR je Schadenfall"), ("Reaktion Kundin", "keine dokumentierte Zustimmung")], sections=[("1. Mitteilung Oktober 2024", ["Die Bank kündigte im Onlinepostfach ein Jahresentgelt von 180 EUR ab 1. Januar 2025 an. Das Schreiben erklärte, die Zustimmung gelte als erteilt, wenn die Kundin nicht bis 15. Dezember widerspreche und das Fach weiter nutze. Helene Falkenberg meldete sich zwischen Oktober und Dezember nicht im Onlinebanking an.", "Das Entgelt wurde am 3. Januar 2025 vom Girokonto abgebucht. Die Kundin bemerkte die Erhöhung nach eigener Angabe erst in der Jahresübersicht im Februar."]), ("2. Bedingungen September 2025", ["Eine weitere Nachricht führte eine Haftungsgrenze von 5000 EUR für Schäden durch Wasser, Feuchtigkeit und technische Störungen ein. Für eine höhere Versicherung sollte der Kunde vor Einlagerung eine Wertmeldung abgeben und 0.4 Prozent des Mehrwerts jährlich zahlen.", "Die Betreffzeile lautete Aktuelle Informationen zu Ihrer Filiale. In der ersten Bildschirmansicht war die Haftungsgrenze nicht genannt. Das PDF wurde vom System am 2. September eingestellt; ein Öffnungsereignis ist nicht gespeichert."])], signer="Rhein-Main Privatbank AG", signer_role="Kundenkommunikation")
    record(d, "03_schadensbericht_wassereintritt.docx", org="Rhein-Main Privatbank AG", strapline="Facility Management und Filialsicherheit", contact=bank, title="Ereignisbericht Schließfachanlage B", metadata=[("Ereignis", "11.04.2026"), ("Feststellung", "06:12 Uhr"), ("Betroffene Fächer", "B-401 bis B-438"), ("Interne Nummer", "FM-MZ-260411")], sections=[("1. Ursache und Verlauf", ["Eine Pressverbindung der Kühlwasserleitung im Deckenbereich löste sich während der Nacht. Wasser trat über etwa 42 Minuten aus und lief an der Rückwand der Schließfachanlage herab. Der Feuchtesensor meldete um 05:51 Uhr; der Sicherheitsdienst betrat den Raum um 06:12 Uhr.", "Die Fächer B-409 bis B-422 wiesen sichtbare Feuchtigkeit auf. B-417 enthielt eine durchnässte Dokumentenmappe und zwei feuchte Schmuckschatullen. Die Kundin wurde am 11. April um 08:26 Uhr telefonisch erreicht und kam um 10:14 Uhr in die Filiale."]), ("2. Sicherung", ["Das Fach wurde gemeinsam geöffnet. Filialleiterin Derya Göbel, Sicherheitsmitarbeiter Karsten Huth und Helene Falkenberg waren anwesend. Gegenstände wurden auf saugfähigem Papier fotografiert und der Kundin in zwei Transportboxen übergeben.", "Der Installationsbetrieb hatte die Pressverbindung am 18. März bei Wartungsarbeiten gelöst und wieder eingesetzt. Das Wartungsprotokoll enthält keine zweite Sichtkontrolle. Die Bank meldete den Schaden ihrer Sachversicherung am selben Tag."])], signer="Derya Göbel", signer_role="Filialleiterin")
    record(d, "04_bankantwort_schadenersatz.docx", org="Rhein-Main Privatbank AG", strapline="Beschwerdemanagement", contact=bank, title="Antwort auf Ihre Schadensaufstellung", metadata=[("Kundin", "Helene Falkenberg"), ("Beschwerde", "RMP-26-1188"), ("Datum", "06.05.2026"), ("Angebot", "5000 EUR ohne Anerkennung")], sections=[("1. Nachweise", ["Die Kundin beziffert Schmuck und Wiederherstellungskosten mit 24680 EUR. Für den Goldreif liegt eine Rechnung aus 1998 über 6200 DM vor, für die Perlenkette eine aktuelle Schätzung von 4200 EUR. Zwei Inhaberschuldverschreibungen sind entwertet, aber noch lesbar.", "Die Bank erkennt den Wassereintritt und die betroffenen Gegenstände dem Grunde nach an. Für eine antike Brosche fehlt bislang ein Eigentums- oder Wertnachweis. Die Kosten der notariellen Ersatzurkunde über 680 EUR sind belegt."]), ("2. Vertragsstand", ["Die Bank verweist auf die im September 2025 bereitgestellten Bedingungen und bietet 5000 EUR an. Die Kundin habe keine erhöhte Wertdeckung beantragt. Für eine weitere Prüfung bittet die Bank um Originalrechnungen, Fotos vor Einlagerung und Angaben zu einer Hausratversicherung.", "Das Angebot soll bis 20. Mai angenommen werden. Eine Abtretung an die Sachversicherung ist nach dem beigefügten Formular vorgesehen."])], signer="Dr. Sven Hartwich", signer_role="Leiter Beschwerdemanagement")
    email(d, "05_email_onlinepostfach_nicht_gesehen.eml", sender="helene.falkenberg@t-online.de", recipients=["beschwerde@rheinmain-privatbank.de"], cc=["kanzlei@schott-mainz.de"], date="Tue, 14 Apr 2026 16:48:00 +0200", subject="Schließfach B-417 / Bedingungen und Schaden", message_id="<hf-b417-202604141648@t-online.de>", body="Sehr geehrte Damen und Herren,\n\nbitte senden Sie mir alle Vertragsbedingungen, auf die Sie sich beim Termin am Samstag bezogen haben. Ich habe weder einer Begrenzung auf 5000 EUR noch einer neuen Versicherung zugestimmt. Das Onlinebanking nutze ich nur selten; Kontoauszüge bekomme ich seit Jahren per Post, wenn ich sie nicht abrufe.\n\nIm Fach lagen die beigefügte Inventarliste, Familienschmuck und notarielle Urkunden. Die Liste hatte ich 2023 für meine Tochter angefertigt und in die blaue Mappe gelegt. Sie ist durch das Wasser teilweise unlesbar. Die Goldschmiedin Frau Pelzer kann den Reif und die Brosche aus Reparaturen bestätigen.\n\nBitte sichern Sie Zutrittsprotokolle, Fotos und Wartungsunterlagen und teilen Sie mir mit, wer die Leitung im März bearbeitet hat.\n\nMit freundlichen Grüßen\nHelene Falkenberg\nKaiserstraße 14, 55116 Mainz\nTelefon 06131 228 41 09")
    email(d, "06_email_goldschmiedin_wertangaben.eml", sender="ina.pelzer@goldschmiede-pelzer.de", recipients=["helene.falkenberg@t-online.de"], cc=["kanzlei@schott-mainz.de"], date="Fri, 17 Apr 2026 09:33:00 +0200", subject="Ihre Schmuckstücke / Reparaturkartei und Fotos", message_id="<pelzer-falkenberg-202604170933@goldschmiede-pelzer.de>", body="Liebe Frau Falkenberg,\n\nich habe unsere Kartei durchsucht. Den breiten Goldreif, 750er Gelbgold, 68 Gramm, habe ich im November 2022 auf Größe 58 geändert. Die Perlenkette mit 52 Akoya-Perlen erhielt im März 2023 einen neuen Verschluss. Von beiden Arbeiten existieren Fotos, die ich anhänge.\n\nDie Brosche mit Granatbesatz sehe ich auf einem Familienfoto, hatte sie aber nie zur Reparatur. Für Reif und Kette kann ich nach Besichtigung eine schriftliche Wiederbeschaffungsbewertung erstellen. Wasser allein schädigt das Gold nicht, kann aber Etuis, Fäden und Klebungen beeinträchtigen. Bitte bewahren Sie alles trocken und einzeln verpackt auf.\n\nHerzliche Grüße\nIna Pelzer\nGoldschmiedemeisterin\nGoldschmiede Pelzer\nAugustinerstraße 31, 55116 Mainz\nTelefon 06131 224 80 12")
    P.write_txt(d / "07_telefonvermerk_filialtermin.txt", """Telefon- und Besuchsvermerk Rhein-Main Privatbank AG
Vorgang: FM-MZ-260411 / Fach B-417
Datum: 11.04.2026

08:26 Uhr: Filialleiterin Derya Göbel erreicht Helene Falkenberg auf dem Mobiltelefon. Frau Falkenberg fragt dreimal, ob eingebrochen worden sei. Frau Göbel erklärt, es handele sich um Wasser und das Fach sei bislang verschlossen.

10:14 Uhr: Frau Falkenberg erscheint mit ihrer Tochter Miriam Falkenberg. Öffnung gemeinsam mit Sicherheitsmitarbeiter Karsten Huth. Aus dem Fach werden entnommen: blaue Dokumentenmappe, rotes Etui, grünes Etui, Umschlag Notar, kleine Blechdose, zwei Fotoalben. Kein Bargeld sichtbar.

10:31 Uhr: Frau Falkenberg sagt, in der roten Schatulle müsse ein Goldreif liegen. Der Reif befindet sich unter dem nassen Samteinsatz. Die Granatbrosche liegt in der Blechdose. Tochter Miriam fotografiert jeden Gegenstand auf dem Auslagetisch.

10:52 Uhr: Frau Göbel erwähnt eine Haftungsgrenze und fragt nach Wertmeldung. Frau Falkenberg sagt, sie kenne keine Grenze und habe nie einen Wert gemeldet. Eine Kopie der aktuellen Bedingungen kann am Samstag nicht ausgedruckt werden, weil das Vertragsarchiv gewartet wird.

11:08 Uhr: Zwei versiegelte Transportboxen werden an Frau Falkenberg übergeben. Empfangsliste von allen drei Anwesenden unterschrieben.
""")
    P.write_csv(d / "08_schliessfach_inhalt_werte.csv", ["Gegenstand", "Beleg", "Wert_alt", "Aktuelle_Angabe_EUR", "Zustand_11_04", "Eigentumshinweis", "Offen"], [["Goldreif 750", "Rechnung 1998 / Reparatur 2022", "6200 DM", "7200", "Etui nass", "Geschenk Mutter 1998", "Bewertung ausstehend"], ["Perlenkette", "Reparaturkartei 2023", "", "4200", "Faden feucht", "Erbstück Tante", "Besichtigung"], ["Granatbrosche", "Familienfoto 1987", "", "3800", "Dose feucht", "Familienbesitz", "kein Kaufbeleg"], ["Inhaberschuldverschreibungen", "Nummern lesbar", "5000 EUR", "5000", "Papier durchnässt", "Helene Falkenberg", "Ersatzverfahren"], ["Notarurkunden", "UR 881/2012 und 144/2018", "", "680", "Tinte verlaufen", "Urkundeninhaberin", "Ersatzkosten"], ["Fotoalben", "keine Rechnung", "", "3800", "stark feucht", "Familienbesitz", "Restaurierungsangebot"]])
