def build_bgb_smartphone_reparatur() -> None:
    meta = CaseMeta(
        slug="bgb-smartphone-reparatur-datenverlust-jena",
        title="BGB: Smartphone-Reparatur und verlorene Familienfotos in Jena",
        plugins=("bgb-bt-pruefer", "verbraucherschutzrecht-pruefer"),
        summary="Nach einem Displaybruch gibt Nadine Krüger ihr Smartphone bei PhoneDock Jena ab. Die Werkstatt tauscht nach einem Startfehler zusätzlich die Hauptplatine; lokale Fotos, Sprachnachrichten und Zugangsdaten sind danach weg, während Auftrag, Sicherungshinweis und telefonische Freigabe unterschiedlich dokumentiert sind.",
        closing="Auftrag, Kostengrenze, Diagnoselog, Anrufdaten, Datensicherungen und Schadenaufstellung ermöglichen die Prüfung von Werkleistung und Nebenpflichten. Wert und Kausalität des Datenverlusts bleiben offen.",
        checks=(("werkvertrag", "Paragrafen 631, 633 und 634 BGB auf Reparaturauftrag, Erfolg, Nachbesserung und Zusatzkosten anwenden."), ("nebenpflicht", "Hinweis-, Schutz- und Rücksichtnahmepflichten nach Paragraf 241 Absatz 2 und Paragraf 280 BGB anhand der konkreten Datenlage prüfen."), ("freigabe", "Reichweite der telefonischen Zustimmung und Kostengrenze aus Anrufprotokoll, Auftrag und E-Mail würdigen."), ("schaden", "Wiederherstellungskosten, immaterielles Interesse und ersparte Cloudkosten nach Paragrafen 249 und 253 BGB ohne pauschale Gleichsetzung behandeln.")),
    )
    d = P.prepare(meta.slug)
    shop = "Löbdergraben 18 · 07743 Jena\nTelefon 03641 559 18 20 · service@phonedock-jena.de\nInhaber Daniel Schenk"
    record(d, "01_reparaturauftrag_display.docx", org="PhoneDock Jena", strapline="Smartphone-Reparatur und Datenübertragung", contact=shop, title="Reparaturauftrag PD-260512-77", metadata=[("Kundin", "Nadine Krüger"), ("Gerät", "Orion P12 Pro, 256 GB"), ("Abgabe", "12.05.2026, 12:36 Uhr"), ("Kostenrahmen", "bis 260 EUR")], sections=[("1. Fehler und Auftrag", ["Das Display ist nach einem Sturz gesprungen, Bild und Berührung funktionieren noch. Die Kundin wünscht Displaytausch und Erhalt aller Daten. Im Feld Datensicherung steht handschriftlich Kundin sagt Fotos wichtig, Cloud wohl aus. Das Kästchen Datensicherung beauftragt ist nicht angekreuzt.", "Der Standardtext weist darauf hin, dass Reparaturen Datenverlust verursachen können und der Kunde vor Abgabe sichern soll. Die Kundin unterschrieb unterhalb des Textes auf einem Tablet. Eine gesonderte Abfrage, ob ein aktuelles Backup besteht, ist im Ausdruck nicht enthalten."]), ("2. Kosten und Kontakt", ["Displayeinheit 219 EUR, Diagnose 29 EUR, Gesamt zunächst 248 EUR. Zusatzarbeiten oberhalb 260 EUR bedürfen einer Freigabe. Als Kontakt ist die Mobilnummer 0176 551 09 184 hinterlegt.", "Das Gerät wurde entsperrt abgegeben; der PIN steht auf einem verdeckten Aufkleber. Der Mitarbeiter sicherte nach eigener Notiz Kontakte, aber keine Fotos, weil der interne Speicher nur noch 1.2 GB frei hatte."])], signer="Mika Lorenz", signer_role="Serviceannahme")
    record(d, "02_werkstattprotokoll_hauptplatine.docx", org="PhoneDock Jena", strapline="Technikarbeitsplatz 2", contact=shop, title="Diagnose- und Reparaturprotokoll", metadata=[("Auftrag", "PD-260512-77"), ("Techniker", "Daniel Schenk"), ("Bearbeitung", "13.05. bis 16.05.2026"), ("Ausgabe", "18.05.2026")], sections=[("1. Displaytausch", ["Am 13. Mai wurde die Displayeinheit ersetzt. Beim ersten Start erschien das Herstellerlogo, anschließend eine Neustartschleife. Das alte Display wurde testweise wieder angeschlossen; die Schleife blieb bestehen. Der Akku zeigte 41 Prozent.", "Das Diagnosetool meldete Fehler Storage controller timeout und Feuchtigkeitshistorie 0. Ein Software-Reset ohne Löschen schlug fehl. Am 14. Mai wurde ein Ersatz-Mainboard eingesetzt. Das Gerät startete danach mit leerem Benutzerspeicher."]), ("2. Freigabe und Altteil", ["Im System steht telefonische Freigabe Mainboard bis 389 EUR, 14.05., 16:07, Gespräch 54 Sekunden. Eine Tonaufzeichnung existiert nicht. Mitarbeiter Mika Lorenz erinnert sich, er habe gesagt, Daten können dann weg sein; die Kundin erinnert sich nur an Gerät startet sonst nicht.", "Das alte Mainboard wurde am 20. Mai an den Teilehändler zurückgesandt und mit 45 EUR gutgeschrieben. Eine spätere Datenrettung ist nur möglich, wenn das Teil zurückgekauft werden kann. Der Händler meldete am 2. Juni, die Charge sei bereits zerlegt."])], signer="Daniel Schenk", signer_role="Inhaber und Techniker")
    record(d, "03_maengelanzeige_datenverlust.docx", org="Nadine Krüger", strapline="Am Planetarium 4 · 07743 Jena", contact="Telefon 0176 551 09 184 · nadine.krueger@posteo.de", title="Beanstandung Reparatur PD-260512-77", metadata=[("Datum", "20.05.2026"), ("Rechnung", "PD-R-260518-77"), ("Bezahlt", "389 EUR unter Vorbehalt"), ("Frist", "03.06.2026")], sections=[("1. Datenbestand", ["Vor Abgabe waren auf dem Gerät Fotos und Videos seit September 2023 gespeichert, darunter Geburt und erstes Lebensjahr der Tochter Mina, Sprachnachrichten der verstorbenen Großmutter und Unterlagen zur Wohnungssuche. Die automatische Cloud-Sicherung war seit November 2025 wegen vollen Speichers ausgesetzt.", "Beim Abholen war das Gerät auf Werkseinstellungen. Mir wurde erst am Tresen gesagt, dass die Hauptplatine ersetzt wurde. Kontakte wurden aus einer Datei eingespielt, Fotos und Messenger-Verläufe fehlen."]), ("2. Verlangen", ["Bitte sichern Sie das alte Mainboard unverzüglich und ermöglichen Sie eine Datenrettung durch ein Fachlabor. Teilen Sie mit, wann und mit welchem Wortlaut ich einem Austausch zugestimmt haben soll. Eine Freigabe zur Vernichtung oder Rücksendung des Datenträgers habe ich nicht erteilt.", "Die Rechnung habe ich gezahlt, weil ich das Gerät für die Arbeit benötige. Den Mehrpreis und die Kosten einer Datenrettung behalte ich mir vor."])], signer="Nadine Krüger", signer_role="Kundin")
    record(d, "04_antwort_werkstatt_und_versicherung.docx", org="PhoneDock Jena", strapline="Beschwerdebearbeitung", contact=shop, title="Stellungnahme zum Auftrag PD-260512-77", metadata=[("Datum", "05.06.2026"), ("Kundin", "Nadine Krüger"), ("Haftpflicht", "Saale Gewerbe VVaG, Schaden SG-26-4418"), ("Kulanz", "100 EUR angeboten")], sections=[("1. Auftrag und Anruf", ["Die Werkstatt verweist auf den unterschriebenen Datensicherungshinweis und die telefonische Freigabe. Ohne Mainboardtausch sei das Gerät nicht nutzbar gewesen. Ein Zusammenhang zwischen Displaytausch und Startfehler könne technisch weder bestätigt noch ausgeschlossen werden.", "Der Altteilrücklauf sei branchenüblich und Voraussetzung für den reduzierten Teilepreis. Die Kundin habe bei Annahme kein Backup beauftragt. Der Mitarbeiter räumt ein, dass im Anrufprotokoll kein wörtlicher Hinweis zum Altteil festgehalten ist."]), ("2. Regulierung", ["Die Haftpflichtversicherung verlangt den vollständigen Reparaturauftrag, Diagnoseexport, Nachweis des Datenbestands und ein Angebot eines Datenrettungslabors. Die Werkstatt bietet ohne Anerkennung 100 EUR und Erstattung der Diagnosepauschale an.", "Eine Rückholung des Mainboards ist nach Auskunft des Lieferanten nicht mehr möglich. Die Werkstatt hat den Lieferanten um eine schriftliche Bestätigung der Zerlegung gebeten."])], signer="Daniel Schenk", signer_role="Inhaber")
    email(d, "05_email_cloudspeicher_status.eml", sender="no-reply@orioncloud.de", recipients=["nadine.krueger@posteo.de"], cc=[], date="Mon, 18 May 2026 17:44:00 +0200", subject="Ihre OrionCloud-Sicherungsübersicht", message_id="<orioncloud-884190-202605181744@orioncloud.de>", body="Guten Tag Frau Krüger,\n\nauf Ihre Anforderung wurde eine Sicherungsübersicht erstellt. Letzte vollständige Gerätesicherung des Orion P12 Pro: 18. November 2025, 03:12 Uhr. Letzte Fotosynchronisierung: 2. November 2025, 4182 Dateien. Seit 3. November wurde die Fotosynchronisierung wegen ausgeschöpften Speicherplatzes nicht fortgesetzt.\n\nKontakte wurden zuletzt am 11. Mai 2026 synchronisiert. Messenger-Inhalte und lokal gespeicherte Sprachnachrichten sind nicht Bestandteil Ihres Pakets. Die Sicherung vom 18. November kann vierzehn Tage lang über das Kundenkonto wiederhergestellt werden.\n\nOrionCloud Kundenservice\nOrion Mobile Services GmbH\nKarl-Marx-Allee 88, 10243 Berlin\nTelefon 030 880 41 0")
    email(d, "06_email_datenrettung_kostenvoranschlag.eml", sender="labor@datenhain-weimar.de", recipients=["nadine.krueger@posteo.de"], cc=["service@phonedock-jena.de"], date="Tue, 26 May 2026 11:21:00 +0200", subject="Anfrage Orion P12 Pro / Datenrettung nur mit Originalplatine", message_id="<dh-260526-orionp12@datenhain-weimar.de>", body="Sehr geehrte Frau Krüger,\n\nfür eine Datenrettung benötigen wir zwingend die ursprüngliche Hauptplatine mit verlötetem Speicher. Das neue Gerät oder ein Cloudkonto reicht nicht aus. Ist die Platine unbeschädigt und lässt sich der Speichercontroller stabilisieren, kostet die Diagnose 390 EUR und die erfolgreiche Auslesung je nach Aufwand 1200 bis 2400 EUR.\n\nWurde die Platine bereits zerlegt oder der Speicherchip mechanisch entfernt, steigen Aufwand und Risiko erheblich. Ohne das Originalteil können wir keine Daten rekonstruieren. Bitte lassen Sie die Werkstatt den Rücksendeweg und die Seriennummer schriftlich bestätigen.\n\nMit freundlichen Grüßen\nDr. Erik Wenzel\nDatenhain Labor Weimar GmbH\nBrennerstraße 8, 99423 Weimar\nTelefon 03643 830 91 22")
    P.write_txt(d / "07_telefonnotiz_freigabe_14_mai.txt", """Eigene Gesprächsnotiz Nadine Krüger
Datum: 14.05.2026
Anruf: 16:07 Uhr, Dauer laut Telefonliste 54 Sekunden
Rufnummer: 03641 559 18 20

Der Mitarbeiter sagte, das Telefon gehe nach dem Displaytausch nicht mehr über das Logo hinaus. Es müsse noch ein Teil getauscht werden und insgesamt koste es dann 389 Euro. Ich fragte, ob meine Bilder noch da seien. Er sagte sinngemäß, das könne er erst sehen, wenn das Telefon wieder startet. Ich sagte: Dann machen Sie es, ich brauche das Telefon Montag.

Ich erinnere keine Aussage, dass die Hauptplatine der Speicher ist, dass alle Daten sicher verschwinden oder dass das alte Teil sofort zurückgeschickt wird. Der Mitarbeiter wirkte eilig und sagte, er müsse die Bestellung noch vor 16:15 Uhr auslösen.

Beim Abholen am 18. Mai sagte ein anderer Mitarbeiter, das alte Board sei im Austausch. Er zeigte mir das neue leere Telefon und spielte Kontakte ein. Auf meine Frage nach Fotos sagte er, die müssten aus der Cloud kommen.

Notiz erstellt am 19.05.2026 um 21:35 Uhr nach Durchsicht der Telefonliste.
""")
    P.write_csv(d / "08_dateibestand_cloud_lokal.csv", ["Zeitraum", "Dateityp", "Lokal_geschaetzt", "Cloud_vorhanden", "Fehlend_geschaetzt", "Quelle", "Bemerkung"], [["09/2023-11/2025", "Fotos", "4182", "4182", "0", "Cloudübersicht", "vollständig bis 02.11.2025"], ["11/2025-05/2026", "Fotos", "1684", "0", "1684", "Galeriezähler Erinnerung", "Cloud voll"], ["09/2023-05/2026", "Videos", "214", "96", "118", "Cloudübersicht", "große Dateien teils lokal"], ["2024-2026", "Sprachnachrichten", "327", "0", "327", "Messengeranzeige vor Abgabe", "keine Cloud"], ["2023-2026", "Kontakte", "684", "684", "0", "OrionCloud", "wiederhergestellt"], ["2025-2026", "Dokumente", "92", "17", "75", "Downloadordner", "Wohnungssuche"]])
    P.write_csv(d / "09_reparaturzeiten_teile_kosten.csv", ["Zeitpunkt", "Arbeit", "Teil", "Betrag_EUR", "Freigabe", "Protokoll", "Folge"], [["2026-05-12 12:36", "Annahme", "", "0", "Auftrag bis 260", "PD-260512-77", "Gerät entsperrt"], ["2026-05-13 10:22", "Displaytausch", "Displayeinheit", "219", "schriftlich", "Techniklog", "Startschleife"], ["2026-05-13 11:08", "Diagnose", "", "29", "schriftlich", "Storage timeout", "Reset erfolglos"], ["2026-05-14 16:07", "Anruf", "Mainboard", "141", "telefonisch", "54 Sekunden", "Bestellung"], ["2026-05-16 13:42", "Mainboardtausch", "Austauschteil", "141", "Systemvermerk", "Gerät startet", "Speicher leer"], ["2026-05-20 15:10", "Altteilversand", "Originalboard", "-45", "keine gesonderte", "Retour 77418", "später zerlegt"]])
