    files = [("01_reparaturauftrag_display.docx", "Auftrag, Datensicherungshinweis und Kostengrenze"), ("02_werkstattprotokoll_hauptplatine.docx", "Technischer Ablauf und Altteilrücksendung"), ("03_maengelanzeige_datenverlust.docx", "Datenbestand und konkrete Beanstandung"), ("04_antwort_werkstatt_und_versicherung.docx", "Werkstattantwort und Versicherungsanforderungen"), ("05_email_cloudspeicher_status.eml", "Cloudübersicht mit letzter vollständiger Sicherung"), ("06_email_datenrettung_kostenvoranschlag.eml", "Fachlabor erläutert Voraussetzungen und Kosten"), ("07_telefonnotiz_freigabe_14_mai.txt", "Zeitnahe Erinnerung an den Freigabeanruf"), ("08_dateibestand_cloud_lokal.csv", "Abgleich lokaler und gesicherter Dateien"), ("09_reparaturzeiten_teile_kosten.csv", "Technik- und Kostenchronologie"), ("10_foto_auftrag_tablet_unterschrift.jpg", "Foto der Kundenkopie mit leeren Feldern")]
