def build_bgb_tierkauf() -> None:
    meta = CaseMeta(
        slug="bgb-tierkauf-welpe-herzfehler-oldenburg",
        title="BGB: Welpenkauf und angeborener Herzfehler in Oldenburg",
        plugins=("bgb-bt-pruefer", "verbraucherschutzrecht-pruefer"),
        summary="Familie Tekin kauft den Labradorwelpen Bruno von einer Züchterin, die sich als private Liebhaberzucht bezeichnet, aber regelmäßig Würfe bewirbt. Drei Wochen nach Übergabe diagnostiziert eine Tierklinik eine schwere Pulmonalstenose; Gesundheitszeugnis, Hörbefund und Verkaufsnachrichten passen nicht vollständig zusammen.",
        closing="Kaufvertrag, Voruntersuchung, Klinikbefund, Inserate, Kommunikation und Kosten lassen Verkäuferstatus, Beschaffenheit, zeitlichen Ursprung und Nacherfüllung offen prüfen. Die Akte enthält keine Vorgabe zu Rückgabe oder Behandlung.",
        checks=(("tierkauf", "Paragraf 90a BGB und kaufrechtliche Regeln der Paragrafen 433, 434 und 437 BGB auf das Tier und die vereinbarten Angaben anwenden."), ("verbrauchsgueterkauf", "Unternehmer- und Verbrauchereigenschaft aus Umfang, Auftreten, Würfen und Zahlungsabwicklung entwickeln; Paragrafen 474 ff. und 477 BGB nur bei erfüllten Voraussetzungen einsetzen."), ("mangel", "Angeborenen Befund, Untersuchungszeitpunkte, zugesagte Gesundheit und Kenntnis anhand tierärztlicher Primärquellen würdigen."), ("rechtsfolge", "Behandlung, Ersatzwelpe, Rückabwicklung und Aufwendungen mit Tierwohl und konkreter Kommunikation trennen.")),
    )
    d = P.prepare(meta.slug)
    breeder = "Zwinger von der Huntewiese · Rita Oltmann\nAmmerländer Heerstraße 288 · 26129 Oldenburg\nTelefon 0441 361 72 18 · kontakt@huntewiese-labradore.de"
    record(d, "01_kaufvertrag_labrador_bruno.docx", org="Zwinger von der Huntewiese", strapline="Labrador Retriever aus Familienaufzucht", contact=breeder, title="Kaufvertrag Rüde Bruno", metadata=[("Käufer", "Aylin und Cem Tekin"), ("Wurftag", "08.02.2026"), ("Übergabe", "18.04.2026"), ("Kaufpreis", "2400 EUR")], sections=[("1. Tier und Angaben", ["Übergeben wird der gelbe Labradorrüde Bruno, Chipnummer 276098108441927, aus dem B-Wurf nach Hündin Nala von der Huntewiese und Rüde Milford Green Cooper. Der Vertrag bezeichnet den Welpen als altersgerecht entwickelt, tierärztlich untersucht, geimpft und ohne bekannte Erkrankung.", "Beigefügt sind Impfpass, Ahnentafel-Antrag, Futterplan und Untersuchungsbogen vom 14. April. Im Vertrag steht Liebhaberzucht, Verkauf von privat. Eine Haftung für später auftretende erbliche Erkrankungen wird ausgeschlossen, soweit der Verkäuferin bei Übergabe kein Befund bekannt war."]), ("2. Übergabe", ["Bei Abholung spielte Bruno etwa zwanzig Minuten im Garten. Cem Tekin bemerkte, dass der Welpe nach dem Rennen stark hechelte. Rita Oltmann erklärte, der Wurf habe an diesem Morgen die zweite Impfung erhalten und sei deshalb müde.", "Gezahlt wurden 500 EUR Reservierung per Überweisung und 1900 EUR bei Übergabe per Echtzeitüberweisung. Eine Rückgabe innerhalb der ersten Woche sollte nach mündlicher Aussage möglich sein, falls die ältere Hündin der Familie den Welpen nicht akzeptiere."])], signer="Rita Oltmann", signer_role="Verkäuferin")
    record(d, "02_tieraerztlicher_untersuchungsbogen.docx", org="Tierarztpraxis Dr. Evers", strapline="Kleintiere · Vorsorge · Zuchtuntersuchung", contact="Bloherfelder Straße 181 · 26129 Oldenburg\nTelefon 0441 570 29 40 · praxis@tierarzt-evers.de", title="Wurfuntersuchung B-Wurf Huntewiese", metadata=[("Untersuchung", "14.04.2026"), ("Tier", "Bruno / Chip 276098108441927"), ("Alter", "9 Wochen"), ("Tierärztin", "Dr. Fenja Evers")], sections=[("1. Allgemeiner Befund", ["Gewicht 7.8 Kilogramm, Schleimhäute rosig, Lunge auskultatorisch frei, Nabel unauffällig, Hoden beidseits im Skrotum. Der Welpe war lebhaft und ließ sich ohne Abwehr untersuchen.", "Unter Herz ist auf dem Durchschlag zunächst o. B. angekreuzt. Daneben befindet sich ein schwer lesbarer Bleistiftvermerk Geräusch nach Aufregung? Kontrolle. In der digitalen Praxisakte steht Herzton leicht rau, Wiedervorstellung in vier Wochen empfohlen."]), ("2. Kommunikation", ["Die Rechnung wurde an Rita Oltmann gestellt. Eine schriftliche Überweisung zur Kardiologie erfolgte nicht. Dr. Evers erinnert sich, die Züchterin habe gesagt, bei einem Welpen sei nach dem Spielen kurz etwas zu hören gewesen und alle Käufer seien weit angereist.", "Der Käuferausdruck enthält den Bleistiftvermerk nicht, weil er vor dessen Ergänzung kopiert wurde. Wann genau der Vermerk gesetzt wurde, lässt sich aus dem Scanzeitpunkt 15:48 Uhr und dem Speichereintrag 16:03 Uhr nicht abschließend ableiten."])], signer="Dr. Fenja Evers", signer_role="Tierärztin")
    record(d, "03_kardiologischer_befund_tierklinik.docx", org="Tierklinik am Küstenkanal", strapline="Kardiologie und Bildgebung", contact="Cloppenburger Straße 418 · 26133 Oldenburg\nTelefon 0441 998 72 0 · kardiologie@tierklinik-kuestenkanal.de", title="Echokardiographischer Befund Bruno", metadata=[("Untersuchung", "09.05.2026"), ("Überweisung", "Tierarztpraxis Dr. Jansen"), ("Gewicht", "10.4 Kilogramm"), ("Befundnummer", "TKK-26-5519")], sections=[("1. Anlass und Messwerte", ["Seit Übernahme berichten die Halter über schnelle Erschöpfung, zweimaliges Taumeln nach Spiel und bläuliche Zunge am 7. Mai. Bei Auskultation findet sich ein systolisches Herzgeräusch Grad 4 von 6 mit Maximum links basal.", "Die Echokardiographie zeigt eine hochgradige valvuläre Pulmonalstenose. Gemessene Spitzengeschwindigkeit 5.6 Meter pro Sekunde, berechneter Druckgradient 125 mmHg. Der rechte Ventrikel ist konzentrisch hypertrophiert. Hinweise auf eine erworbene Ursache bestehen nicht."]), ("2. Empfehlung und Kosten", ["Empfohlen wird körperliche Schonung und zeitnahe Vorstellung zur Ballonvalvuloplastie. Die Klinik schätzt Intervention, Narkose und zwei stationäre Tage auf 4800 bis 6200 EUR. Ohne Behandlung besteht ein erhöhtes Risiko für Synkopen und Rechtsherzversagen.", "Die Halter wünschen zunächst Rücksprache mit Züchterin und Haustierarzt. Bis dahin soll Bruno nur kurze Leinenwege gehen. Ein Notfallblatt wurde ausgehändigt."])], signer="Dr. Leander Voß", signer_role="Diplomate Kardiologie")
    record(d, "04_antwort_zuechterin_behandlung.docx", org="Zwinger von der Huntewiese", strapline="Rita Oltmann", contact=breeder, title="Antwort zur Erkrankung von Bruno", metadata=[("Datum", "13.05.2026"), ("Bezug", "E-Mail Familie Tekin vom 10.05.2026"), ("Wurf", "B-Wurf 08.02.2026"), ("Vorschlag", "Rücknahme oder Kostenbeitrag 800 EUR")], sections=[("1. Kenntnisstand", ["Rita Oltmann erklärt, ihr sei bei Übergabe keine Herzerkrankung bekannt gewesen. Der Tierarztbogen habe keinen behandlungsbedürftigen Befund ausgewiesen. Die übrigen sieben Welpen des Wurfs seien nach Rückmeldung der Halter gesund.", "Sie habe seit 2021 vier Würfe mit insgesamt 31 Welpen gehabt. Die Hündinnen lebten im Haushalt. Die Einnahmen würden Futter, Untersuchungen, Deckgebühren und Vereinskosten decken; ein Gewerbe betreibe sie nicht."]), ("2. Vorschlag", ["Die Züchterin bietet an, Bruno zurückzunehmen und den Kaufpreis abzüglich 300 EUR für die bisherige Haltung zu erstatten. Alternativ will sie 800 EUR zu einer Behandlung beitragen. Einen Ersatzwelpen aus dem nächsten Wurf könne sie frühestens 2027 anbieten.", "Eine Übernahme der vollständigen Operationskosten lehnt sie ab. Sie bittet um Originalbefund, Ultraschallbilder und Freigabe, mit Dr. Evers sowie der Tierklinik zu sprechen."])], signer="Rita Oltmann", signer_role="Verkäuferin")
    email(d, "05_email_haustierarzt_ueberweisung.eml", sender="praxis@tierarzt-jansen-oldenburg.de", recipients=["aylin.tekin@posteo.de"], cc=["kardiologie@tierklinik-kuestenkanal.de"], date="Thu, 7 May 2026 18:26:00 +0200", subject="Bruno / Herzgeräusch und Termin Tierklinik", message_id="<jansen-bruno-202605071826@tierarzt-jansen-oldenburg.de>", body="Liebe Frau Tekin,\n\nbei der heutigen Untersuchung war das Herzgeräusch deutlich und nach kurzer Bewegung stärker hörbar. Wegen des von Ihnen beschriebenen Taumelns habe ich für Samstag, 9. Mai, 08:30 Uhr, einen Termin in der Kardiologie der Tierklinik reserviert. Bitte lassen Sie Bruno bis dahin nicht frei laufen und kommen Sie bei Atemnot sofort in den Notdienst.\n\nBringen Sie Kaufvertrag, Impfpass und den Untersuchungsbogen vom 14. April mit. Auf Ihrer Kopie ist Herz ohne Befund markiert. Ich habe Dr. Evers um Übersendung ihrer digitalen Akte gebeten, weil dort möglicherweise ein Kontrollhinweis gespeichert ist.\n\nHerzliche Grüße\nDr. Malte Jansen\nTierarztpraxis Jansen\nAlexanderstraße 201, 26121 Oldenburg\nTelefon 0441 882 10 44")
    email(d, "06_email_wurfkaeufer_rueckmeldungen.eml", sender="rita.oltmann@huntewiese-labradore.de", recipients=["aylin.tekin@posteo.de"], cc=[], date="Tue, 12 May 2026 21:04:00 +0200", subject="B-Wurf / Rückmeldungen der anderen Familien", message_id="<huntewiese-bwurf-202605122104@huntewiese-labradore.de>", body="Hallo Frau Tekin,\n\nich habe heute alle Familien angerufen. Bella und Balu waren diese Woche beim Tierarzt, dort sei am Herzen nichts aufgefallen. Benno hustet manchmal nach dem Trinken, hat aber laut Familie viel zu schnell getrunken. Von den anderen habe ich nur allgemeine Rückmeldungen.\n\nBitte schicken Sie mir den vollständigen Klinikbericht und nicht nur das Foto der ersten Seite. Ich möchte auch wissen, ob die Klinik sicher sagt, dass die Verengung schon bei Übergabe hörbar gewesen sein musste. Frau Dr. Evers hat mir damals gesagt, der Wurf könne ausziehen. An einen ernsthaften Kontrollhinweis erinnere ich mich nicht.\n\nWir sollten in Ruhe besprechen, ob Bruno bei Ihnen bleibt. Mir ist wichtig, dass er nicht zwischen mehreren Familien hin- und hergeht.\n\nViele Grüße\nRita Oltmann\nZwinger von der Huntewiese\nTelefon 0441 361 72 18")
    P.write_txt(d / "07_whatsapp_uebergabe_erste_symptome.txt", """WhatsApp-Export · Familie Tekin / Rita Oltmann · 18.04.2026 bis 08.05.2026

18.04. 16:12 Aylin Tekin: Bruno schläft seit der Fahrt. Er hat im Garten sehr stark gehechelt, ist das von der Impfung?
18.04. 16:20 Rita Oltmann: Ja, aufregender Tag und Impfung. Heute Ruhe, morgen wird er munter.
23.04. 19:44 Cem Tekin: Beim Spielen setzt er sich nach zwei Minuten hin. Die alte Hündin spielt viel länger.
23.04. 20:03 Rita Oltmann: Welpen haben kurze Phasen. Nicht überfordern, er wächst gerade.
02.05. 10:18 Aylin Tekin: Bruno ist kurz getaumelt, nachdem er dem Ball nachlief. Zahnfleisch sah blass aus.
02.05. 10:42 Rita Oltmann: Bitte beim Tierarzt zeigen, wenn das wieder kommt. Beim Check war alles gut.
07.05. 17:51 Aylin Tekin: Tierarzt hört lautes Herzgeräusch, Samstag Kardiologie. Ich schicke den Überweisungsschein.
08.05. 08:16 Rita Oltmann: Das überrascht mich sehr. Bitte erst Befund abwarten. Ich spreche heute mit Dr. Evers.
""")
    P.write_csv(d / "08_behandlungskosten_termine.csv", ["Datum", "Leistung", "Praxis", "Betrag_EUR", "Bezahlt", "Beleg", "Bemerkung"], [["2026-04-18", "Kaufpreis", "Rita Oltmann", "2400", "ja", "Kaufvertrag", "500 Reservierung"], ["2026-05-07", "Untersuchung und Überweisung", "Tierarzt Jansen", "84.60", "ja", "J-260507", "Herzgeräusch"], ["2026-05-09", "Echokardiographie", "Tierklinik Küstenkanal", "612.40", "ja", "TKK-5519", "Pulmonalstenose"], ["2026-05-12", "Medikament", "Apotheke", "48.20", "ja", "AP-1188", "bis Eingriff"], ["2026-05-20", "Voruntersuchung Intervention", "Tierklinik Küstenkanal", "390", "Termin", "KV-5519-A", "noch offen"], ["2026-06-03", "Ballonvalvuloplastie", "Tierklinik Küstenkanal", "5480", "Kostenvoranschlag", "KV-5519-B", "Spanne 4800 bis 6200"]])
    P.write_csv(d / "09_wuerfe_inserate_zahlungen.csv", ["Jahr", "Wurf", "Welpen", "Preis_je_EUR", "Inseratsportal", "Reservierungen", "Zahlungskonto", "Hinweis"], [["2021", "A1", "6", "1800", "Vereinsseite", "5", "Privatkonto", "eine Hündin behalten"], ["2022", "A2", "8", "1950", "Vereinsseite und HundeMarkt", "8", "Privatkonto", ""], ["2024", "A3", "9", "2200", "eigene Website", "9", "Privatkonto", "Warteliste"], ["2026", "B", "8", "2400", "eigene Website und HundeMarkt", "8", "Privatkonto", "Bruno betroffen"], ["2027", "C geplant", "", "", "Website angekündigt", "3", "", "unverbindliche Liste"]])
