    files = [("01_kaufvertrag_labrador_bruno.docx", "Kaufvertrag, Gesundheitsangaben und Übergabe"), ("02_tieraerztlicher_untersuchungsbogen.docx", "Voruntersuchung mit abweichenden Fassungen"), ("03_kardiologischer_befund_tierklinik.docx", "Diagnose, Messwerte und Behandlungsvorschlag"), ("04_antwort_zuechterin_behandlung.docx", "Kenntnisdarstellung und zwei Angebote"), ("05_email_haustierarzt_ueberweisung.eml", "Zeitnahe Überweisung zur Kardiologie"), ("06_email_wurfkaeufer_rueckmeldungen.eml", "Züchterin berichtet Rückfragen im Wurf"), ("07_whatsapp_uebergabe_erste_symptome.txt", "Nachrichten vom Übergabetag bis zur Überweisung"), ("08_behandlungskosten_termine.csv", "Behandlungen, Kosten und offene Termine"), ("09_wuerfe_inserate_zahlungen.csv", "Mehrjährige Wurf- und Verkaufsdaten"), ("10_foto_uebergabe_bruno.jpg", "Bildanlage vom Übergabetag")]
