def build_bgb_onlinekurs() -> None:
    meta = CaseMeta(
        slug="bgb-onlinekurs-kuendigungsbutton-koeln",
        title="BGB: Onlinekurs, Kündigungsschaltfläche und Vertragsverlängerung in Köln",
        plugins=("agb-recht-pruefer", "verbraucherschutzrecht-pruefer", "bgb-bt-pruefer"),
        summary="Studentin Melina Schürmann bucht einen zwölfmonatigen Spanischkurs mit Videobibliothek und monatlicher Sprechstunde. Nach Ablauf verlängert der Anbieter um weitere zwölf Monate; die Kündigungsschaltfläche führt bei ihr wiederholt zur Anmeldung zurück, während der Anbieter auf eine Kündigung per Chat verweist.",
        closing="Bestellseite, Bedingungen, technische Ereignisse, Lernnutzung und Zahlungsdaten trennen Vertragsinhalt, Zugang und Beendigung. Die Akte lässt offen, zu welchem Zeitpunkt und auf welchem Weg das Vertragsverhältnis endete.",
        checks=(("button", "Paragraf 312k BGB auf dauerhafte Erreichbarkeit, Beschriftung, Bestätigungsseite, Zugang und Rechtsfolge anwenden."), ("laufzeit", "Paragraf 309 Nummer 9 BGB anhand von Erstlaufzeit, Verlängerung und Kündigungsfrist prüfen."), ("einbeziehung", "Bestellablauf und Fassungen der AGB nach Paragrafen 305 Absatz 2, 305c und 307 BGB würdigen."), ("nutzung", "Nutzung nach Kündigungsversuchen nicht vorschnell als Bestätigung behandeln; technische und kommunikative Vorgänge trennen.")),
    )
    d = P.prepare(meta.slug)
    provider = "Lernbrücke Sprachen GmbH\nSalierring 46 · 50677 Köln\nTelefon 0221 650 81 20 · service@lernbruecke-sprachen.de\nHRB 112844 AG Köln"
    record(d, "01_bestellbestaetigung_spanischkurs.docx", org="Lernbrücke Sprachen GmbH", strapline="Online-Sprachkurse und Live-Sprechstunden", contact=provider, title="Bestellbestätigung Español B2", metadata=[("Kundin", "Melina Schürmann"), ("Bestellung", "12.01.2025, 19:42 Uhr"), ("Preis", "29.90 EUR monatlich"), ("Mindestlaufzeit", "12 Monate")], sections=[("1. Paket", ["Das Paket umfasst Videolektionen, Übungsblätter, Lernfortschritt und eine Gruppensprechstunde pro Monat. Die Zahlung erfolgt monatlich per Lastschrift. Der Zugang wurde unmittelbar nach Betätigung der Schaltfläche zahlungspflichtig bestellen freigeschaltet.", "Auf der Bestellseite stand: Nach der Mindestlaufzeit flexibel weiterlernen. In der Bestätigung wird ergänzt, der Vertrag verlängere sich gemäß Ziffer 8 der Bedingungen, wenn er nicht sechs Wochen vor Laufzeitende gekündigt werde."]), ("2. Unterlagen", ["Die Bestätigung enthält einen Link auf AGB-Fassung 2024-11 und eine Widerrufsinformation. Ein PDF der Bedingungen ist nicht angehängt. Im Kundenkonto erscheint später Fassung 2025-09 mit einer zwölfmonatigen Verlängerung.", "Melina Schürmann widerrief nicht. Sie nutzte den Kurs regelmäßig bis Oktober 2025 und danach nur noch am 4. Januar und 2. Februar 2026."])], signer="Lernbrücke Sprachen GmbH", signer_role="Automatische Bestellbestätigung")
    record(d, "02_agb_fassungen_laufzeit.docx", org="Lernbrücke Sprachen GmbH", strapline="Vertragsbedingungen Español B2", contact=provider, title="AGB-Auszüge mit Versionshistorie", metadata=[("Fassung Vertragsschluss", "2024-11"), ("Fassung Kundenkonto", "2025-09"), ("Archivexport", "18.03.2026"), ("Ziffer", "8 Laufzeit und Kündigung")], sections=[("1. Fassung 2024-11", ["Der Vertrag läuft zwölf Monate. Danach verlängert er sich auf unbestimmte Zeit und kann mit einer Frist von einem Monat gekündigt werden. Kündigungen sind über die Kündigungsschaltfläche oder in Textform möglich.", "Der Anbieter darf Bedingungen aus rechtlichen oder technischen Gründen ändern. Änderungen werden mindestens sechs Wochen vorher mitgeteilt. Schweigen gilt nur dann als Zustimmung, wenn die Änderung keine Hauptleistung oder Vergütung betrifft."]), ("2. Fassung 2025-09", ["Die im Konto angezeigte Fassung nennt eine automatische Verlängerung um weitere zwölf Monate, sofern nicht sechs Wochen vor Ablauf gekündigt wird. Unter derselben Ziffer steht, gesetzlich zwingende kürzere Fristen blieben unberührt.", "Das Archiv zeigt Veröffentlichung am 4. September 2025. Ob und wann die Kundin eine Mitteilung erhielt, ist im Kommunikationsprotokoll nicht vermerkt. Eine Newslettermail vom 5. September trägt nur den Betreff Neue Lernfunktionen im Herbst."])], signer="Lernbrücke Sprachen GmbH", signer_role="Vertragsarchiv")
    record(d, "03_kuendigungsversuche_browserprotokoll.docx", org="Melina Schürmann", strapline="Kundenkonto LS-884120", contact="Eifelstraße 72 · 50677 Köln\nmelina.schuermann@posteo.de · Telefon 0176 411 88 240", title="Protokoll der Kündigungsversuche", metadata=[("Erster Versuch", "28.12.2025, 21:18 Uhr"), ("Zweiter Versuch", "10.01.2026, 10:02 Uhr"), ("Geräte", "Notebook und Mobiltelefon"), ("Browser", "Firefox 146 / Safari iOS")], sections=[("1. Ablauf", ["Der Link Verträge hier kündigen im Seitenfuß öffnete zunächst eine Anmeldeseite. Nach Anmeldung erschien erneut die Kursübersicht. Beim zweiten Klick wurde für weniger als eine Sekunde eine Seite /contract/cancel angezeigt, dann erfolgte eine Rückleitung auf /dashboard.", "Am 10. Januar trat derselbe Ablauf auf dem Mobiltelefon auf. Ein Bildschirmvideo zeigt Uhrzeit, Adresszeile und Rückleitung. Eine Bestätigungsseite oder speicherbare Kündigungsbestätigung erschien nicht."]), ("2. Kontakt", ["Am 10. Januar um 10:18 Uhr schrieb die Kundin im Supportchat Kündigung zum nächstmöglichen Termin. Der Bot antwortete, Vertragsfragen würden innerhalb von zwei Werktagen bearbeitet. Am 14. Januar teilte ein Mitarbeiter mit, die Verlängerung sei bereits am 12. Januar eingetreten.", "Die Kundin nutzte am 2. Februar versehentlich einen Link zu einer neuen Lektion aus einer Erinnerungsmail. Sie beendete das Video nach 46 Sekunden und schrieb unmittelbar an den Support."])], signer="Melina Schürmann", signer_role="Kundin")
    record(d, "04_inkasso_und_anbieterantwort.docx", org="Lernbrücke Sprachen GmbH", strapline="Forderungsservice", contact=provider, title="Antwort auf Kündigung und Zahlungsrückgabe", metadata=[("Konto", "LS-884120"), ("Datum", "04.04.2026"), ("Offen", "107.70 EUR"), ("Vertragsende laut Anbieter", "11.01.2027")], sections=[("1. Anbieterposition", ["Der Anbieter behandelt den Vertrag als um zwölf Monate verlängert. Der Kündigungsbutton sei am 28. Dezember allgemein verfügbar gewesen; Serverfehler seien für das Kundenkonto nicht dokumentiert. Der Chat vom 10. Januar sei nach Ablauf der sechswöchigen Frist eingegangen.", "Die Nutzung am 4. Januar und 2. Februar werde als Fortsetzung des Kurses gewertet. Die Lastschriften Februar bis April wurden zurückgegeben."]), ("2. Forderung", ["Verlangt werden drei Monatsbeiträge zu je 29.90 EUR, Rücklastschriftkosten zu je 4.50 EUR und 4.50 EUR Mahnkosten. Der Zugang ist seit 15. März gesperrt.", "Der Anbieter bietet an, den Vertrag aus Kulanz zum 30. Juni 2026 zu beenden, wenn die offenen Beiträge bis 18. April gezahlt werden. Die Kundin hat dieses Angebot nicht angenommen."])], signer="Tobias Klewe", signer_role="Team Forderungsservice")
    email(d, "05_email_support_kuendigung.eml", sender="melina.schuermann@posteo.de", recipients=["service@lernbruecke-sprachen.de"], cc=[], date="Sat, 10 Jan 2026 10:26:00 +0100", subject="Kündigung Español B2 / Schaltfläche funktioniert nicht", message_id="<ms-ls-884120-202601101026@posteo.de>", body="Sehr geehrte Damen und Herren,\n\nich kündige meinen Kurs Español B2 zum nächstmöglichen Zeitpunkt. Die Schaltfläche auf Ihrer Website funktioniert bei mir weder am Notebook noch am Mobiltelefon. Nach der Anmeldung werde ich immer wieder zur Kursübersicht zurückgeleitet und erhalte keine Bestätigung.\n\nBereits am 28. Dezember habe ich es mehrfach versucht. Das Bildschirmvideo von heute und zwei Bildschirmfotos sind beigefügt. Bitte bestätigen Sie Zugang und Beendigungsdatum in Textform. Einer Verlängerung um weitere zwölf Monate widerspreche ich.\n\nMit freundlichen Grüßen\nMelina Schürmann\nKundennummer LS-884120\nEifelstraße 72, 50677 Köln")
    email(d, "06_email_technik_sessionfehler.eml", sender="technik@lernbruecke-sprachen.de", recipients=["serviceleitung@lernbruecke-sprachen.de"], cc=["tobias.klewe@lernbruecke-sprachen.de"], date="Mon, 12 Jan 2026 08:41:00 +0100", subject="Kündigungsroute / Session-Redirect 28.12. bis 10.01.", message_id="<technik-cancel-route-202601120841@lernbruecke-sprachen.de>", body="Guten Morgen,\n\nzwischen 27. Dezember und heute gab es bei Konten mit älterem Login-Token vereinzelt eine Rückleitung von /contract/cancel auf /dashboard. Das Monitoring zählt 184 Redirects, aber nicht, ob Nutzer anschließend neu gestartet haben. Die Bestätigungsroute selbst war erreichbar.\n\nFür Konto LS-884120 sehe ich am 28. Dezember drei Aufrufe der Kündigungsroute und jeweils sofort einen 302-Redirect. Am 10. Januar gibt es zwei weitere. Eine Kündigungsbestätigung wurde für dieses Konto nicht erzeugt. Bitte bei der Antwort berücksichtigen und die Rohlogs sichern; die Standardaufbewahrung endet nach neunzig Tagen.\n\nViele Grüße\nLeonie Frings\nPlatform Operations\nLernbrücke Sprachen GmbH\nTelefon 0221 650 81 248")
