def build_bgb_vollmacht_location() -> None:
    meta = CaseMeta(
        slug="bgb-vollmacht-hochzeitslocation-dresden",
        title="BGB: Hochzeitslocation, Schwesterbestellung und abgesagte Feier in Dresden",
        plugins=("bgb-at-pruefer", "vertragsrecht", "bgb-bt-pruefer"),
        summary="Während das Brautpaar im Ausland ist, verhandelt die Schwester mit dem Gut Wachwitz und unterzeichnet eine Reservierung über 12800 EUR. Nach der Trennung des Paares verlangt die Location eine Stornopauschale; E-Mails, Vollmachtsnachricht und spätere Änderungswünsche lassen offen, wer welchen Vertrag bestätigte.",
        closing="Angebot, Unterschrift, Nachrichten, Zahlungen und Veranstaltungsplanung bilden Duldung, Vertretungsmacht, Genehmigung und AGB-Fragen ab. Das Vertrags- und Haftungsergebnis ist nicht vorgegeben.",
        checks=(("vertretung", "Paragrafen 164, 167, 177 und 179 BGB auf Auftreten, Vollmachtsinhalt und spätere Erklärungen anwenden."), ("rechtsschein", "Äußeres Auftreten und Kommunikation auf Duldungs- oder Anscheinsvollmacht prüfen, ohne familiäre Nähe genügen zu lassen."), ("genehmigung", "Anzahlung, Änderungswünsche und E-Mail des Brautpaars auf mögliche Genehmigung nach Paragraf 184 BGB würdigen."), ("agb", "Stornopauschale, ersparte Aufwendungen und Nachweismöglichkeit nach Paragrafen 305c, 307 und 309 BGB prüfen.")),
    )
    d = P.prepare(meta.slug)
    venue = "Pillnitzer Landstraße 188 · 01326 Dresden\nTelefon 0351 261 88 40 · feiern@gut-wachwitz.de\nGut Wachwitz Veranstaltungen GmbH · HRB 44108 AG Dresden"
    record(d, "01_angebot_hochzeit_21_august.docx", org="Gut Wachwitz Veranstaltungen GmbH", strapline="Orangerie und Elbterrasse", contact=venue, title="Veranstaltungsangebot GW-2608-21", metadata=[("Brautpaar", "Nora Seifert und Elias Born"), ("Termin", "21.08.2026"), ("Gäste", "82 Erwachsene / 11 Kinder"), ("Gesamt", "12800 EUR")], sections=[("1. Leistungen", ["Enthalten sind Orangerie von 14:00 bis 02:00 Uhr, freie Trauung auf der Elbterrasse, Mobiliar, Menü, Getränkepauschale sechs Stunden, Servicepersonal und Endreinigung. Nicht enthalten sind Floristik, Musiktechnik und Übernachtungen.", "Das Angebot ist bis 18. November 2025 bindend. Zur Festbuchung verlangt die Location unterschriebene Reservierung und 3200 EUR Anzahlung. Das Paar befindet sich bis Ende November beruflich in Kanada."]), ("2. Stornoregel", ["Die beigefügten Bedingungen nennen bei Eingang der Absage mehr als 120 Kalendertage vor dem Termin 40 Prozent, bei 120 bis 31 Kalendertagen 70 Prozent und ab 30 Kalendertagen 90 Prozent des vereinbarten Entgelts. Der Kunde darf geringere ersparte Aufwendungen oder anderweitige Vermietung nachweisen.", "Eventmanagerin Paula Neubert führt Gespräche mit der Schwester des Bräutigams, Miriam Born. In der Kundenakte steht Familie entscheidet gemeinsam, Miriam koordiniert vor Ort."])], signer="Paula Neubert", signer_role="Eventmanagement")
    record(d, "02_reservierung_unterschrift_miriam.docx", org="Gut Wachwitz Veranstaltungen GmbH", strapline="Reservierungsbestätigung", contact=venue, title="Festbuchung GW-2608-21", metadata=[("Unterzeichnung", "17.11.2025"), ("Unterzeichnerin", "Miriam Born"), ("Zusatz", "i. A. Nora Seifert und Elias Born"), ("Anzahlung", "3200 EUR fällig 24.11.2025")], sections=[("1. Erklärung", ["Miriam Born unterzeichnet die Reservierung mit dem Zusatz i. A. und trägt die Anschrift des Brautpaars ein. Eine Vollmachtsurkunde ist nicht beigefügt. Sie legt der Location auf dem Mobiltelefon eine Nachricht ihres Bruders vor: Such uns etwas aus und mach den Termin fest, Budget höchstens 12000 plus Getränke.", "Paula Neubert weist darauf hin, das Angebot liege mit 12800 EUR über dem genannten Betrag. Miriam Born erklärt, Nora habe am Vortag telefonisch zusätzliche Kinderbetreuung gewünscht und das höhere Budget sei geklärt."]), ("2. Nachlauf", ["Die Anzahlung von 3200 EUR geht am 21. November vom gemeinsamen Konto Nora Seifert/Elias Born ein, Verwendungszweck Hochzeit Wachwitz 21.8. Elias. Am 28. November schreibt Nora Seifert an die Location und fragt nach vegetarischem Menü und früherem Aufbau.", "Eine gegengezeichnete Ausfertigung wird am 18. November an Miriam Born und in Kopie an die gemeinsame E-Mail-Adresse des Paares geschickt. Ein Zustellfehler ist nicht vermerkt."])], signer="Miriam Born", signer_role="i. A. Nora Seifert und Elias Born")
    record(d, "03_absage_und_stornorechnung.docx", org="Gut Wachwitz Veranstaltungen GmbH", strapline="Vertragsservice", contact=venue, title="Stornobestätigung und Rechnung", metadata=[("Absage", "09.03.2026"), ("Veranstaltung", "21.08.2026"), ("Stornopauschale", "5120 EUR"), ("Abzüglich Anzahlung", "1920 EUR offen")], sections=[("1. Absage", ["Nora Seifert teilte telefonisch mit, die Hochzeit werde nicht stattfinden. Elias Born schrieb am selben Tag, er habe nie einen Vertrag abgeschlossen und widerspreche einer Belastung. Die Location bestätigte die Absage, ohne zu klären, wessen Erklärung maßgeblich sei.", "Der Termin lag 165 Tage später. Die Location setzte 40 Prozent des Gesamtpreises an und verrechnete die Anzahlung. Eine konkrete Aufstellung ersparter Speisen, Getränke und Personalstunden ist nicht beigefügt."]), ("2. Weitervergabe", ["Am 22. April reservierte ein Unternehmen die Orangerie für denselben Abend von 18:00 bis 01:00 Uhr zu 7600 EUR, ohne Terrasse und Trauung. Die Location erklärte, Aufbau und Nachmittag könnten wegen der früheren Hochzeitsplanung nicht zusätzlich vergeben werden.", "Miriam Born verlangt die Anzahlung zurück. Sie erklärt, nur Botengänge erledigt und nie persönlich zahlen zu wollen."])], signer="Paula Neubert", signer_role="Eventmanagement")
    record(d, "04_forderung_gegen_schwester.docx", org="Kanzlei Elbbogen", strapline="Rechtsanwälte für Vertrags- und Veranstaltungsrecht", contact="Königstraße 31 · 01097 Dresden\nTelefon 0351 804 28 60 · kanzlei@elbbogen-recht.de\nAktenzeichen EB-884/26", title="Zahlungsaufforderung an Miriam Born", metadata=[("Datum", "18.05.2026"), ("Forderung", "1920 EUR"), ("Mandantin", "Gut Wachwitz Veranstaltungen GmbH"), ("Frist", "29.05.2026")], sections=[("1. Begründung der Mandantin", ["Unsere Mandantin geht vorrangig von einem Vertrag mit Nora Seifert und Elias Born aus. Sie beruft sich auf Ihre vorgezeigte Nachricht, die Überweisung vom Gemeinschaftskonto und die spätere Menüanfrage. Beide haben eine Zahlung bislang abgelehnt.", "Hilfsweise nimmt unsere Mandantin Sie wegen Abschlusses ohne ausreichende Vertretungsmacht in Anspruch. Sie haben mit dem Zusatz i. A. unterschrieben und bestätigt, das Budget sei abgestimmt."]), ("2. Offene Punkte", ["Bitte übersenden Sie bis zum Fristablauf den vollständigen Nachrichtenverlauf und teilen Sie mit, wer am 16. November an dem Telefonat teilnahm. Die Mandantin hält an der Restforderung fest.", "Eine doppelte Befriedigung wird nicht verlangt. Zahlungen des Brautpaars würden angerechnet."])], signer="Rechtsanwalt Dr. Jonas Wieland", signer_role="Kanzlei Elbbogen")
    email(d, "05_email_braut_menueaenderung.eml", sender="nora.seifert@posteo.de", recipients=["paula.neubert@gut-wachwitz.de"], cc=["elias.born@posteo.de", "miriam.born@web.de"], date="Fri, 28 Nov 2025 16:08:00 +0100", subject="GW-2608-21 / Menü, Kinder und Aufbau am 21. August", message_id="<ns-gw-2608-21-202511281608@posteo.de>", body="Liebe Frau Neubert,\n\nvielen Dank, dass Miriam den Termin festhalten konnte. Wir sind Sonntag zurück und würden nächste Woche gern per Video die Details durchgehen. Bitte planen Sie zwölf vegetarische Hauptgerichte statt der bislang notierten acht und eine Betreuungsecke für die Kinder ein.\n\nKönnen Floristin und Band am Freitagvormittag ab 10 Uhr aufbauen? Im Angebot steht Zugang ab 12 Uhr. Falls früherer Aufbau extra kostet, schicken Sie uns bitte den Preis. Elias kümmert sich um die nächste Rate, sobald wir die endgültige Getränkepauschale haben.\n\nHerzliche Grüße\nNora Seifert\nKamenzer Straße 44, 01099 Dresden\nTelefon 0176 504 18 882")
    email(d, "06_email_braeutigam_keine_vollmacht.eml", sender="elias.born@posteo.de", recipients=["paula.neubert@gut-wachwitz.de"], cc=["nora.seifert@posteo.de", "miriam.born@web.de"], date="Mon, 9 Mar 2026 18:42:00 +0100", subject="GW-2608-21 / kein Vertrag durch mich", message_id="<eb-gw-2608-21-202603091842@posteo.de>", body="Sehr geehrte Frau Neubert,\n\nich bestätige, dass die Feier abgesagt ist. Einen Vertrag habe ich nicht unterschrieben. Meine Nachricht an Miriam lautete, sie solle einen Termin festmachen, aber nur bis 12000 EUR plus Getränke. Das Angebot über 12800 EUR und die Stornobedingungen hatte ich damals nicht gelesen.\n\nDie Anzahlung ging vom gemeinsamen Konto, wurde aber von Nora im Onlinebanking ausgelöst. Ich habe mich später an Menügesprächen beteiligt, weil ich davon ausging, dass wir bei Bedarf ohne hohe Kosten absagen können. Bitte senden Sie mir den vollständigen Vertrag und den Nachweis, wann er an meine Adresse ging.\n\nMit freundlichen Grüßen\nElias Born\nKamenzer Straße 44, 01099 Dresden")
    P.write_txt(d / "07_whatsapp_geschwister_vollmacht.txt", """WhatsApp-Export · Elias Born / Miriam Born · 15.11.2025 bis 18.11.2025

15.11. 22:14 Elias: Wachwitz sieht gut aus. Such uns etwas aus und mach den Termin fest. Budget höchstens 12000 plus Getränke.
16.11. 08:05 Miriam: Angebot ist 12800 komplett mit Getränken für sechs Stunden. Nora will Kinderbetreuung, dann eher mehr.
16.11. 17:48 Elias: Bin im Termin. Ruf Nora an, wenn sie das okay findet, reservier es. Hauptsache 21. August bleibt frei.
17.11. 10:22 Miriam: Paula braucht Unterschrift heute. Ich schreibe i. A. darunter. Ist das in Ordnung?
17.11. 10:37 Elias: Ja, mach. Wir überweisen Anzahlung vom gemeinsamen Konto.
17.11. 14:51 Miriam: Unterschrieben. In den Bedingungen stehen 40 Prozent Storno bis 180 Tage. Bitte lest das heute Abend.
17.11. 22:09 Elias: Habe gerade nur erste Seite gesehen. Nora sagt, Termin passt. Rest nach Rückflug.
18.11. 09:12 Miriam: Vertrag kam per Mail an uns alle. Speichert ihn bitte.
""")
    P.write_csv(d / "08_zahlungen_kosten_weitervergabe.csv", ["Datum", "Vorgang", "Betrag_EUR", "Zahler_Empfaenger", "Status", "Beleg", "Hinweis"], [["2025-11-21", "Anzahlung", "3200", "Konto Seifert/Born an Gut Wachwitz", "gezahlt", "BK-1121", "Verwendungszweck Elias"], ["2026-03-09", "Stornopauschale 40 Prozent", "5120", "Gut Wachwitz", "berechnet", "ST-2608-21", "165 Tage vor Termin"], ["2026-03-09", "Verrechnung Anzahlung", "-3200", "Gut Wachwitz", "verrechnet", "ST-2608-21", ""], ["2026-04-22", "Firmenfeier Abend", "7600", "Sächsische Medientechnik GmbH", "reserviert", "GW-2608-21B", "18 bis 01 Uhr"], ["2026-05-18", "Restforderung", "1920", "Miriam Born", "offen", "EB-884/26", "hilfsweise"]])
    P.write_csv(d / "09_kommunikation_vertrag.csv", ["Datum", "Person", "Handlung", "Empfaenger", "Dokument", "Betrag_genannt", "Bemerkung"], [["2025-11-15", "Elias", "Nachricht", "Miriam", "WhatsApp", "12000 plus Getränke", "Termin festmachen"], ["2025-11-17", "Miriam", "Unterschrift i. A.", "Location", "Reservierung", "12800", ""], ["2025-11-18", "Location", "Vertragskopie", "alle drei", "E-Mail", "12800", "kein Fehler"], ["2025-11-21", "Nora", "Anzahlung", "Location", "Bank", "3200", "Gemeinschaftskonto"], ["2025-11-28", "Nora", "Menüänderung", "Location", "E-Mail", "Mehrpreis offen", "Dank für Festhalten"], ["2026-03-09", "Nora", "Absage", "Location", "Telefon", "", "Trennung"], ["2026-03-09", "Elias", "Widerspruch", "Location", "E-Mail", "", "keine Unterschrift"]])
    P.write_device_photo(d / "10_foto_unterschriftsseite_location.jpg", "Reservierung GW-2608-21", ["Unterschrift: Miriam Born", "Zusatz: i. A. Nora Seifert / Elias Born", "Stornotabelle auf Rückseite", "Aufnahme Paula Neubert · 17.11.2025", "Original im Veranstaltungsordner"], (108, 78, 67))
    files = [("01_angebot_hochzeit_21_august.docx", "Angebot, Leistungen und Stornoregel"), ("02_reservierung_unterschrift_miriam.docx", "Unterschrift der Schwester und Anzahlung"), ("03_absage_und_stornorechnung.docx", "Absage, Pauschale und spätere Weitervergabe"), ("04_forderung_gegen_schwester.docx", "Vorrangige und hilfsweise Anspruchsrichtung"), ("05_email_braut_menueaenderung.eml", "Spätere Detailänderung durch die Braut"), ("06_email_braeutigam_keine_vollmacht.eml", "Bräutigam bestreitet Vertragsbindung"), ("07_whatsapp_geschwister_vollmacht.txt", "Vollmachtsnachrichten im Originalzusammenhang"), ("08_zahlungen_kosten_weitervergabe.csv", "Anzahlung, Pauschale und Weitervermietung"), ("09_kommunikation_vertrag.csv", "Chronologie möglicher Bestätigungen"), ("10_foto_unterschriftsseite_location.jpg", "Bildanlage der Unterschriftsseite")]
