def build_bgb_leihe_ebike() -> None:
    meta = CaseMeta(
        slug="bgb-leihe-e-bike-akkubrand-freiburg",
        title="BGB: Geliehenes E-Bike, Ladegerät und Kellerbrand in Freiburg",
        plugins=("bgb-bt-pruefer", "versicherungsrecht"),
        summary="Nachbarin Ruth Ganter leiht Jonas Maier ihr E-Bike für ein Wochenende. Er lädt den Akku im gemeinschaftlichen Keller mit einem älteren Ersatzladegerät; nachts entsteht ein Brand. Frühere Warnanzeige, Ladeanweisung, Stromleiste und Eigentumsschäden werden von Feuerwehr, Gutachter und Versicherern unterschiedlich eingeordnet.",
        closing="Leihabrede, Übergabezustand, technische Spuren, Versicherungsunterlagen und Nachbarschaftskommunikation erlauben eine quellennahe Haftungsprüfung. Brandursache, Sorgfaltsmaßstab und Schadensteilung bleiben offen.",
        checks=(("leihe", "Paragrafen 598 bis 606 BGB auf Übergabe, Gebrauch, Rückgabe, Mangelkenntnis und Haftungsmaßstab anwenden."), ("delikt", "Paragrafen 823 und 254 BGB sowie Verkehrssicherung und Mitverursachung anhand technischer Tatsachen prüfen."), ("beweis", "Feuerwehrfeststellungen, Gutachten, Akkulog, Ladegerät und Steckdosenleiste nach Beweiswert und Lücken trennen."), ("versicherung", "Regress, Neuwert, Zeitwert und Selbstbehalte der beteiligten Versicherungen betragsgenau zuordnen.")),
    )
    d = P.prepare(meta.slug)
    record(d, "01_uebergabe_e_bike_ladegeraet.docx", org="Ruth Ganter", strapline="Schwarzwaldstraße 221 · 79117 Freiburg", contact="Telefon 0761 482 11 06 · ruth.ganter@posteo.de", title="Übergabenotiz E-Bike Veloria Tour 8", metadata=[("Entleiher", "Jonas Maier, Wohnung 2. OG"), ("Übergabe", "12.06.2026, 17:40 Uhr"), ("Rückgabe geplant", "15.06.2026, 08:00 Uhr"), ("Fahrradwert 2023", "3790 EUR")], sections=[("1. Überlassung", ["Jonas Maier erhält Fahrrad, Rahmenschloss, Akkuschlüssel und ein schwarzes Ersatzladegerät ChargePro 42V. Das Originalgerät liegt nach Angabe von Ruth Ganter bei ihrer Tochter in Basel. Die Leihe ist unentgeltlich und dient einer Wochenendtour im Kaiserstuhl.", "Der Akku zeigte 54 Prozent. Beim Einschalten erschien kurz Fehler E17, verschwand aber nach Neustart. Ruth Ganter erklärte, die Anzeige sei nach kalten Nächten schon zweimal aufgetreten; das Rad habe danach normal funktioniert."]), ("2. Laden und Aufbewahren", ["Ruth Ganter bat darum, den Akku in der Waschküche auf der Steinablage und nicht in der Wohnung zu laden. Das Ersatzgerät passe zum Stecker und sei im Frühjahr bereits benutzt worden. Eine schriftliche Anleitung wurde nicht übergeben.", "Im Keller hängt ein Aushang der Hausverwaltung, Akkus nicht unbeaufsichtigt über Nacht zu laden. Jonas Maier kannte den Aushang, hielt die Waschküche aber für den von der Eigentümerin gewünschten Ort."])], signer="Ruth Ganter", signer_role="Verleiherin")
    record(d, "02_feuerwehr_einsatzbericht.docx", org="Feuerwehr Freiburg", strapline="Amt für Brand- und Katastrophenschutz", contact="Eschholzstraße 118 · 79115 Freiburg\nTelefon 0761 201 3315 · leitstelle@feuerwehr.freiburg.de", title="Einsatzbericht Kellerbrand Schwarzwaldstraße 221", metadata=[("Einsatznummer", "FR-2026-0614-00418"), ("Alarm", "14.06.2026, 02:18 Uhr"), ("Brand aus", "02:47 Uhr"), ("Einsatzleiter", "Brandamtmann Lars Michel")], sections=[("1. Lage", ["Rauch trat aus dem Kellerfenster zur Hofseite. Bewohner hatten das Gebäude verlassen. Der Brandherd lag in der gemeinschaftlichen Waschküche auf und unter einer Steinablage. Dort befanden sich ein Fahrradakku, ein Ladegerät und eine vierfache Steckdosenleiste.", "Der Akku war thermisch durchgegangen. Zwei Waschmaschinen, Leitungen und Kellerabteile wurden durch Hitze und Ruß beschädigt. Eine Ausbreitung auf Wohnungen erfolgte nicht. Bewohnerin Elif Yalçın wurde wegen Rauchreizung ambulant untersucht."]), ("2. Sicherung", ["Akku, Ladegerät und Steckdosenleiste wurden getrennt verpackt und an die Polizei übergeben. Das Ladegerät trug ein beschädigtes Typenschild mit Ausgang 42V 4A. Auf dem Akku war als zulässiger Ladestrom 3A angegeben.", "Die Stromleiste lag unter der Ablage und wies an einer Buchse starke Schmelzspuren auf. Ob diese Ursache oder Folge des Brandes waren, konnte vor Ort nicht festgestellt werden."])], signer="Lars Michel", signer_role="Brandamtmann")
    record(d, "03_brandgutachten_zwischenstand.docx", org="Sachverständigenbüro Dr. Sauter", strapline="Elektrotechnik und Brandursachen", contact="Basler Straße 74 · 79100 Freiburg\nTelefon 0761 707 18 40 · gutachten@sauter-brand.de", title="Technischer Zwischenbericht", metadata=[("Auftrag", "Badische Gebäudeversicherung"), ("Gutachten", "SB-26-771"), ("Besichtigung", "16.06.2026"), ("Stand", "29.06.2026")], sections=[("1. Befunde", ["Das Ersatzladegerät ist kein vom Fahrradhersteller freigegebenes Zubehör. Gemessene Ausgangsregelung war wegen Brandschadens nicht möglich. Der Akku enthält Zellen aus 2023; zwei Zellgruppen zeigen ältere Temperaturereignisse im Speicher, zuletzt am 4. Mai 2026.", "Die Steckdosenleiste war mit Ladegerät, Trockner und Gefrierschrank belegt. Der Trockner war zur Brandzeit ausgeschaltet, der Gefrierschrank in Betrieb. Die Leitungsschutzschaltung löste um 02:17:48 Uhr aus."]), ("2. Vorläufige Einordnung", ["Als Ausgangsbereiche kommen Akku, Ladegerät und Kontaktstelle der Steckdosenleiste in Betracht. Die stärkste thermische Einwirkung liegt am Akkuanschluss. Ein eindeutiger Primärlichtbogen ist im bisherigen Röntgenbild nicht nachweisbar.", "Für den Abschluss werden Herstellerdaten zu Fehler E17, Kaufnachweis des Ladegeräts und Angaben zum Ladebeginn benötigt. Das Gutachten trifft derzeit keine abschließende Ursachenzuordnung."])], signer="Dr.-Ing. Mara Sauter", signer_role="Öffentlich bestellte Sachverständige")
    record(d, "04_regressankuendigung_versicherung.docx", org="Badische Gebäudeversicherung VVaG", strapline="Sachschaden und Regress", contact="Kaiser-Joseph-Straße 188 · 79098 Freiburg\nTelefon 0761 381 0 · schaden@badische-gebaeude.de", title="Regressankündigung zum Schaden BG-26-18841", metadata=[("Versicherungsnehmer", "WEG Schwarzwaldstraße 221"), ("Schadentag", "14.06.2026"), ("Bisherige Zahlungen", "68400 EUR"), ("Adressaten", "Ruth Ganter und Jonas Maier")], sections=[("1. Regulierung", ["Die Versicherung hat Trocknung, Elektroarbeiten, Reinigung, zwei Waschmaschinen und Kellerinventar vorläufig mit 68400 EUR reguliert. Weitere Angebote für Maler- und Geruchsarbeiten liegen vor.", "Nach den bisherigen Feststellungen wurde ein nicht freigegebenes Ladegerät an einem Akku mit früheren Temperaturereignissen verwendet. Eigentümerin und Nutzer sollen erklären, wer Ladegerät auswählte, Ladevorgang startete und Warnhinweise kannte."]), ("2. Vorbehalt", ["Die Versicherung kündigt an, Ersatzansprüche nach Abschluss des Gutachtens zu prüfen. Eine Haftungsquote wird noch nicht genannt. Beide Adressaten sollen ihre privaten Haftpflichtversicherer informieren.", "Ruth Ganter meldete den Vorgang der Breisgau Haftpflicht, Jonas Maier der HanseDirekt. Beide Versicherer fordern das vollständige Gutachten an."])], signer="Carolin Heß", signer_role="Schadenreferentin")
    email(d, "05_email_verleiherin_fehler_e17.eml", sender="ruth.ganter@posteo.de", recipients=["jonas.maier@mailbox.org"], cc=[], date="Fri, 12 Jun 2026 18:06:00 +0200", subject="E-Bike / E17 und Ladegerät", message_id="<rg-veloria-202606121806@posteo.de>", body="Hallo Jonas,\n\nfalls E17 noch einmal kommt, schalte das Rad aus, nimm den Akku kurz heraus und setze ihn wieder ein. Das war bei mir im Mai nach einer kalten Nacht. Die Werkstatt meinte am Telefon, es könne ein Temperaturhinweis sein und ich solle beim nächsten Service den Akku mitbringen. Einen Termin hatte ich noch nicht.\n\nDas schwarze Ladegerät habe ich vor zwei Jahren für das alte Rad meines Mannes gekauft. Der Stecker passt und ich habe den Veloria-Akku damit im April einmal geladen. Bitte stell ihn auf die Steinplatte und deck nichts darüber.\n\nGute Fahrt\nRuth")
    email(d, "06_email_hausverwaltung_aushang.eml", sender="verwaltung@dreisam-haus.de", recipients=["eigentümer@schwarzwaldstrasse221.de"], cc=["hausmeister@dreisam-haus.de"], date="Mon, 2 Mar 2026 10:14:00 +0100", subject="Schwarzwaldstraße 221 / Laden von Fahrradakkus im Keller", message_id="<dh-ss221-akku-202603021014@dreisam-haus.de>", body="Sehr geehrte Eigentümerinnen und Eigentümer,\n\nnachdem in der Waschküche wiederholt Fahrradakkus über Nacht geladen wurden, hängt der Hausmeister heute einen Hinweis aus. Bitte verwenden Sie nur passende, unbeschädigte Ladegeräte, laden Sie nicht unbeaufsichtigt und entfernen Sie Akkus nach Ende des Ladevorgangs. Fluchtwege und Holzregale sind freizuhalten.\n\nDie Waschküche ist kein dauerhaft zugewiesener Ladeplatz. Wer dort ausnahmsweise lädt, muss die Hausordnung und Herstellerangaben beachten. Die Steckdosenleiste auf der Steinablage soll nur für Bügeleisen und vorübergehende Geräte genutzt werden; der Gefrierschrank erhält eine feste Wandsteckdose.\n\nMit freundlichen Grüßen\nDreisam Hausverwaltung GmbH\nTalstraße 41, 79102 Freiburg\nTelefon 0761 509 18 70")
    P.write_txt(d / "07_signal_chat_ladebeginn.txt", """Signal-Export · Jonas Maier / Ruth Ganter · 13.06.2026 bis 14.06.2026

13.06. 19:42 Jonas: Tour war gut, Akku noch 18 Prozent. Ich lade ihn unten und bringe Rad Montag.
13.06. 19:46 Ruth: Nimm bitte die Steinplatte und das schwarze Gerät. Nicht auf die Waschmaschine.
13.06. 22:08 Jonas: Ladegerät zeigt grün blinkend statt rot. Ist das normal?
13.06. 22:16 Ruth: Bei mir war erst rot und dann grün. Stecker noch mal fest rein. Wenn es heiß ist, ausstecken.
13.06. 22:21 Jonas: Handwarm, Akku selbst kühl. Jetzt rot. Ich gehe schlafen.
14.06. 02:23 Jonas: Feuerwehr ist da. Es brennt im Keller. Akku war an der Steckdosenleiste.
14.06. 02:31 Ruth: Oh Gott. Sind alle draußen? Bitte sag, dass es mein Rad ist.
14.06. 03:18 Jonas: Alle draußen, Elif beim Rettungswagen. Polizei nimmt Akku und Ladegerät mit.
""")
    P.write_csv(d / "08_schadenpositionen_versicherung.csv", ["Position", "Eigentuemer", "Neuwert_EUR", "Zeitwert_EUR", "Reguliert_EUR", "Beleg", "Status"], [["Elektroinstallation Keller", "WEG", "18200", "18200", "18200", "RG Elektro Huber", "gezahlt"], ["Trocknung und Reinigung", "WEG", "24600", "24600", "24600", "RG Klarraum", "gezahlt"], ["Geruchsneutralisierung Gemeinschaftsflächen", "WEG", "11200", "11200", "11200", "RG Klarraum 2", "gezahlt"], ["Malerarbeiten Kellerflur", "WEG", "8300", "8300", "8300", "RG Farbwerk", "gezahlt"], ["Sicherung und Sachverständigenkosten", "WEG", "3746", "3746", "3746", "BG-26-18841-A", "gezahlt"], ["Waschmaschine Bosch", "Elif Yalçın", "820", "410", "410", "Kaufbeleg 2021", "gezahlt"], ["Waschmaschine Miele", "Ruth Ganter", "1240", "744", "744", "Kaufbeleg 2022", "gezahlt"], ["Kellerinventar Abteil 8", "Jonas Maier", "3100", "1800", "1200", "Liste und Fotos", "teilweise"], ["E-Bike Veloria Tour 8", "Ruth Ganter", "3790", "2450", "0", "Rechnung 2023", "Haftpflicht offen"]])
